/* ================================================================
   NGG — APP-MODE STYLES
   Sign-in, dashboard, admin, book, motion. Loaded after styles.css.
   ================================================================ */

:root {
  --lime-ink: #2e4400;
}

/* ============================================================
   PAGE UI POLISH — unified eyebrows, headings, section spacing,
   button refinement. Loaded last so it wins on conflicts.
   ============================================================ */

/* Eyebrow — uppercase mono micro-label used everywhere. */
.eyebrow {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--eyebrow-fg, var(--gold-700));
  font-weight: 500;
}

/* Section heading rhythm */
.section-h {
  display: flex; flex-direction: column; gap: 14px;
  margin: 0 0 clamp(40px, 6vw, 64px);
  max-width: 760px;
}
.section-h h2 {
  font-family: var(--font-display);
  font-size: clamp(36px, 5.2vw, 64px);
  line-height: 1.02;
  letter-spacing: -0.025em;
  font-weight: 700;
  margin: 0;
}

/* Hairline divider used between sections that need a soft break. */
.hr-soft {
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, rgba(12,20,50,0.1) 25%, rgba(12,20,50,0.1) 75%, transparent 100%);
  border: none;
  margin: 0;
}

/* Button — this is the DEFINITION THAT SHIPS. It loads after styles.css and
   overrides the `.btn*` rules there, so treat this block as the effective
   source of truth for buttons (and `.chip`). If you ever unify the marketing
   and app looks into one, delete the duplicate block in styles.css. */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 999px;
  padding: 11px 22px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.005em;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  position: relative;
  text-decoration: none;
}
.btn-lg {
  padding: 15px 28px;
  font-size: 15px;
}
.btn-sm {
  padding: 8px 16px;
  font-size: 13px;
}
.btn-primary {
  background: var(--navy-900);
  color: white;
  box-shadow: 0 3px 0 #050a1e;
}
.btn-primary:hover {
  background: var(--navy-800);
  transform: translateY(-1px);
  box-shadow: 0 4px 0 #050a1e;
}
.btn-primary:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 #050a1e;
}
.btn-gold {
  background: var(--gold-500);
  color: var(--navy-900);
  box-shadow: 0 3px 0 #b07c12;
  font-weight: 700;
}
.btn-gold:hover {
  background: var(--gold-400);
  transform: translateY(-1px);
  box-shadow: 0 4px 0 #b07c12;
}
.btn-gold:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 #b07c12;
}
.btn-ghost {
  background: transparent;
  border: 1.5px solid rgba(12, 20, 50, 0.18);
  color: var(--ink-900);
}
.btn-ghost:hover {
  border-color: var(--navy-900);
  background: rgba(12, 20, 50, 0.04);
}
.btn-on-dark-ghost {
  background: transparent;
  border: 1.5px solid rgba(255, 255, 255, 0.2);
  color: white;
}
.btn-on-dark-ghost:hover {
  border-color: white;
  background: rgba(255, 255, 255, 0.06);
}
.btn:disabled, .btn[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}
.btn:disabled:not(#_):not(#_), .btn[disabled]:not(#_):not(#_) { transform: none; }

/* Chips — unify */
.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: rgba(12, 20, 50, 0.06);
  color: var(--ink-900);
}
.chip-gold { background: var(--gold-500); color: var(--navy-900); }
.chip-on-dark { background: rgba(255, 255, 255, 0.12); color: white; }
.chip-lime { background: var(--lime); color: var(--lime-ink); }
.chip-coral { background: var(--coral); color: white; }
.chip-plum { background: var(--plum); color: white; }
/* A centre that follows CACENTRE's locations list (domain/cac-locations.php). */
.chip-cac { margin-left: 8px; background: var(--navy-900); color: white; }
.chip-cac-not { margin-left: 8px; background: rgba(12, 20, 50, 0.06); color: var(--ink-700); }
.centres-cac-note { max-width: 72ch; background: rgba(12, 20, 50, 0.04); border: 1px solid rgba(12, 20, 50, 0.12); border-radius: 10px; padding: 10px 12px; }
.centre-cac-fixed { flex: 1 1 200px; }
.centre-cac-lbl { display: block; font-size: 12px; font-weight: 600; color: var(--ink-700); margin-bottom: 4px; }
.centre-cac-val { margin: 0; min-height: 38px; display: flex; align-items: center; gap: 8px; color: var(--ink-900); }

/* Cards — soft, intentional shadow */
.card {
  background: white;
  border-radius: 18px;
  border: 1px solid rgba(12, 20, 50, 0.05);
  box-shadow: 0 1px 0 rgba(12, 20, 50, 0.02);
}

/* Section rhythm — generous vertical pacing */
.section {
  padding: clamp(72px, 9vw, 120px) 0;
}
.section-tight {
  padding: clamp(48px, 6vw, 72px) 0;
}

/* ============================================================
   1b. GLOBAL MICRO-INTERACTIONS
   Subtle hover lift + active press on every card/CTA the site
   already classes. Respects reduced-motion automatically.
   ============================================================ */
@media (prefers-reduced-motion: no-preference) and (hover: hover) {
  .btn,
  .nav-auth-trigger,
  .footer-status-pill,
  .dash-shortcut,
  .admin-tile,
  .admin-quick-btn,
  .admin-card {
    transition: transform 0.18s cubic-bezier(0.2, 0.7, 0.2, 1),
                box-shadow 0.18s ease,
                background 0.18s ease,
                color 0.18s ease,
                border-color 0.18s ease;
  }
  .btn:hover {
    transform: translateY(-1px);
  }
  .btn:active {
    transform: translateY(1px);
    transition-duration: 0.05s;
  }
  /* Underline on every text link in cards on hover */
  .footer-link::after,
  .legal::after {
    content: "";
    display: block;
    height: 1px;
    background: currentColor;
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.22s cubic-bezier(0.2, 0.7, 0.2, 1);
    margin-top: 1px;
  }
  .footer-link:hover::after,
  .legal:hover::after {
    transform: scaleX(1);
  }
  /* Chip pulse on hover */
  .chip {
    transition: transform 0.18s ease;
  }
  .chip:hover { transform: translateY(-1px); }
}

/* Smooth scroll for in-page anchors (already on html but reinforce) */
html { scroll-behavior: smooth; }

/* ============================================================
   1c. TILT — pointer-tracked 3D card rotation
   ============================================================ */
.tilt {
  display: block;
  transform-style: preserve-3d;
  transition: transform 0.32s cubic-bezier(0.2, 0.7, 0.2, 1);
  will-change: transform;
  position: relative;
  isolation: isolate;
}
.tilt > * { transform-style: preserve-3d; }
.tilt.has-glare::after {
  content: "";
  position: absolute; inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at var(--tilt-gx, 50%) var(--tilt-gy, 50%),
                              rgba(255, 255, 255, var(--tilt-glare, 0)) 0%, transparent 60%);
  border-radius: inherit;
  z-index: 2;
  transition: background 0.18s ease;
  mix-blend-mode: overlay;
}
@media (hover: none), (prefers-reduced-motion: reduce) {
  .tilt:not(#_):not(#_) { transform: none; }
  .tilt.has-glare::after { display: none; }
}

/* ============================================================
   1d. PHOTO FRAME — shimmer + blur-up for site-wide Photo
   ============================================================ */
.photo-frame {
  /* Shimmer placeholder until image loads. */
  background-image: linear-gradient(
    90deg,
    var(--cream-100) 0%,
    var(--cream-200) 50%,
    var(--cream-100) 100%
  );
  background-size: 200% 100%;
  animation: photo-shimmer 1.6s linear infinite;
}
.photo-frame.is-loaded {
  animation: none;
}
.photo-frame img {
  opacity: 0;
  filter: blur(8px) saturate(1.1);
  transform: scale(1.04);
  transition: opacity 0.55s ease, filter 0.55s ease, transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.photo-frame.is-loaded img {
  opacity: 1;
  filter: none;
  transform: none;
}
@keyframes photo-shimmer {
  from { background-position: 200% 0; }
  to   { background-position: -200% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .photo-frame { animation: none; }
  .photo-frame img { opacity: 1; filter: none; transform: none; transition: none; }
}

/* ============================================================
   1d2. BLUR-IMAGE — fade-in image loader (standalone)
   ============================================================ */
.blur-image {
  position: relative;
  overflow: hidden;
  border-radius: 12px;
  background: linear-gradient(135deg, #efe8d5 0%, #ddd3b9 100%);
}
.blur-image img {
  width: 100%; height: 100%;
  object-fit: cover;
  display: block;
  opacity: 0;
  filter: blur(10px) saturate(1.1);
  transform: scale(1.06);
  transition: opacity 0.6s ease, filter 0.6s ease, transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.blur-image.is-loaded img {
  opacity: 1;
  filter: none;
  transform: none;
}

/* ============================================================
   1f. COMMAND PALETTE
   ============================================================ */
.cmdk-scrim {
  position: fixed; inset: 0;
  background: rgba(10, 17, 48, 0.55);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  z-index: 240;
  display: grid;
  place-items: start center;
  padding: 96px 20px 32px;
  animation: signin-scrim-in 0.18s ease;
}
.cmdk {
  width: 100%; max-width: 600px;
  background: var(--paper);
  border-radius: 18px;
  box-shadow: 0 30px 80px -20px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  animation: cmdk-in 0.22s cubic-bezier(0.2, 0.7, 0.2, 1);
}
@keyframes cmdk-in {
  from { opacity: 0; transform: translateY(-16px) scale(0.98); }
  to   { opacity: 1; transform: none; }
}
.cmdk-input-wrap {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(12, 20, 50, 0.06);
}
.cmdk-icon { font-size: 18px; color: var(--ink-500); }
.cmdk-input {
  border: none; outline: none;
  background: transparent;
  font-family: inherit;
  font-size: 17px;
  color: var(--ink-900);
  width: 100%;
}
.cmdk-input::placeholder { color: var(--ink-500); }
.cmdk-esc {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  background: rgba(12, 20, 50, 0.06);
  padding: 4px 8px;
  border-radius: 5px;
  color: var(--ink-500);
}

.cmdk-list { max-height: 50vh; overflow-y: auto; padding: 6px 6px; }
.cmdk-group { padding: 6px 0; }
.cmdk-group + .cmdk-group { border-top: 1px solid rgba(12, 20, 50, 0.04); }
.cmdk-group-h {
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--ink-500);
  padding: 8px 16px 4px;
}
.cmdk-item {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  width: 100%;
  background: transparent;
  border: none;
  padding: 10px 14px;
  border-radius: 10px;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  color: var(--ink-900);
  transition: background 0.12s ease;
}
.cmdk-item:hover, .cmdk-item.is-active {
  background: rgba(245, 176, 38, 0.1);
}
.cmdk-item.is-active { box-shadow: inset 0 0 0 1px rgba(245, 176, 38, 0.35); }
.cmdk-item-icon {
  font-size: 16px;
  width: 30px; height: 30px;
  border-radius: 8px;
  background: white;
  display: grid; place-items: center;
  border: 1px solid rgba(12, 20, 50, 0.06);
  color: var(--ink-700);
}
.cmdk-item-body { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.cmdk-item-label { font-weight: 600; font-size: 14px; }
.cmdk-item-hint { font-size: 12px; color: var(--ink-500); }
.cmdk-item kbd {
  font-family: var(--font-mono);
  font-size: 10px;
  background: white;
  border: 1px solid rgba(12,20,50,0.08);
  border-radius: 4px;
  padding: 2px 6px;
  color: var(--ink-500);
  letter-spacing: 0.1em;
}
.cmdk-empty {
  padding: 32px 18px;
  text-align: center;
  color: var(--ink-500);
}
.cmdk-empty-h { font-weight: 700; }
.cmdk-empty-sub { font-size: 13px; margin-top: 4px; }
.cmdk-foot {
  display: flex; gap: 16px;
  padding: 10px 16px;
  border-top: 1px solid rgba(12, 20, 50, 0.06);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  color: var(--ink-500);
}
.cmdk-foot kbd {
  background: rgba(12,20,50,0.06);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 10px;
  margin-right: 4px;
}

/* Floating hint */
.cmdk-hint {
  position: fixed;
  /* Sit ABOVE the accessibility FAB (bottom-left) so the two never overlap. */
  left: 20px; bottom: 84px;
  z-index: 90;
  animation: cmdk-hint-in .3s ease both;
  background: white;
  border: 1px solid rgba(12, 20, 50, 0.08);
  border-radius: 999px;
  padding: 6px 10px 6px 8px;
  display: inline-flex; align-items: center; gap: 8px;
  font-family: inherit;
  font-size: 12px;
  color: var(--ink-700);
  box-shadow: 0 12px 30px -10px rgba(12, 20, 50, 0.18);
  cursor: pointer;
  opacity: 0.92;
  transition: opacity 0.18s ease, transform 0.18s ease;
}
.cmdk-hint:hover { opacity: 1; transform: translateY(-1px); }
.cmdk-hint kbd {
  font-family: var(--font-mono);
  font-size: 10px;
  background: rgba(12, 20, 50, 0.06);
  border-radius: 4px;
  padding: 2px 5px;
  margin-right: 2px;
  letter-spacing: 0.06em;
}
.cmdk-hint-text { color: var(--ink-500); }
.cmdk-hint-x { color: var(--ink-500); opacity: 0.55; padding: 0 4px; cursor: pointer; }
.cmdk-hint-x:hover { opacity: 1; }
@media (hover: none) { .cmdk-hint { display: none; } }
@keyframes cmdk-hint-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
/* Full-height app chrome (community): keep the corners clear. */
body.cm-app .cmdk-hint { display: none; }
body.cm-app .fab-top { display: none; }

/* ============================================================
   1. MOTION PRIMITIVES — used by motion.jsx
   ============================================================ */

.reveal {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.7s cubic-bezier(0.22, 0.61, 0.36, 1), transform 0.7s cubic-bezier(0.22, 0.61, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}
.reveal.is-visible { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  .reveal { opacity: 1; transform: none; transition: none; }
}

.kinetic { display: inline-block; }
.kinetic-part {
  display: inline-block;
  opacity: 0;
  transform: translateY(0.4em);
  animation: ki-in 0.7s cubic-bezier(0.22, 0.61, 0.36, 1) forwards;
  animation-delay: calc(var(--ki-i) * 35ms + var(--ki-d) * 1ms);
}
@keyframes ki-in {
  to { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .kinetic-part { opacity: 1; transform: none; animation: none; }
}

.magnetic {
  display: inline-block;
  transition: transform 0.22s cubic-bezier(0.22, 0.61, 0.36, 1);
  will-change: transform;
}

.page-transition {
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.35s ease, transform 0.35s ease;
}
.page-transition.is-show { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .page-transition { opacity: 1; transform: none; transition: none; }
}

/* ============================================================
   2. SIGN-IN MODAL
   ============================================================ */

/* On the Control Room v2 design system: the --cr-* tokens are declared for
   .signin-scrim with the Control Room's own (see "The Control Room v2 tokens").
   One job per screen; the card is the only thing on the page. */
.signin-scrim {
  position: fixed; inset: 0; z-index: 200;
  display: grid; place-items: center; padding: 16px;
  background: rgba(11, 11, 12, .45);
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  font-family: var(--cr-font); color: var(--cr-ink); -webkit-font-smoothing: antialiased;
  animation: signin-scrim-in .18s var(--cr-ease);
}
@keyframes signin-scrim-in { from { opacity: 0; } to { opacity: 1; } }
.signin-scrim *, .signin-scrim *::before, .signin-scrim *::after { box-sizing: border-box; }
.signin-card {
  position: relative; width: 100%; max-width: 400px; max-height: calc(100dvh - 32px); overflow: auto;
  background: var(--cr-bg); border-radius: var(--cr-r-xl); box-shadow: var(--cr-sh-cmd);
  padding: 36px 32px 24px;
  animation: signin-card-in .22s var(--cr-ease);
}
@keyframes signin-card-in { from { opacity: 0; transform: translateY(8px) scale(.98); } to { opacity: 1; transform: none; } }
.signin-card :focus-visible { outline: 2px solid var(--cr-ink); outline-offset: 2px; }

.signin-close {
  position: absolute; top: 12px; right: 12px; width: 36px; height: 36px; display: inline-grid; place-items: center;
  border: 0; border-radius: var(--cr-r); background: transparent; color: var(--cr-muted-3); font-size: 18px; cursor: pointer;
}
.signin-close:hover { background: var(--cr-s2); color: var(--cr-ink); }

.signin-head { display: flex; flex-direction: column; align-items: center; text-align: center; margin-bottom: 28px; }
.signin-logo { width: 40px; height: 40px; border-radius: var(--cr-r); margin-bottom: 18px; }
.signin-headline { margin: 0; font-size: 24px; line-height: 1.2; font-weight: 600; letter-spacing: -.02em; color: var(--cr-ink); }
.signin-sub { margin: 8px 0 0; max-width: 300px; font-size: 14px; line-height: 1.5; color: var(--cr-muted-2); }
.signin-sub b { color: var(--cr-ink); font-weight: 600; }

.signin-form { display: flex; flex-direction: column; }
/* The honeypot (auth.jsx): off-screen, not display:none — some scripts skip
   fields they can tell are hidden. aria-hidden + tabindex -1 keep it from
   every person, screen-reader users included. */
.signin-trap { position: absolute; left: -10000px; top: auto; width: 1px; height: 1px; overflow: hidden; }
.signin-label { display: block; margin: 0 0 6px; font-size: 13px; font-weight: 500; color: var(--cr-text); }
.signin-label-row { display: flex; align-items: baseline; justify-content: space-between; margin-top: 16px; }
.signin-label-row .signin-label { margin-bottom: 6px; }
.signin-hint { display: block; min-height: 0; margin: 6px 0 0; font-size: 12.5px; line-height: 1.45; color: var(--cr-text); }
.signin-hint:empty { margin: 0; }
.signin-hint.is-warn { color: #7a5600; }
.signin-hint .signin-link { font-size: 12.5px; padding: 0; }
.signin-input {
  width: 100%; height: 44px; padding: 0 14px;
  border: 1px solid var(--cr-line-strong); border-radius: var(--cr-r); background: var(--cr-bg);
  font: inherit; font-size: 15px; color: var(--cr-ink); outline: none;
  transition: border-color .15s var(--cr-ease), box-shadow .15s var(--cr-ease);
}
.signin-input::placeholder { color: var(--cr-faint); }
.signin-input:hover { border-color: var(--cr-line-hover); }
.signin-input:focus, .signin-input:focus-visible { outline: none; border-color: var(--cr-ink); box-shadow: 0 0 0 1px var(--cr-ink); }
.signin-input.is-bad { border-color: var(--cr-err-line); }
.signin-input.is-bad:focus { box-shadow: 0 0 0 3px rgba(194, 52, 52, .12); }
.signin-input + .signin-label, .signin-code + .signin-label, .signin-pw + .signin-label, .signin-who + .signin-label, .signin-note + .signin-label { margin-top: 16px; }
/* Kept for the portal gate's sign-in card, which still uses it. */
.signin-otp { font-family: var(--cr-mono); font-size: 20px; letter-spacing: .3em; text-align: center; }
.signin-err { padding: 10px 12px; border-radius: var(--cr-r); background: var(--cr-bad-bg); color: var(--cr-bad-fg); font-size: 13px; line-height: 1.45; }

.signin-pw { position: relative; }
.signin-pw .signin-input { padding-right: 46px; }
.signin-eye {
  position: absolute; right: 4px; top: 4px; width: 36px; height: 36px; display: inline-grid; place-items: center;
  border: 0; border-radius: var(--cr-r-sm); background: transparent; color: var(--cr-muted-3); font-size: 18px; cursor: pointer;
}
.signin-eye:hover { color: var(--cr-ink); }

/* The code: six boxes, one digit each. */
.signin-code { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 8px; }
.signin-code .signin-digit:nth-child(3) { margin-right: 6px; }
.signin-digit {
  width: 100%; height: 52px; padding: 0; text-align: center;
  border: 1px solid var(--cr-line-strong); border-radius: var(--cr-r); background: var(--cr-bg);
  font: 500 22px var(--cr-mono); color: var(--cr-ink); caret-color: var(--cr-ink); outline: none;
  transition: border-color .15s var(--cr-ease), box-shadow .15s var(--cr-ease);
}
.signin-digit:hover { border-color: var(--cr-line-hover); }
.signin-digit:focus, .signin-digit:focus-visible { outline: none; border-color: var(--cr-ink); box-shadow: 0 0 0 1px var(--cr-ink); }
.signin-code.is-bad .signin-digit { border-color: var(--cr-err-line); }

.signin-who { display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 6px 0 8px; border: 1px solid var(--cr-line); border-radius: var(--cr-r); background: var(--cr-s1); }
.signin-who-av { width: 28px; height: 28px; display: inline-grid; place-items: center; flex: none; border-radius: 50%; background: var(--cr-ink); color: var(--cr-on-ink); font-size: 12px; font-weight: 600; }
.signin-who-id { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; font-weight: 500; }
.signin-change { height: 32px; padding: 0 10px; border: 0; border-radius: var(--cr-r-sm); background: transparent; font: inherit; font-size: 13px; font-weight: 500; color: var(--cr-muted-2); cursor: pointer; }
.signin-change:hover { background: var(--cr-s3); color: var(--cr-ink); }

.signin-ferr { display: flex; gap: 6px; align-items: flex-start; margin: 8px 0 0; font-size: 13px; line-height: 1.4; color: var(--cr-bad-fg); }
.signin-ferr .ph { font-size: 15px; flex: none; margin-top: 1px; }
.signin-help { margin: 8px 0 0; font-size: 12.5px; color: var(--cr-muted-3); }
.signin-help--wait { line-height: 1.5; }
.signin-note { display: flex; gap: 8px; align-items: flex-start; margin: 0 0 4px; padding: 10px 12px; border-radius: var(--cr-r); background: var(--cr-warn-bg); color: var(--cr-warn-fg); font-size: 13px; line-height: 1.4; }
.signin-who + .signin-note { margin-top: 16px; }
.signin-note .ph { font-size: 15px; flex: none; margin-top: 1px; }

.signin-remember { display: flex; align-items: center; gap: 10px; margin-top: 14px; font-size: 13.5px; color: var(--cr-muted); cursor: pointer; user-select: none; }
.signin-remember input { width: 16px; height: 16px; margin: 0; accent-color: var(--cr-ink); cursor: pointer; flex: none; }

/* The one solid button on the card. */
.signin-submit {
  display: inline-flex; align-items: center; justify-content: center; width: 100%; height: 44px; margin-top: 20px;
  border: 0; border-radius: var(--cr-r); background: var(--cr-ink); color: var(--cr-on-ink);
  font: inherit; font-size: 15px; font-weight: 600; cursor: pointer; transition: background .15s var(--cr-ease), opacity .15s var(--cr-ease);
}
.signin-submit:hover:not(:disabled) { background: #26262a; }
.signin-submit:disabled { opacity: .35; cursor: not-allowed; }
.signin-submit[aria-busy="true"] { opacity: 1; }
.signin-spin { width: 18px; height: 18px; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: signin-spin .7s linear infinite; }
@keyframes signin-spin { to { transform: rotate(360deg); } }

.signin-alts { display: flex; justify-content: center; margin-top: 12px; }
.signin-link {
  min-height: 32px; padding: 0 4px; border: 0; background: transparent;
  font: inherit; font-size: 13.5px; font-weight: 500; color: var(--cr-muted-2); cursor: pointer;
}
.signin-link:hover:not(:disabled) { color: var(--cr-ink); text-decoration: underline; text-underline-offset: 3px; }
.signin-link:disabled { color: var(--cr-faint); cursor: default; }
.signin-link--sm { min-height: 24px; font-size: 13px; }

.signin-foot { margin: 24px 0 0; font-size: 13px; color: var(--cr-muted-3); text-align: center; }
.signin-foot a { color: var(--cr-ink); font-weight: 500; text-decoration: underline; text-decoration-color: var(--cr-line-hover); text-underline-offset: 3px; }
.signin-foot a:hover { text-decoration-color: currentColor; }
@media (max-width: 420px) { .signin-card { padding: 32px 20px 20px; } .signin-code { gap: 6px; } }
@media (pointer: coarse) { .signin-link, .signin-close, .signin-eye, .signin-change { min-height: 44px; min-width: 44px; } .signin-input { height: 48px; font-size: 16px; } .signin-digit { height: 56px; } }
@media (prefers-reduced-motion: reduce) { .signin-scrim, .signin-card { animation: none; } .signin-spin { animation-duration: 2s; } }

/* ============================================================
   3. NAV AUTH SLOT
   ============================================================ */

.nav-auth-loading {
  width: 86px; height: 32px;
  background: rgba(12,20,50,0.05);
  border-radius: 8px;
  animation: shimmer 1.4s linear infinite;
}
@keyframes shimmer { 0%,100%{opacity:.6} 50%{opacity:1} }

.nav-auth { position: relative; }
.nav-auth-trigger {
  display: inline-flex; align-items: center; gap: 8px;
  min-height: 44px;
  background: transparent;
  border: 1.5px solid rgba(12,20,50,0.12);
  border-radius: 999px;
  padding: 4px 12px 4px 4px;
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  color: var(--ink-900);
  transition: border-color 0.16s ease;
}
.nav-auth-trigger:hover { border-color: var(--navy-900); }
.nav-auth-avatar {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--navy-900); color: white;
  display: grid; place-items: center;
  font-weight: 700; font-size: 13px;
}
.nav-auth-name { font-weight: 600; }
.nav-auth-chevron { font-size: 10px; color: var(--ink-500); }
.nav-auth-menu {
  position: absolute; top: calc(100% + 8px); right: 0;
  background: white;
  border-radius: 14px;
  box-shadow: 0 18px 50px -12px rgba(12, 20, 50, 0.3);
  border: 1px solid rgba(12, 20, 50, 0.06);
  min-width: 240px; padding: 8px;
  z-index: 50;
  animation: menu-in 0.18s ease;
}
@keyframes menu-in { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }
.nav-auth-menu-head { padding: 10px 14px 12px; border-bottom: 1px solid rgba(12,20,50,0.06); margin-bottom: 6px; }
.nav-auth-menu-name { font-weight: 700; }
.nav-auth-menu-id { font-size: 10px; color: var(--ink-500); margin-top: 2px; }
.nav-auth-menu-item {
  display: block; width: 100%;
  background: transparent; border: none; text-align: left;
  padding: 10px 14px; border-radius: 8px;
  font-family: inherit; font-size: 14px;
  cursor: pointer;
  color: var(--ink-900);
}
.nav-auth-menu-item:hover { background: rgba(12,20,50,0.05); }
.nav-auth-menu-admin { color: var(--gold-500); font-weight: 600; }
.nav-auth-menu-divider { height: 1px; background: rgba(12,20,50,0.06); margin: 6px 0; }
.nav-auth-menu-danger { color: var(--coral); }

/* Notifications bell */
.nav-bell { position: relative; }
.nav-bell-btn { position: relative; width: 44px; height: 44px; border-radius: 50%; border: 1.5px solid rgba(12,20,50,0.12); background: transparent; cursor: pointer; font-size: 16px; line-height: 1; display: grid; place-items: center; transition: border-color .16s ease, background .16s ease; }
.nav-bell-btn:hover { border-color: var(--navy-900); background: rgba(12,20,50,0.04); }
.nav-bell-badge { position: absolute; top: -3px; right: -3px; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 999px; background: var(--coral,#e4032b); color: #fff; font-size: 10px; font-weight: 800; display: grid; place-items: center; border: 2px solid var(--paper,#fbf7ed); box-sizing: border-box; }
.nav-bell-menu { position: absolute; top: calc(100% + 8px); right: 0; width: 340px; max-width: 90vw; background: #fff; border-radius: 14px; box-shadow: 0 18px 50px -12px rgba(12,20,50,0.3); border: 1px solid rgba(12,20,50,0.06); z-index: 60; animation: menu-in 0.18s ease; overflow: hidden; }
.nav-bell-head { display: flex; align-items: center; justify-content: space-between; padding: 13px 16px; border-bottom: 1px solid rgba(12,20,50,0.07); font-family: var(--font-display); font-weight: 800; font-size: 15px; color: var(--ink-900,#0a1130); }
.nav-bell-all { background: none; border: none; cursor: pointer; font: inherit; font-size: 12px; font-weight: 600; color: #3b5bdb; }
.nav-bell-list { max-height: 420px; overflow-y: auto; }
.nav-bell-empty { padding: 34px 20px; text-align: center; color: var(--ink-500,#8088a6); font-size: 14px; }
.nav-bell-item { position: relative; display: flex; gap: 11px; width: 100%; text-align: left; background: none; border: none; border-bottom: 1px solid rgba(12,20,50,0.05); cursor: pointer; padding: 12px 16px; font: inherit; }
.nav-bell-item:hover { background: rgba(12,20,50,0.04); }
.nav-bell-item.is-unread { background: rgba(59,91,219,0.05); }
.nav-bell-ic { width: 30px; height: 30px; flex: none; border-radius: 8px; background: rgba(12,20,50,0.06); display: grid; place-items: center; font-size: 14px; font-weight: 800; color: #3b5bdb; }
.nav-bell-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.nav-bell-title { font-size: 13.5px; font-weight: 700; color: var(--ink-900,#0a1130); }
.nav-bell-text { font-size: 12.5px; color: var(--ink-500,#5a6488); line-height: 1.4; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.nav-bell-ago { font-family: var(--font-mono); font-size: 10.5px; color: #a0a6bd; margin-top: 2px; }
.nav-bell-dot { position: absolute; top: 15px; right: 14px; width: 8px; height: 8px; border-radius: 50%; background: var(--coral,#e4032b); }

/* Mobile drawer auth */
.drawer-auth {
  display: flex; align-items: center; gap: 12px;
  margin: 12px 0 6px;
  padding: 12px;
  background: rgba(12,20,50,0.04);
  border-radius: 12px;
}
.drawer-auth-avatar {
  width: 40px; height: 40px; border-radius: 50%;
  background: var(--navy-900); color: white;
  display: grid; place-items: center;
  font-weight: 700;
}
.drawer-auth-name { font-weight: 700; }
.drawer-auth-id { font-size: 10px; color: var(--ink-500); margin-top: 2px; }
.nav-link-admin { font-weight: 600; }
.nav-link-admin:not(#_):not(#_) { color: var(--gold-500); }
.nav-link-danger:not(#_):not(#_) { color: var(--coral); }

/* ============================================================
   4. DASHBOARD — signed-out hero
   ============================================================ */

.signed-out-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 64px;
  align-items: center;
}
@media (max-width: 820px) {
  .signed-out-grid { gap: 36px; }
  .signed-out-grid:not(#_):not(#_) { grid-template-columns: minmax(0, 1fr); }
}
.signed-out-h1 {
  font-size: clamp(48px, 8vw, 96px);
  line-height: 0.96;
  letter-spacing: -0.03em;
  margin: 16px 0 0;
}
.signed-out-p {
  margin-top: 22px;
  font-size: 18px;
  line-height: 1.55;
  color: var(--ink-500);
  max-width: 540px;
}
.signed-out-cta {
  display: flex; gap: 12px; margin-top: 28px; flex-wrap: wrap;
}
.signed-out-list {
  list-style: none; padding: 0; margin: 36px 0 0;
  display: flex; flex-direction: column; gap: 10px;
  font-size: 15px;
}
.signed-out-list li {
  display: flex; align-items: center; gap: 12px;
  color: var(--ink-700);
}
.signed-out-list li span {
  display: inline-block;
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--gold-500);
  flex-shrink: 0;
}

.signed-out-preview {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: 24px;
  background: linear-gradient(135deg, var(--navy-900) 0%, var(--navy-700) 100%);
  overflow: hidden;
}
.signed-out-card {
  position: absolute; inset: 32px;
  background: white;
  border-radius: 18px;
  padding: 22px;
  display: flex; flex-direction: column; gap: 12px;
  box-shadow: 0 20px 50px -10px rgba(0,0,0,0.4);
}
.signed-out-card-bar {
  height: 12px;
  background: rgba(12,20,50,0.1);
  border-radius: 6px;
  width: 100%;
}
.signed-out-card-bar.w70 { width: 70%; }
.signed-out-card-bar.w50 { width: 50%; }
.signed-out-card-grid {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(2, 1fr);
  gap: 8px;
