}
.signed-out-card-grid > div {
  background: rgba(12,20,50,0.08);
  border-radius: 10px;
}
.signed-out-card-blur {
  position: absolute; left: 0; right: 0; bottom: 0; height: 50%;
  background: linear-gradient(180deg, transparent 0%, rgba(12,20,50,0.85) 100%);
  backdrop-filter: blur(6px);
}

/* ============================================================
   5. DASHBOARD — signed-in live
   ============================================================ */

.dash-spinner {
  width: 32px; height: 32px;
  border: 3px solid rgba(12,20,50,0.1);
  border-top-color: var(--navy-900);
  border-radius: 50%;
  margin: 0 auto;
  animation: dash-spin 0.9s linear infinite;
}
@keyframes dash-spin { to { transform: rotate(360deg); } }

/* Skeleton placeholders — shimmer in the dashboard's real layout while
   the first payload loads, so content fills in place (no spinner→grid jump). */
.dash-skel {
  background: linear-gradient(90deg,
    rgba(12,20,50,0.06) 25%,
    rgba(12,20,50,0.12) 50%,
    rgba(12,20,50,0.06) 75%);
  background-size: 200% 100%;
  animation: dash-skel-shine 1.4s ease-in-out infinite;
  border-radius: 8px;
}
.dash-hero .dash-skel {
  background: linear-gradient(90deg,
    rgba(255,255,255,0.08) 25%,
    rgba(255,255,255,0.18) 50%,
    rgba(255,255,255,0.08) 75%);
  background-size: 200% 100%;
}
.dash-skel-avatar { width: 64px; height: 64px; border-radius: 50%; flex-shrink: 0; }
.dash-skel-line { border-radius: 6px; }
.dash-skel-chip { width: 84px; height: 24px; border-radius: 999px; }
.dash-skel-card { min-height: 120px; }
@keyframes dash-skel-shine {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .dash-skel { animation: none; }
}

/* Tiny "refreshing" pip next to the greeting during a background poll. */
.dash-refreshing {
  display: inline-block;
  width: 9px; height: 9px;
  margin-left: 8px;
  border: 1.5px solid rgba(255,255,255,0.35);
  border-top-color: var(--gold-400);
  border-radius: 50%;
  vertical-align: middle;
  animation: dash-spin 0.8s linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .dash-refreshing { animation: none; opacity: 0.5; }
}

.dash-hero {
  background: linear-gradient(135deg, var(--navy-900) 0%, var(--navy-700) 100%);
  color: white;
  padding: 56px 0 72px;
  position: relative;
  overflow: hidden;
}
.dash-hero::before {
  content: "";
  position: absolute; top: -40%; right: -10%;
  width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(245, 176, 38, 0.15) 0%, transparent 70%);
  pointer-events: none;
}
.dash-hero-row {
  display: flex; justify-content: space-between; align-items: flex-end; gap: 24px;
  flex-wrap: wrap;
  position: relative; z-index: 1;
}
.dash-hero-id { display: flex; align-items: flex-end; gap: 20px; }
.dash-hero-meta {
  font-size: 10px;
  letter-spacing: 0.22em;
  color: rgba(255, 255, 255, 0.5);
  margin-bottom: 6px;
}
.dash-hero-name {
  font-family: var(--font-display);
  font-size: clamp(48px, 8vw, 84px);
  font-weight: 700;
  line-height: 0.95;
  margin: 0;
  letter-spacing: -0.03em;
}
.dash-hero-sub {
  display: flex; gap: 8px; margin-top: 14px; flex-wrap: wrap;
}
.dash-hero-actions {
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap;
}

.dash-session-badge {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 16px;
  padding: 14px 20px;
  min-width: 220px;
}
.dash-session-num {
  font-family: var(--font-display);
  font-size: 44px;
  font-weight: 700;
  line-height: 1;
  margin-top: 4px;
}
.dash-session-unit {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  color: rgba(255, 255, 255, 0.55);
  margin-left: 4px;
}

.dash-section { padding: 56px 0 96px; background: var(--cream-50); }

.dash-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);
  gap: 28px;
}
@media (max-width: 980px) {
  .dash-grid { grid-template-columns: minmax(0, 1fr); }
}

.dash-main, .dash-rail { display: flex; flex-direction: column; gap: 20px; }

/* Every control on this screen clears 44px on a phone.
   They cleared WCAG 2.5.8's 24×24 already, so none of this was a conformance
   failure — it was `btn-sm` at 32–34px on a page a member operates one-handed
   on a bus, while the rest of the product holds 44. The primary two went
   first; the rest followed, because "secondary" is not a reason for a control
   to be harder to hit, only a reason for it to be quieter. */
@media (max-width: 600px) {
  .ngg-dash .btn-sm,
  .dash-mission-cta, .dash-journal-save, .dash-assign-start,
  .dash-event-rsvp, .dash-account-toggle, .ngg-side-toggle { min-height: 44px; padding-inline: 16px; }
  /* The ID-card downloads sit two-up in a 280px card, so they take the height
     without the extra inline padding that would wrap their labels. */
  .dash-idcard-actions .btn-sm { padding-inline: 10px; }
}

.dash-card {
  background: white;
  border-radius: 18px;
  padding: 24px 24px 22px;
  border: 1px solid rgba(12, 20, 50, 0.05);
}
.dash-card-head {
  display: flex; justify-content: space-between; align-items: flex-start;
  gap: 16px;
  margin-bottom: 18px;
}
.dash-card-h {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  line-height: 1;
  margin: 6px 0 0;
  letter-spacing: -0.02em;
}
.dash-card-h-sm {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  margin: 0;
  letter-spacing: -0.01em;
}

/* Today's missions */
.dash-today-tally {
  display: flex; align-items: baseline; gap: 4px;
  font-family: var(--font-display);
}
.dash-today-tally-n { font-size: 28px; font-weight: 800; }
.dash-today-tally-d { font-size: 13px; color: var(--ink-500); font-weight: 500; }

.dash-mission-group { margin-top: 6px; }
.dash-mission-group-h {
  font-size: 10px; letter-spacing: 0.2em;
  color: var(--ink-500);
  margin: 18px 0 10px;
  padding-top: 12px;
  border-top: 1px dashed rgba(12,20,50,0.1);
}

.dash-mission {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid rgba(12,20,50,0.05);
}
.dash-mission:last-child { border-bottom: none; }
.dash-mission-icon {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--cream-100);
  display: grid; place-items: center;
  font-family: var(--font-display);
  color: var(--navy-900);
  font-size: 16px; font-weight: 700;
}
.dash-mission.is-done .dash-mission-icon { background: var(--lime); color: var(--lime-ink); }
.dash-mission.is-disabled .dash-mission-icon { background: rgba(245, 176, 38, 0.18); color: var(--gold-500); }
.dash-mission-title { font-weight: 700; font-size: 16px; }
.dash-mission-prompt { font-size: 14px; color: var(--ink-500); margin-top: 3px; line-height: 1.45; }
.dash-mission-meta { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.12em; color: var(--ink-500); margin-top: 6px; display: flex; gap: 6px; flex-wrap: wrap; }
.dash-mission-cta { white-space: nowrap; }
.dash-mission.is-done { opacity: 0.6; }
.dash-mission.is-done .dash-mission-title { text-decoration: line-through; }

.dash-empty {
  display: flex; align-items: center; gap: 18px;
  padding: 24px 0;
}
.dash-empty-num {
  font-family: var(--font-display);
  font-size: 64px; font-weight: 800;
  color: var(--cream-200);
  line-height: 1;
}
.dash-empty-text { color: var(--ink-500); font-size: 15px; line-height: 1.5; }

/* Stats card */
/* Four fixed columns put "1860" in a 51px cell inside the rail, where it
   overflowed into BADGES and the two numbers read as one — "1860 2" looked
   like 18602. auto-fit reflows to 2×2 rather than colliding, and the number
   is sized to fit the narrowest cell that still holds four across. */
.dash-stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(70px, 1fr));
  gap: 12px;
  margin: 4px 0 18px;
}
.dash-stat {}
.dash-stat-l { font-size: 9px; letter-spacing: 0.2em; color: var(--ink-500); }
.dash-stat-n {
  font-family: var(--font-display);
  font-size: 28px; font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  margin-top: 4px;
  color: var(--navy-900);
}
.dash-stat-u { font-size: 14px; color: var(--ink-500); font-weight: 500; margin-left: 2px; }

.dash-xp-bar {
  height: 8px;
  background: rgba(12,20,50,0.08);
  border-radius: 999px;
  overflow: hidden;
  margin-top: 14px;
}
.dash-xp-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--lime) 0%, var(--gold-500) 100%);
  border-radius: 999px;
  transition: width 0.6s cubic-bezier(0.22, 0.61, 0.36, 1);
}
.dash-xp-meta {
  display: flex; justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--ink-500);
  letter-spacing: 0.12em;
  margin-top: 8px;
}

/* Mentor */
.dash-mentor-row { display: flex; gap: 14px; align-items: center; margin-top: 12px; }
.dash-mentor-avatar {
  width: 56px; height: 56px; border-radius: 50%;
  object-fit: cover; border: 2px solid var(--gold-500);
}
.dash-mentor-avatar-fallback {
  display: grid; place-items: center;
  background: var(--navy-900); color: white;
  font-family: var(--font-display); font-weight: 800;
}
.dash-mentor-name { font-weight: 700; font-size: 16px; }
.dash-mentor-meta { font-family: var(--font-mono); font-size: 11px; color: var(--ink-500); margin-top: 2px; }
.dash-mentor-bio { font-size: 14px; line-height: 1.5; color: var(--ink-700); margin-top: 14px; }

/* Events */
.dash-events { display: flex; flex-direction: column; gap: 12px; }
.dash-event {
  display: grid;
  grid-template-columns: 56px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid rgba(12,20,50,0.05);
}
.dash-event:last-child { border-bottom: none; }
.dash-event-date {
  background: var(--navy-900); color: white;
  border-radius: 12px;
  padding: 8px 0;
  text-align: center;
}
.dash-event-dd {
  font-family: var(--font-display);
  font-size: 22px; font-weight: 800; line-height: 1;
}
.dash-event-mm { font-size: 9px; letter-spacing: 0.2em; color: var(--gold-400); margin-top: 2px; }
.dash-event-title { font-weight: 700; font-size: 14px; }
.dash-event-meta { font-family: var(--font-mono); font-size: 10px; color: var(--ink-500); margin-top: 2px; letter-spacing: 0.1em; }

/* Notifications */
.dash-notes { display: flex; flex-direction: column; gap: 4px; }
.dash-note {
  display: flex; gap: 12px; align-items: flex-start;
  background: transparent; border: none;
  font-family: inherit; text-align: left;
  width: 100%; padding: 10px 12px;
  border-radius: 12px;
  cursor: pointer;
  color: var(--ink-900);
  transition: background 0.14s ease;
}
.dash-note:hover { background: var(--cream-50); }
.dash-note.is-unread { background: rgba(245, 176, 38, 0.06); }
.dash-note-kind {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gold-500);
  margin-top: 6px;
  flex-shrink: 0;
}
.dash-note[data-kind="mission"] .dash-note-kind { background: var(--lime); }
.dash-note-title { font-weight: 700; font-size: 14px; }
.dash-note-text { font-size: 13px; color: var(--ink-500); margin-top: 2px; line-height: 1.4; }
.dash-note-time { font-size: 9px; color: var(--ink-500); margin-top: 4px; letter-spacing: 0.15em; }

/* ── Your account ─────────────────────────────────────────────────────────
   A young person reading a debt. Nothing here is red and nothing shouts: the
   figure is the same ink as every other figure on the page, and the line that
   gets the accent colour is the one about what their service has earned off.
   A panel that alarms produces a member who stops opening the dashboard. */
.dash-account-figure {
  font-size: 30px; font-weight: 800; letter-spacing: -0.02em;
  color: var(--ink-800, #0a1130); margin-top: 2px;
}
.dash-account-figure.is-clear { color: var(--green, #2f9e44); font-size: 24px; }
.dash-account-sub {
  font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--ink-400); margin-top: 2px;
}
.dash-account-earned {
  font-size: 13px; line-height: 1.55; color: var(--ink-600, #3c4460);
  background: rgba(110, 156, 29, 0.09);
  border-radius: 10px; padding: 9px 11px; margin-top: 12px;
}
.dash-account-phase {
  font-size: 9.5px; letter-spacing: 0.13em; color: var(--ink-400); margin-top: 10px;
}
.dash-account-toggle { margin-top: 12px; }
.dash-account-list { margin-top: 10px; border-top: 1px solid var(--line); }
.dash-account-row {
  display: flex; justify-content: space-between; gap: 10px;
  padding: 9px 0; border-bottom: 1px solid var(--line);
}
.dash-account-row.is-void { opacity: 0.45; text-decoration: line-through; }
.dash-account-row-what { font-size: 13.5px; font-weight: 600; }
.dash-account-row-note { font-size: 12px; color: var(--ink-500); margin-top: 1px; line-height: 1.4; }
.dash-account-row-when { font-size: 9px; letter-spacing: 0.14em; color: var(--ink-400); margin-top: 3px; }
.dash-account-row-amt { font-size: 13.5px; font-weight: 700; white-space: nowrap; }
.dash-account-row-amt.is-credit { color: var(--green, #2f9e44); }
.dash-account-empty { font-size: 13px; color: var(--ink-500); padding: 10px 0; }
.dash-account-foot {
  font-size: 12px; line-height: 1.55; color: var(--ink-500); margin-top: 12px;
}
.dash-badges { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
.dash-badge { font-size: 10.5px; }

/* Shortcuts */
.dash-shortcuts-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 6px;
}
.dash-shortcut {
  display: flex; align-items: center; gap: 10px;
  background: var(--cream-50);
  border: none;
  border-radius: 12px;
  padding: 14px 14px;
  font-family: inherit; font-weight: 600; font-size: 14px;
  color: var(--ink-900);
  cursor: pointer;
  transition: transform 0.18s ease, background 0.18s ease;
}
.dash-shortcut span {
  display: grid; place-items: center;
  width: 28px; height: 28px;
  border-radius: 8px;
  background: white;
  font-family: var(--font-display); font-weight: 800;
}
.dash-shortcut:hover { background: var(--cream-100); transform: translateY(-2px); }

/* Activity feed */
.dash-feed-list { list-style: none; padding: 0; margin: 0; }
.dash-feed-item {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 14px;
  padding: 10px 0;
  position: relative;
}
.dash-feed-item:not(:last-child)::before {
  content: ""; position: absolute;
  left: 11px; top: 24px; bottom: -10px;
  border-left: 2px dashed rgba(12,20,50,0.1);
}
.dash-feed-dot {
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--gold-500);
  margin-top: 8px; margin-left: 6px;
  position: relative;
  z-index: 1;
}
.dash-feed-verified .dash-feed-dot { background: var(--lime); }
.dash-feed-title { font-weight: 700; font-size: 14px; }
.dash-feed-meta { font-family: var(--font-mono); font-size: 10px; color: var(--ink-500); margin-top: 3px; letter-spacing: 0.12em; }

/* Journal */
.dash-mood {
  display: flex; gap: 8px;
  margin-bottom: 12px;
}
.dash-mood-btn {
  background: transparent;
  border: 2px solid rgba(12,20,50,0.08);
  border-radius: 50%;
  width: 44px; height: 44px;
  font-size: 22px;
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.16s ease;
}
.dash-mood-btn:hover { transform: scale(1.08); }
.dash-mood-btn.is-on {
  border-color: var(--gold-500);
  background: rgba(245, 176, 38, 0.08);
}
.dash-journal-input {
  width: 100%;
  border: 1.5px solid rgba(12,20,50,0.1);
  border-radius: 12px;
  padding: 14px;
  font-family: inherit; font-size: 15px;
  line-height: 1.55;
  resize: vertical;
  background: var(--cream-50);
}
.dash-journal-foot {
  display: flex; justify-content: space-between; align-items: center;
  margin-top: 12px;
  font-size: 10px; letter-spacing: 0.18em;
}

/* ============================================================
   6. BOOK PAGE
   ============================================================ */

.book-hero {
  background: linear-gradient(135deg, var(--cream-50) 0%, var(--cream-100) 100%);
  padding: 96px 0 80px;
  overflow: hidden;
}
.book-hero-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 56px;
  align-items: center;
}
@media (max-width: 820px) {
  .book-hero-grid { gap: 40px; }
  .book-hero-grid:not(#_):not(#_) { grid-template-columns: minmax(0, 1fr); }
}
.book-hero-h1 {
  font-size: clamp(56px, 11vw, 144px);
  line-height: 0.92;
  letter-spacing: -0.04em;
  margin: 18px 0 0;
}
.book-hero-p {
  margin-top: 28px;
  font-size: 18px;
  line-height: 1.55;
  color: var(--ink-500);
  max-width: 540px;
}
.book-hero-cta { display: flex; gap: 12px; margin-top: 32px; flex-wrap: wrap; }
.book-hero-meta {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
