  font-weight: 800;
  color: var(--gold-500);
  line-height: 1;
}
.book-flex-l { font-size: 10px; letter-spacing: 0.22em; color: rgba(255,255,255,0.55); margin-top: 6px; }

.book-chapters-sec { padding: 96px 0; background: var(--paper); }
.book-chapters-head { max-width: 720px; margin-bottom: 56px; }
.book-chapters-h { font-size: clamp(40px, 6vw, 72px); line-height: 1; margin: 18px 0; }
.book-chapters-p { font-size: 17px; line-height: 1.55; color: var(--ink-500); }

.book-chapter-list { list-style: none; padding: 0; margin: 0; }
.book-chapter {
