}
.book-chapter:last-child { border-bottom: 1px solid rgba(12,20,50,0.08); }
.book-chapter:hover { padding-left: 8px; }
.book-chapter-num {
  font-family: var(--font-display);
  font-size: 48px; font-weight: 800;
  color: var(--gold-500);
  line-height: 1;
  letter-spacing: -0.04em;
}
.book-chapter-title { font-family: var(--font-display); font-size: 22px; font-weight: 700; }
.book-chapter-sub { font-size: 14px; color: var(--ink-500); margin-top: 4px; line-height: 1.45; }
.book-chapter-meta { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.14em; color: var(--ink-500); margin-top: 6px; display: flex; gap: 8px; }
.book-chapter-cta {
  display: inline-flex; align-items: center; gap: 8px;
  background: transparent; border: none;
  font-family: inherit; font-size: 14px; font-weight: 600;
  color: var(--navy-900);
  cursor: pointer;
  white-space: nowrap;
}
.book-chapter-cta:hover { color: var(--gold-500); }

.book-proof { padding: 96px 0; background: var(--cream-100); }
.book-proof-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 32px;
}
@media (max-width: 720px) { .book-proof-grid { grid-template-columns: minmax(0, 1fr); } }
.book-proof-q {
  background: white;
  border-radius: 18px;
  padding: 32px;
}
.book-proof-mark {
  font-size: 72px; color: var(--gold-500);
  line-height: 0.5; font-family: var(--font-display);
}
.book-proof-q p { font-size: 18px; line-height: 1.5; margin: 0 0 18px; }
.book-proof-by { font-size: 10px; letter-spacing: 0.2em; color: var(--ink-500); }

.book-cta { padding: 112px 0; text-align: center; background: var(--navy-900); color: white; }
.book-cta-h { font-size: clamp(48px, 8vw, 96px); margin: 0; line-height: 1; }
.book-cta-p { font-size: 18px; color: rgba(255,255,255,0.7); margin: 18px auto 32px; max-width: 540px; }
.book-cta-row { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; }
.book-cta-note { font-size: 10px; letter-spacing: 0.22em; color: rgba(255,255,255,0.4); margin-top: 36px; }

/* ============================================================
   7. ADMIN CONSOLE
   ============================================================ */

.app-shell-admin { background: #f6f8fb; min-height: 100vh; }
.page.admin { background: #f6f8fb; min-height: 100vh; }

.admin-topbar {
  display: flex; justify-content: space-between; align-items: center;
  background: var(--navy-900); color: white;
  padding: 14px 28px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.admin-topbar-l { display: flex; align-items: center; gap: 14px; }
.admin-topbar-eyebrow { font-size: 10px; color: var(--gold-400); white-space: nowrap; }
.admin-topbar-section { font-family: var(--font-display); font-weight: 700; font-size: 18px; }
.admin-topbar-r { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.admin-session-chip { font-family: var(--font-mono, monospace); font-size: 11px; font-weight: 600; color: rgba(255,255,255,0.7); background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.14); border-radius: 999px; padding: 4px 10px; white-space: nowrap; }
.admin-session-chip.warn { color: #ffd7a1; background: rgba(245,176,38,0.16); border-color: rgba(245,176,38,0.4); }
.admin-gate-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 14px; flex-wrap: wrap; }

/* Integration setup guide */
.admin-guide { margin: 4px 0 2px; }
.admin-guide-toggle { background: none; border: none; cursor: pointer; font: inherit; font-size: 13px; font-weight: 700; color: var(--navy-700, #1c2a5e); padding: 4px 0; }
.admin-guide-body { margin-top: 8px; background: rgba(12,20,50,0.03); border: 1px solid rgba(12,20,50,0.08); border-radius: 12px; padding: 14px 16px; font-size: 13.5px; line-height: 1.6; color: var(--ink-700, #46506e); }
.admin-guide-body ol { margin: 0; padding-left: 20px; }
.admin-guide-body li { margin-bottom: 6px; }
.admin-guide-body code { font-family: var(--font-mono, monospace); font-size: 12px; background: rgba(12,20,50,0.07); padding: 1px 5px; border-radius: 4px; }
.admin-guide-code { margin-top: 12px; border: 1px solid rgba(12,20,50,0.1); border-radius: 10px; overflow: hidden; }
.admin-guide-code-h { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 12px; background: rgba(12,20,50,0.05); font-size: 12px; font-weight: 700; color: var(--ink-600, #47506e); }
.admin-guide-code pre { margin: 0; padding: 14px 16px; background: #0c1432; color: #e8ecfb; font-family: var(--font-mono, monospace); font-size: 12px; line-height: 1.55; overflow-x: auto; }
.admin-guide-note { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-500, #5a6488); }

/* The console shell: sidebar, work, and — when it is open — the Analyst.
 *
 * A TRACK, not an overlay. The page reflows beside the pane rather than being
 * covered by it, which is the difference between an assistant you consult while
 * reading and one you consult instead of reading.
 *
 * `minmax(0, 1fr)` on the middle track is load-bearing and not defensive: grid
 * items default to `min-width: auto`, so a wide table in the middle refuses to
 * shrink and pushes the pane clean off the right edge of the window.
 *
 * Each column owns its own overflow when the pane is open, so the two scroll
 * independently — the conversation does not run away when the page is scrolled,
 * and the page's own sticky filter bar still sticks. */
.admin-shell {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  min-height: calc(100vh - 60px);
}
.admin-shell.has-analyst {
  grid-template-columns: 220px minmax(0, 1fr) var(--analyst-w, 420px);
  height: calc(100vh - 60px);
  min-height: 0;
}
.admin-shell.has-analyst > .admin-nav,
.admin-shell.has-analyst > .admin-main { overflow-y: auto; min-height: 0; }
@media (max-width: 1240px) {
  /* Below this the middle column is narrower than the pane and the work becomes
     a gutter. The pane goes over the top instead — still usable, and honest
     about the fact that there is not room for both. */
  .admin-shell.has-analyst { grid-template-columns: 220px minmax(0, 1fr); height: auto; min-height: calc(100vh - 60px); }
  .admin-shell.has-analyst > .anp {
    position: fixed; top: 60px; right: 0; bottom: 0; width: min(420px, 100vw);
    z-index: 60; box-shadow: -18px 0 44px -22px rgba(12, 20, 50, 0.5);
  }
}
/* Phone section picker — hidden on desktop, where the sidebar does the job. */
.admin-nav-m { display: none; }
@media (max-width: 820px) {
  .admin-shell { grid-template-columns: minmax(0, 1fr); }
  /* The sidebar used to stay visible here with only `display: flex` applied —
     but `.admin-nav` is `flex-direction: column`, which nothing reset, so on a
     phone it rendered as a full vertical list of every section and pushed the
     actual page a screen and a half down. The picker replaces it outright. */
  .admin-nav:not(#_):not(#_) { display: none; }
  .admin-nav-m {
    display: flex; align-items: center; gap: 10px;
    background: white;
    padding: 10px 16px;
    border-bottom: 1px solid rgba(12, 20, 50, 0.08);
  }
  .admin-nav-m-lab {
    font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.1em;
    text-transform: uppercase; color: var(--ink-500); flex-shrink: 0;
  }
  .admin-nav-m-sel {
    flex: 1; min-width: 0; min-height: 44px;
    padding: 8px 12px;
    border: 1px solid rgba(12, 20, 50, 0.16); border-radius: 10px;
    background: var(--cream-50);
    font-family: inherit; font-size: 15px; font-weight: 600; color: var(--ink-900);
  }
  .admin-nav-m-sel:focus-visible { outline: 2px solid var(--gold-500); outline-offset: 2px; }
}

/* The sidebar reads as part of the topbar rather than as the first column of
   the page. Thirty sections on white was a wall of near-identical rows; on navy
   the group headings carry the structure and the active row is unmistakable
   from the corner of the eye, which is what a nav that deep needs. */
.admin-nav {
  background: var(--navy-900, #0c1432);
  padding: 14px 12px 28px;
  border-right: 1px solid rgba(255, 255, 255, 0.06);
  display: flex; flex-direction: column;
  gap: 1px;
}
.admin-nav-group {
  font-family: var(--font-mono, monospace);
  font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase;
  color: rgba(232, 236, 251, 0.5);
  padding: 20px 14px 8px;
}
.admin-nav-item {
  position: relative;
  display: flex; align-items: center; gap: 12px;
  background: transparent; border: none;
  padding: 9px 12px;
  border-radius: 9px;
  font-family: inherit; font-size: 13.5px; font-weight: 500;
  color: rgba(232, 236, 251, 0.76);
  text-align: left;
  cursor: pointer;
  transition: background 0.14s ease, color 0.14s ease;
}
.admin-nav-item:hover { background: rgba(255, 255, 255, 0.07); color: #fff; }
.admin-nav-item.is-active {
  background: rgba(255, 255, 255, 0.1);
  color: #fff; font-weight: 700;
}
/* A bar in the gutter rather than a filled pill: at this density a solid block
   every time you move sections is a lot of movement for one row of text. */
.admin-nav-item.is-active::before {
  content: ""; position: absolute; left: -12px; top: 7px; bottom: 7px;
  width: 3px; border-radius: 0 3px 3px 0; background: var(--gold-400, #f5b026);
}
.admin-nav-item:focus-visible { outline: 2px solid var(--gold-400, #f5b026); outline-offset: -2px; }
.admin-nav-icon { width: 16px; text-align: center; opacity: 0.6; }
.admin-nav-item.is-active .admin-nav-icon { opacity: 1; color: var(--gold-400); }

/* The Analyst toggle in the topbar. NGG lime, because it is the one control up
   there that opens a whole surface rather than navigating. */
.admin-analyst-btn {
  display: inline-flex; align-items: center; gap: 8px;
  height: 32px; padding: 0 12px;
  border: 1px solid rgba(255, 255, 255, 0.18); border-radius: 9px;
  background: rgba(255, 255, 255, 0.07); color: rgba(255, 255, 255, 0.86);
  font-family: inherit; font-size: 13px; font-weight: 700; cursor: pointer;
  white-space: nowrap;
}
.admin-analyst-btn:hover { background: rgba(255, 255, 255, 0.13); color: #fff; }
.admin-analyst-btn.is-on { background: #d0ff3a; border-color: #d0ff3a; color: #0c1432; }
.admin-analyst-btn kbd {
  font-family: var(--font-mono, monospace); font-size: 9.5px; font-weight: 700;
  border: 1px solid currentColor; border-radius: 4px; padding: 1px 4px; opacity: 0.6;
}
@media (max-width: 900px) { .admin-analyst-btn kbd { display: none; } }

.admin-main { padding: 32px; }
.admin-h2 { font-family: var(--font-display); font-size: 28px; font-weight: 700; margin: 0; letter-spacing: -0.01em; }
.admin-h3 { font-family: var(--font-display); font-size: 18px; font-weight: 700; margin: 0 0 14px; }

.admin-section { background: white; border-radius: 14px; padding: 28px; margin-bottom: 24px; }
.admin-section-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 24px; flex-wrap: wrap; gap: 12px; }
.admin-section-actions { display: flex; gap: 8px; }

.admin-tiles {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 24px;
}
@media (max-width: 820px) { .admin-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.admin-tile {
  background: white;
  border: none;
  border-radius: 14px;
  padding: 22px 22px 20px;
  text-align: left;
  cursor: pointer;
  font-family: inherit;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.admin-tile:hover { transform: translateY(-2px); box-shadow: 0 14px 30px -10px rgba(12, 20, 50, 0.15); }
.admin-tile-n {
  font-family: var(--font-display);
  font-size: 42px; font-weight: 800;
  color: var(--navy-900); line-height: 1;
}
.admin-tile-l { font-size: 10px; letter-spacing: 0.2em; color: var(--ink-500); margin-top: 8px; }

.admin-quick { background: white; border-radius: 14px; padding: 22px; }
.admin-quick-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
@media (max-width: 720px) { .admin-quick-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.admin-quick-btn {
  background: var(--cream-50);
  border: none;
  border-radius: 10px;
  padding: 14px;
  font-family: inherit; font-weight: 600;
  cursor: pointer;
  text-align: left;
  transition: background 0.14s ease;
}
.admin-quick-btn:hover { background: var(--cream-100); }

.admin-input, .admin-select {
  width: 100%;
  border: 1.5px solid rgba(12,20,50,0.12);
  border-radius: 10px;
  padding: 10px 12px;
  font-family: inherit; font-size: 14px;
  background: white;
  outline: none;
}
.admin-input:focus, .admin-select:focus { border-color: var(--navy-900); }

.admin-filters {
  display: grid;
  grid-template-columns: 2fr repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 18px;
}
/* The members roster carries a fifth control (rows with something missing).
   Its own modifier rather than a wider default, because the other filter rows
   — requests, submissions — have fewer and would grow a dead column. */
.admin-seg { display: inline-flex; gap: 6px; flex-wrap: wrap; }
.admin-filters-5 { grid-template-columns: 2fr repeat(4, minmax(0, 1fr)); }
.admin-filters-6 { grid-template-columns: 2fr repeat(5, minmax(0, 1fr)); }
@media (max-width: 1300px) { .admin-filters-6 { grid-template-columns: 2fr repeat(3, minmax(0, 1fr)); } }
@media (max-width: 1100px) { .admin-filters-5, .admin-filters-6 { grid-template-columns: 2fr repeat(2, minmax(0, 1fr)); } }
@media (max-width: 820px) { .admin-filters, .admin-filters-5, .admin-filters-6 { grid-template-columns: 1fr 1fr; } }

/* Active-filter chips. Five dropdowns can be left in a state that explains an
   empty table, and reading five controls to work out why is worse than being
   told — so what is filtered is stated, and each piece is removable on its own. */
.admin-chipbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 0 0 12px; }
.admin-chip-x {
  display: inline-flex; align-items: center; gap: 7px; cursor: pointer;
  padding: 6px 11px; min-height: 32px; border-radius: 999px;
  border: 1px solid rgba(12,20,50,0.16); background: rgba(12,20,50,0.04);
  font: inherit; font-size: 12.5px; font-weight: 600; color: var(--ink-700);
}
.admin-chip-x:hover { background: rgba(12,20,50,0.09); }
.admin-chip-x:focus-visible { outline: 2px solid var(--navy-900); outline-offset: 2px; }
/* A table being refreshed keeps its rows — dropping them to a spinner on every
   page turn reads as the data going missing. It dims instead, and carries
   aria-busy so it is announced rather than only faded. */
.admin-table-wrap.is-refreshing { opacity: 0.55; transition: opacity 0.12s ease; pointer-events: none; }
.admin-table tbody tr.is-selected { background: rgba(208,255,58,0.14); }
@media (max-width: 600px) { .admin-chip-x { min-height: 40px; } }

/* The result of a bulk run, kept on screen. A toast tells you it happened; a
   run where twelve of forty were refused needs the twelve NAMED, and needs to
   stay put until the operator dismisses it. */
.admin-callout {
  margin: 0 0 14px; padding: 12px 14px; border-radius: 12px;
  background: rgba(12,20,50,0.04); border: 1px solid rgba(12,20,50,0.10);
  font-size: 13.5px; line-height: 1.55; color: var(--ink-700);
}
.admin-callout-list { margin: 8px 0 10px; padding-left: 18px; }
.admin-callout-list li { margin: 2px 0; }

.admin-table-wrap { overflow-x: auto; }
/* Pagination + count chip (shared by paged admin tables). */
.admin-pager { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 14px 2px 2px; flex-wrap: wrap; }
.admin-pager-count { font-size: 12px; color: var(--ink-500); }
.admin-pager-btns { display: flex; align-items: center; gap: 10px; }
.admin-pager-page { font-size: 12px; color: var(--ink-500); }
.admin-count { display: inline-block; margin-left: 10px; padding: 2px 9px; border-radius: 999px; background: rgba(12,20,50,0.06); color: var(--ink-500); font-size: 12px; vertical-align: middle; }
/* Bulk-select bar for review queues. */
.admin-bulkbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 10px 12px; margin-bottom: 12px; border-radius: 12px; background: rgba(12,20,50,0.04); border: 1px solid rgba(12,20,50,0.06); }
.admin-bulk-all { display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 600; color: var(--ink-700); cursor: pointer; }
.admin-bulk-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.admin-bulk-label { font-size: 11px; color: var(--ink-500); text-transform: uppercase; letter-spacing: 0.1em; }
/* The shared bulk bar (see the admin action layer in components.jsx). The
   count is a live region, so the selection size is announced and not only
   drawn — the hand-rolled bars it replaces were unlabelled divs. */
.admin-bulk-count { margin: 0; font-size: 13px; color: var(--ink-700); }
.admin-bulk-count b { font-variant-numeric: tabular-nums; }
/* "Select all N matching the filter" — the escape hatch a paged table needs.
   A real button, because it makes a decision, styled as a link because it sits
   inside a sentence. */
.admin-bulk-link {
  border: 0; background: none; padding: 0; font: inherit; color: var(--navy-900);
  text-decoration: underline; text-underline-offset: 2px; cursor: pointer;
}
.admin-bulk-link:hover { color: var(--coral); }
.admin-bulk-link:focus-visible { outline: 2px solid var(--navy-900); outline-offset: 2px; border-radius: 3px; }

/* One row's action menu. Same declarations as the bulk bar drive it, so an
   individual action cannot drift from its bulk equivalent. */
.admin-rowmenu { position: relative; display: inline-block; }
.admin-rowmenu-pop {
  position: absolute; right: 0; top: calc(100% + 4px); z-index: 40; min-width: 210px;
  display: flex; flex-direction: column; padding: 6px; border-radius: 12px;
  background: #fff; border: 1px solid rgba(12,20,50,0.12);
  box-shadow: 0 12px 32px rgba(12,20,50,0.16);
}
.admin-rowmenu-item {
  appearance: none; border: 0; background: none; text-align: left; cursor: pointer;
  font: inherit; font-size: 13.5px; color: var(--ink-700);
  padding: 9px 10px; border-radius: 8px; min-height: 40px;
}
.admin-rowmenu-item:hover { background: rgba(12,20,50,0.06); }
.admin-rowmenu-item:focus-visible { outline: 2px solid var(--navy-900); outline-offset: -2px; }
.admin-rowmenu-item.is-danger { color: #b3261e; }
.admin-rowmenu-item.is-danger:hover { background: rgba(179,38,30,0.08); }
/* A checkbox in a table cell is a target as well as a control. */
.admin-table td input[type="checkbox"], .admin-bulk-all input[type="checkbox"] { width: 18px; height: 18px; }
@media (max-width: 720px) {
  .admin-bulkbar { position: sticky; bottom: 0; z-index: 30; background: #fff; box-shadow: 0 -6px 20px rgba(12,20,50,0.1); }
  .admin-rowmenu-item { min-height: 44px; }
}
.admin-app.is-selected { outline: 2px solid var(--gold-500); outline-offset: 1px; }
.admin-table { width: 100%; border-collapse: collapse; }
.admin-table th, .admin-table td { padding: 12px 14px; text-align: left; border-bottom: 1px solid rgba(12,20,50,0.06); font-size: 14px; }
/* A column of numbers, aligned on its digits.
   Every column in here was left-aligned in proportional figures, including
   Enrolled, Present today, Late, Attendance, Level, Streak and Points — the
   columns people open the screen FOR. Left-aligned with a proportional 1
   narrower than a 0, you cannot scan down for the outlier, which is the only
   thing a column of numbers is for. The community's standings table already
   did this right (.trn-num in styles.css); this is the same rule, brought back
   to the admin tables it was never applied to. */
.admin-table th.admin-num, .admin-table td.admin-num {
  text-align: right; font-variant-numeric: tabular-nums; }
/* The unit trails the figure and must not push it out of the column. */
.admin-num small { font-weight: 400; color: var(--ink-500); }

/* A sortable column header. The button fills the cell so the whole header is
   the target — 316 header cells in this app and a 12px arrow would be a
   24×24 miss on every one of them. */
.admin-sort-th:not(#_):not(#_) { padding: 0; }
.admin-sort-btn {
  display: flex; align-items: center; gap: 6px; width: 100%; min-height: 40px;
  padding: 12px 14px; border: 0; background: none; cursor: pointer;
  font: inherit; color: inherit; letter-spacing: inherit; text-transform: inherit;
  text-align: inherit;
}
.admin-num .admin-sort-btn { justify-content: flex-end; }
.admin-sort-btn:hover { background: rgba(12, 20, 50, 0.05); color: var(--ink-900); }
.admin-sort-btn:focus-visible { outline: 2px solid var(--navy-700, #1c2a5e); outline-offset: -2px; }
/* The unsorted state is deliberately faint and the sorted one is not: the
   arrow is a hint until it is an answer. */
.admin-sort-ind { font-size: 9px; opacity: .35; }
.admin-sort-th.is-on { color: var(--ink-900); }
.admin-sort-th.is-on .admin-sort-ind { opacity: 1; color: var(--navy-700, #1c2a5e); }
.admin-table th { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.18em; color: var(--ink-500); text-transform: uppercase; }
.admin-cell-name { font-weight: 600; }
/* The row's primary action, as a control rather than a click handler on the
   <tr>. Styled as text because it IS the row's name — the affordance is the
   row, and the button exists so a keyboard can reach what a mouse already
   could. */
.admin-cell-link {
  display: block; padding: 0; border: 0; background: none; cursor: pointer;
  font: inherit; color: inherit; text-align: left;
}
.admin-cell-link:hover .admin-cell-name { text-decoration: underline; }
.admin-cell-link:focus-visible { outline: 2px solid var(--navy-700, #1c2a5e); outline-offset: 2px; border-radius: 3px; }
.admin-cell-sub { font-size: 10px; color: var(--ink-500); margin-top: 2px; letter-spacing: 0.1em; }
.admin-empty { text-align: center; color: var(--ink-500); padding: 32px; }

.chip.status-active { background: rgba(208, 255, 58, 0.3); color: var(--lime-ink); }
.chip.status-graduated-ngg { background: rgba(245, 176, 38, 0.2); color: #6c4500; }
.chip.status-graduated-vanguard { background: rgba(176, 124, 255, 0.2); color: #4a2a86; }
.chip.status-suspended { background: rgba(255, 90, 60, 0.15); color: #8e1e0a; }
.chip.status-inactive { background: rgba(12,20,50,0.08); color: var(--ink-500); }
/* Post + event lifecycle statuses (admin lists) */
.chip.status-published { background: rgba(208, 255, 58, 0.3); color: var(--lime-ink); }
.chip.status-draft { background: rgba(245, 176, 38, 0.2); color: #6c4500; }
.chip.status-archived { background: rgba(12,20,50,0.08); color: var(--ink-500); }
.chip.status-cancelled { background: rgba(255, 90, 60, 0.15); color: #8e1e0a; }

/* Mentors grid */
.admin-grid-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 14px;
}
.admin-card {
  background: var(--cream-50);
  border: none; border-radius: 12px;
  padding: 14px;
  text-align: center;
  cursor: pointer;
  font-family: inherit;
  transition: transform 0.18s ease;
}
.admin-card:hover { transform: translateY(-2px); }
.admin-card-img { width: 72px; height: 72px; border-radius: 50%; object-fit: cover; }
.admin-card-img-fallback {
  display: grid; place-items: center;
  background: var(--navy-900); color: white;
  font-family: var(--font-display); font-weight: 800; font-size: 28px;
}
.admin-card-name { font-weight: 700; margin-top: 10px; }
.admin-card-meta { font-size: 10px; letter-spacing: 0.14em; color: var(--ink-500); margin-top: 4px; }

/* Sessions */
.admin-sessions-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}
@media (max-width: 820px) { .admin-sessions-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.admin-sessions-source { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 16px; margin: 0 0 16px; padding: 12px 16px; border-radius: 14px; background: var(--cream-50); border: 1px solid var(--line, #e6e2d6); font-size: 14px; }
.admin-sessions-note { margin: 0 0 12px; font-size: 14px; color: var(--ink-500); }
.admin-session-dl { display: grid; grid-template-columns: auto 1fr; gap: 6px 14px; margin: 0; }
.admin-session-dl dt { font-weight: 700; }
.admin-session-dl dd { margin: 0; }
.admin-session-card {
  background: var(--cream-50);
  border: 2px solid transparent;
  border-radius: 14px; padding: 22px;
  text-align: left; cursor: pointer; font-family: inherit;
  transition: transform 0.18s ease, border-color 0.18s ease;
}
.admin-session-card:hover { transform: translateY(-2px); }
.admin-session-card.is-active { border-color: var(--gold-500); }
.admin-session-name { font-family: var(--font-display); font-size: 28px; font-weight: 800; margin-top: 6px; letter-spacing: -0.02em; }
.admin-session-dates { font-size: 12px; color: var(--ink-500); margin-top: 6px; }
.admin-session-theme { font-size: 13px; margin-top: 10px; font-style: italic; color: var(--ink-700); }
.admin-session-live { font-size: 10px; color: var(--gold-500); letter-spacing: 0.2em; margin-top: 8px; }

/* Missions */
.admin-mission-list { display: flex; flex-direction: column; gap: 12px; }
.admin-mission-week { background: var(--cream-50); border-radius: 12px; padding: 12px 16px; }
.admin-mission-week-h { display: flex; justify-content: space-between; align-items: center; padding: 6px 0; font-weight: 600; }
.admin-mission-week-h .mono { background: var(--navy-900); color: var(--gold-400); padding: 4px 10px; border-radius: 6px; font-size: 11px; letter-spacing: 0.18em; }
.admin-mission-week-c { font-family: var(--font-mono); font-size: 10px; color: var(--ink-500); letter-spacing: 0.14em; }
.admin-mission-rows { display: flex; flex-direction: column; gap: 4px; margin-top: 8px; }
.admin-mission-row {
  display: grid; grid-template-columns: 200px minmax(0, 1fr) auto; gap: 12px;
  background: white; border: none; border-radius: 8px;
  padding: 10px 14px; text-align: left;
  font-family: inherit; cursor: pointer; font-size: 13px;
  align-items: center;
}
.admin-mission-row:hover { background: rgba(245, 176, 38, 0.06); }
.admin-mission-row-empty { background: transparent; border: 1px dashed rgba(12,20,50,0.15); color: var(--ink-500); grid-template-columns: 1fr; text-align: center; }
.admin-mission-row-t { font-weight: 600; }
.admin-mission-row-x { font-size: 10px; color: var(--gold-500); letter-spacing: 0.14em; }

/* Events */
.admin-event-list { display: flex; flex-direction: column; gap: 8px; }
.admin-event-row {
  display: grid; grid-template-columns: 56px 1fr; gap: 16px;
  background: var(--cream-50);
  border: none; border-radius: 12px;
  padding: 14px;
  font-family: inherit; cursor: pointer; text-align: left;
}
.admin-event-row:hover { background: var(--cream-100); }
.admin-event-date-block {
  background: var(--navy-900); color: white;
  border-radius: 10px;
  text-align: center; padding: 8px 0;
}
.admin-event-date-block > div:first-child {
  font-family: var(--font-display); font-size: 22px; font-weight: 800; line-height: 1;
}
.admin-event-date-block .mono { font-size: 9px; color: var(--gold-400); letter-spacing: 0.2em; margin-top: 2px; }
.admin-event-title { font-weight: 700; font-size: 16px; }
.admin-event-meta { font-size: 10px; color: var(--ink-500); margin-top: 2px; letter-spacing: 0.12em; }

/* Posts */
.admin-post-list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 6px; }
.admin-post-row {
  display: flex; justify-content: space-between; align-items: center;
  background: var(--cream-50);
  padding: 14px 16px;
  border-radius: 10px;
  cursor: pointer;
  gap: 12px;
}
.admin-post-row:hover { background: var(--cream-100); }
.admin-post-title { font-weight: 700; }
.admin-post-meta { font-size: 10px; color: var(--ink-500); margin-top: 2px; letter-spacing: 0.14em; }
.chip.post-kind-blog { background: rgba(12, 20, 50, 0.08); color: var(--ink-900); }
.chip.post-kind-news { background: rgba(245, 176, 38, 0.2); color: #6c4500; }
.chip.post-kind-update { background: rgba(208, 255, 58, 0.3); color: var(--lime-ink); }
.chip.post-kind-promo { background: rgba(176, 124, 255, 0.2); color: #4a2a86; }

/* Drawer */
.admin-drawer {
  position: fixed; inset: 0;
  background: rgba(12, 20, 50, 0.4);
  backdrop-filter: blur(6px);
  z-index: 250;
  animation: signin-scrim-in 0.18s ease;
}
.admin-drawer-panel {
  position: absolute; top: 0; right: 0; bottom: 0;
  width: min(560px, 100%);
  background: white;
  overflow-y: auto;
  display: flex; flex-direction: column;
  animation: drawer-in 0.28s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.admin-drawer-wide { width: min(800px, 100%); }
/* A drawer whose body scrolls independently of its sticky head and foot. The
   editions/groups editors need it: they carry a fieldset of weekdays and four
   dates, and a drawer that scrolls as one unit puts Save off-screen. */
.admin-drawer-scroll { flex: 1; overflow-y: auto; display: flex; flex-direction: column; }
/* A sub-heading inside a section — one level below .admin-h3. */
.admin-h4 {
  font-family: var(--font-display); font-size: 15px; font-weight: 700;
  margin: 0 0 10px; color: var(--ink-900);
}
/* An inline form error. role="alert" on the element, so it is announced when it
   appears rather than only turning red. */
.admin-form-err {
  margin: 12px 28px 0; padding: 10px 12px; border-radius: 10px;
  background: rgba(179,38,30,0.08); border: 1px solid rgba(179,38,30,0.25);
  color: #8c1d18; font-size: 13px; line-height: 1.5;
}
/* A real <fieldset>/<legend>, because a group of checkboxes needs a name a
   screen reader can read out before the boxes. */
.admin-fieldset { border: 0; padding: 0; margin: 0; min-width: 0; }
.admin-legend {
  font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.18em;
  color: var(--ink-500); padding: 0; margin-bottom: 8px;
}
/* Weekday picker. Each day is a real checkbox with a visible label — a row of
   toggle buttons would be prettier and unreachable by keyboard without extra
   work that adds nothing here. */
.admin-daypick { display: flex; flex-wrap: wrap; gap: 6px; }
.admin-daypick-day {
  display: inline-flex; align-items: center; gap: 6px; cursor: pointer;
  padding: 8px 11px; min-height: 40px; border-radius: 999px;
  border: 1px solid rgba(12,20,50,0.16); background: #fff;
  font-size: 13px; font-weight: 600; color: var(--ink-700);
}
.admin-daypick-day.is-on { background: var(--navy-900); border-color: var(--navy-900); color: #fff; }
.admin-daypick-day:focus-within { outline: 2px solid var(--navy-900); outline-offset: 2px; }
.admin-daypick-day input { width: 16px; height: 16px; margin: 0; }

/* Grouped panel navigation, for a workspace with more panels than fit in one
   readable strip. Fifteen tabs in a row is a wall; four named groups is a map
   of the job. */
.admin-panelnav { display: flex; flex-wrap: wrap; gap: 8px 22px; margin: 4px 0 18px; }
.admin-panelnav-group { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
.admin-panelnav-label {
  font-family: var(--font-mono); font-size: 9.5px; letter-spacing: 0.2em;
  text-transform: uppercase; color: var(--ink-500);
}
@media (max-width: 900px) { .admin-panelnav { gap: 10px 0; flex-direction: column; } }
@media (max-width: 600px) { .admin-daypick-day { min-height: 44px; } }
@keyframes drawer-in { from { transform: translateX(100%); } to { transform: none; } }
.admin-drawer-head {
  display: flex; justify-content: space-between; align-items: center;
  padding: 22px 28px;
  border-bottom: 1px solid rgba(12,20,50,0.06);
}
.admin-drawer-head h3 { font-family: var(--font-display); font-size: 22px; font-weight: 700; margin: 0; }
.admin-drawer-close {
  background: transparent; border: none;
  width: 32px; height: 32px; border-radius: 50%;
  font-size: 18px;
  cursor: pointer;
}
.admin-drawer-close:hover { background: rgba(12,20,50,0.06); }
.admin-fields { padding: 24px 28px; display: flex; flex-direction: column; gap: 16px; flex: 1; }
.admin-fields-row { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.admin-fields-row:has(>*:nth-child(3)) { grid-template-columns: repeat(3, minmax(0, 1fr)); }
@media (max-width: 600px) { .admin-fields-row, .admin-fields-row:has(>*:nth-child(3)) { grid-template-columns: 1fr; } }

.admin-field { display: flex; flex-direction: column; gap: 6px; font-size: 13px; }
.admin-field > span { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.18em; color: var(--ink-500); }
.admin-field em { color: var(--coral); margin-left: 2px; font-style: normal; }
.admin-field-check { flex-direction: row; align-items: center; gap: 10px; }
.admin-field-check input { width: 18px; height: 18px; }
.admin-field-check span { font-size: 13px; letter-spacing: normal; color: var(--ink-900); font-family: inherit; }

.admin-drawer-foot {
  position: sticky; bottom: 0;
  display: flex; justify-content: flex-end; align-items: center; gap: 10px;
  padding: 18px 28px;
  background: white;
  border-top: 1px solid rgba(12, 20, 50, 0.06);
}

.admin-broadcast { display: flex; flex-direction: column; gap: 16px; max-width: 640px; }

/* Admin gate */
.admin-gate {
  min-height: 100vh;
  display: grid; place-items: center;
  background: linear-gradient(135deg, var(--navy-900) 0%, var(--navy-700) 100%);
  padding: 28px;
}
.admin-gate-card {
  width: 100%; max-width: 460px;
  background: white;
  border-radius: 24px;
  padding: 40px 32px;
}
.admin-gate-h { font-size: 32px; margin: 8px 0 14px; }
.admin-gate-p { font-size: 14px; color: var(--ink-500); margin-bottom: 22px; }
.admin-gate-secret { margin-bottom: 22px; }
.admin-gate-secret code {
  display: block; padding: 12px;
  background: var(--cream-50); border-radius: 10px;
  font-family: var(--font-mono); font-size: 14px;
  letter-spacing: 0.1em;
  word-break: break-all;
}

/* Stand-alone coordinator portal logins (Summer School / NGG Club) */
.portal-login-card { max-width: 420px; text-align: center; }
.portal-login-card form { display: flex; flex-direction: column; gap: 12px; margin-top: 6px; }
.portal-login-card .signin-input { width: 100%; text-align: left; }
.portal-login-card .signin-link {
  background: none; border: none; cursor: pointer;
  font: inherit; font-size: 13px; font-weight: 600;
  color: var(--ink-500); padding: 4px; margin-top: 2px;
}
.portal-login-card .signin-link:hover { color: var(--cr-ink); }
.portal-login-badge {
  width: 56px; height: 56px; margin: 0 auto 14px;
  display: grid; place-items: center;
  border-radius: 16px; font-size: 26px;
  background: var(--navy-900); color: var(--gold-400);
}
/* Per-portal accent tint on the sign-in badge so the two front doors read
   as distinct surfaces at a glance. */
[data-portal="summer"] .portal-login-badge { background: #8a4b12; color: #ffd79a; }
[data-portal="club"]   .portal-login-badge { background: #1f2a5e; color: #d0ff3a; }
/* The portal chrome hides the empty admin side-nav rail. */
.coord-portal .admin-shell { display: block; }

/* ============================================================
   0. TOP NAV — refined nav-bar + mega menu
   Loaded after styles.css so its declarations win on conflict.
   ============================================================ */
.topnav {
  /* Subtle initial state — almost-transparent paper, no border. */
  background: rgba(251, 247, 237, 0.55);
  border-bottom: 1px solid transparent;
  transition: background 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease, backdrop-filter 0.22s ease;
}
.topnav.is-scrolled {
  background: rgba(251, 247, 237, 0.94);
  border-bottom-color: rgba(28, 42, 94, 0.08);
  box-shadow: 0 8px 20px -16px rgba(12, 20, 50, 0.18);
}
.topnav.has-mega {
  background: rgba(251, 247, 237, 0.96);
  border-bottom-color: rgba(28, 42, 94, 0.06);
}
.topnav-inner {
  padding: 14px 32px;
  gap: 24px;
}
.brand-word b { font-size: 16px; }

/* Refined nav links — pill-on-active, hover lift, animated underline. */
.nav-link {
  position: relative;
  font-size: 14px;
  font-weight: 600;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--ink-700);
  letter-spacing: -0.005em;
  transition: color 0.15s ease, background 0.15s ease;
}
.nav-link::after { display: none; }   /* kill the legacy underline */
.nav-link:hover { background: transparent; color: var(--navy-900); }
.nav-link::before {
  content: "";
  position: absolute;
  left: 14px; right: 14px;
  bottom: 4px;
  height: 2px;
  border-radius: 2px;
  background: var(--navy-900);
  transform: scaleX(0);
  transform-origin: center;
  transition: transform 0.28s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.nav-link:hover::before { transform: scaleX(1); }
.nav-link.active {
  color: white;
  background: var(--navy-900);
}
.nav-link.active::before { display: none; }

/* Mega-menu trigger */
.nav-link-mega { display: inline-flex; align-items: center; gap: 6px; }
.nav-link-chev {
  font-size: 9px;
  opacity: 0.55;
  transition: transform 0.22s ease;
}
.nav-link-mega.is-expanded .nav-link-chev { transform: rotate(180deg); }
.nav-link-mega.is-expanded { color: var(--navy-900); }
.nav-link-mega.is-expanded::before { transform: scaleX(1); }
.nav-mega-wrap { position: relative; }

/* The mega panel — full-width strip below the nav. */
.nav-mega {
  position: absolute;
  left: 0; right: 0; top: 100%;
  background: var(--paper);
  border-bottom: 1px solid rgba(28, 42, 94, 0.06);
  box-shadow: 0 24px 40px -24px rgba(12, 20, 50, 0.2);
  opacity: 0;
  pointer-events: none;
  /* visibility:hidden pulls the panel's buttons OUT of the tab order while
     closed — opacity alone left ~10 invisible focusable controls between the
     nav and the Apply button (a WCAG focus-order + aria-hidden violation). */
  visibility: hidden;
  transform: translateY(-6px);
  transition: opacity 0.22s ease, transform 0.22s ease, visibility 0s linear 0.22s;
  z-index: 1;
}
.nav-mega.is-open {
  opacity: 1;
  pointer-events: auto;
  visibility: visible;
  transform: none;
  transition: opacity 0.22s ease, transform 0.22s ease, visibility 0s;
}
.nav-mega-inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 28px 32px 24px;
}
.nav-mega-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}
.nav-mega-item {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  background: transparent;
  border: none;
  font-family: inherit;
  text-align: left;
  padding: 14px;
  border-radius: 12px;
  cursor: pointer;
  color: var(--ink-900);
  transition: background 0.16s ease, transform 0.16s ease;
}
.nav-mega-item:hover {
  background: rgba(245, 176, 38, 0.08);
  transform: translateX(2px);
}
.nav-mega-item.is-active {
  background: var(--navy-900);
  color: white;
}
.nav-mega-icon {
  width: 40px; height: 40px;
  border-radius: 10px;
  background: white;
  border: 1px solid rgba(12,20,50,0.06);
  display: grid; place-items: center;
  font-size: 18px;
  color: var(--navy-900);
}
.nav-mega-item.is-active .nav-mega-icon {
  background: var(--gold-500);
  color: var(--navy-900);
  border-color: transparent;
}
.nav-mega-body { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.nav-mega-label {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 16px;
  letter-spacing: -0.01em;
  display: inline-flex; align-items: center; gap: 8px;
}
.nav-mega-badge {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.18em;
  background: var(--lime);
  color: var(--lime-ink);
  padding: 2px 6px;
  border-radius: 4px;
}
.nav-mega-item.is-active .nav-mega-badge {
  background: var(--gold-500);
}
.nav-mega-desc {
  font-size: 12.5px;
  color: var(--ink-500);
  line-height: 1.35;
}
.nav-mega-item.is-active .nav-mega-desc { color: rgba(255,255,255,0.7); }
.nav-mega-arrow {
  opacity: 0;
  color: var(--ink-500);
  font-weight: 600;
  transition: opacity 0.16s ease, transform 0.16s ease;
}
.nav-mega-item:hover .nav-mega-arrow {
  opacity: 1;
  transform: translateX(4px);
  color: var(--navy-900);
}
.nav-mega-item.is-active .nav-mega-arrow { opacity: 1; color: var(--gold-500); }

.nav-mega-foot {
  display: flex; justify-content: space-between; align-items: center;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px dashed rgba(12, 20, 50, 0.08);
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--ink-500);
}
.nav-mega-foot kbd {
  background: rgba(12,20,50,0.06);
  padding: 2px 6px;
  border-radius: 4px;
  margin: 0 1px;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0;
}

/* Apply button gets a permanent gold accent */
.nav-apply {
  box-shadow: 0 3px 0 #b07c12;
}
.nav-apply:not(#_):not(#_) { background: var(--gold-500); color: var(--navy-900); font-weight: 700; border-radius: 999px; }
.nav-apply:hover {
  transform: translateY(-1px);
}
.nav-apply:hover:not(#_):not(#_) { background: var(--gold-400); }
.nav-apply:active {
  transform: translateY(1px);
  box-shadow: 0 1px 0 #b07c12;
}

/* Drawer sections */
.drawer-section {
  margin-top: 18px;
  border-top: 1px solid rgba(12, 20, 50, 0.06);
  padding-top: 14px;
}
.drawer-section-h {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.24em;
  color: var(--ink-500);
  padding: 0 10px 8px;
}
.mobile-drawer .nav-link {
  align-items: center;
  gap: 12px;
}
.mobile-drawer .nav-link:not(#_):not(#_) { display: flex; }
.drawer-link-icon {
  display: inline-grid;
  place-items: center;
  width: 28px; height: 28px;
  border-radius: 8px;
  background: white;
  border: 1px solid rgba(12, 20, 50, 0.06);
  font-size: 14px;
  color: var(--navy-900);
}
.mobile-drawer .nav-link.active .drawer-link-icon {
  background: var(--gold-500);
  border-color: transparent;
  color: var(--navy-900);
}

/* On mobile, hide mega panel; the burger covers the same content. */
@media (max-width: 1024px) {
  .nav-mega { display: none; }
  .nav-link-mega { display: none; }
  /* Reduce primary links to just Home — drawer carries the rest. */
}

/* On 820 and below, the existing breakpoint already hides .nav-links */

/* ============================================================
   1a. SAFETY NETS: ErrorBoundary, Toast, SkipLink, focus rings
   ============================================================ */

/* Skip-to-content link — only visible on keyboard focus. */
.skip-link {
  position: fixed;
  left: 12px; top: -100px;
  background: var(--navy-900); color: white;
  padding: 10px 16px;
  border-radius: 10px;
  z-index: 999;
  font-weight: 700;
  text-decoration: none;
  transition: top 0.18s ease;
}
.skip-link:focus { top: 12px; outline: 3px solid var(--focus-ring, #0c1432); outline-offset: 2px; }

/* The global ring is defined once, below ("Global focus-visible polish"). */
button:focus-visible, .nav-link:focus-visible, .btn:focus-visible {
  outline-offset: 3px;
}

/* Error boundary */
.boundary {
  min-height: 70vh;
  display: grid; place-items: center;
  padding: 64px 24px;
  background: var(--cream-50);
}
.boundary-inner {
  max-width: 540px;
  text-align: center;
}
.boundary-eyebrow {
  font-size: 11px;
  letter-spacing: 0.28em;
  color: var(--coral);
}
.boundary-h {
  font-size: clamp(56px, 8vw, 96px);
  line-height: 1;
  margin: 16px 0 18px;
  letter-spacing: -0.03em;
}
.boundary-p {
  font-size: 17px; line-height: 1.55;
  color: var(--ink-500);
}
.boundary-detail {
  margin: 24px auto 0;
  max-width: 420px;
  text-align: left;
  font-size: 13px;
}
.boundary-detail summary {
  cursor: pointer;
  color: var(--ink-500);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.boundary-detail code {
  display: block;
  padding: 14px;
  margin-top: 10px;
  background: rgba(12,20,50,0.04);
  border-radius: 10px;
  font-size: 12px;
  word-break: break-word;
  white-space: pre-wrap;
}
.boundary-actions {
  display: flex; gap: 12px; justify-content: center;
  margin-top: 28px; flex-wrap: wrap;
}

/* Toast host */
.toast-host {
  position: fixed;
  bottom: 22px; right: 22px;
  z-index: 220;
  display: flex; flex-direction: column;
  gap: 10px;
  max-width: min(420px, calc(100vw - 32px));
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: flex-start;
  background: white;
  border: 1px solid rgba(12, 20, 50, 0.08);
  border-radius: 14px;
  padding: 14px 14px 14px 14px;
  box-shadow: 0 16px 40px -10px rgba(12, 20, 50, 0.18);
  animation: toast-in 0.28s cubic-bezier(0.2, 0.7, 0.2, 1);
}
@keyframes toast-in {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: none; }
}
.toast-icon {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: var(--cream-100);
  display: grid; place-items: center;
  font-family: var(--font-display);
  font-weight: 800;
  color: var(--navy-900);
}
.toast-title { font-weight: 700; font-size: 14px; line-height: 1.25; }
.toast-text { font-size: 13px; color: var(--ink-500); margin-top: 3px; line-height: 1.45; }
.toast-action {
  background: transparent; border: none;
  font-family: inherit; font-size: 12px; font-weight: 600;
  color: var(--navy-900); cursor: pointer;
  padding: 6px 0 0;
}
.toast-action:hover { color: var(--gold-500); }
.toast-close {
  background: transparent; border: none;
  width: 28px; height: 28px;
  border-radius: 50%;
  cursor: pointer; opacity: 0.5;
  font-size: 13px;
}
.toast-close:hover { opacity: 1; background: rgba(12,20,50,0.05); }

.toast-success { border-left: 3px solid var(--lime); }
.toast-success .toast-icon { background: var(--lime); color: var(--lime-ink); }
.toast-error { border-left: 3px solid var(--coral); }
.toast-error .toast-icon { background: rgba(255, 90, 60, 0.15); color: var(--coral); }
.toast-warn { border-left: 3px solid var(--gold-500); }
.toast-warn .toast-icon { background: rgba(245, 176, 38, 0.15); color: #8a5d00; }
.toast-info { border-left: 3px solid var(--navy-900); }

@media (max-width: 600px) {
  .toast-host { right: 12px; bottom: 12px; left: 12px; max-width: none; }
}

/* ============================================================
   7z. HERO VISUAL — organized composition
   One anchor image (chip top-left, caption bottom-left, theme
   card bottom-right) over a tidy bottom row (photo + live card).
   Everything stays inside the column — no negative offsets.
   ============================================================ */
.hero-visual {
  display: flex;
  flex-direction: column;
  gap: 14px;
  height: 560px;
  min-width: 0;
  position: relative;
  z-index: 0;
}
/* Soft aurora behind the composition — depth without clutter. */
.hero-visual::before {
  content: "";
  position: absolute;
  inset: -10% -14%;
  background:
    radial-gradient(42% 46% at 72% 22%, rgba(245, 176, 38, 0.20), transparent 65%),
    radial-gradient(36% 40% at 16% 84%, rgba(147, 87, 255, 0.15), transparent 65%);
  filter: blur(44px);
  z-index: -1;
  pointer-events: none;
}
.hero-visual .photo-frame:not(#_):not(#_) { border-radius: 22px; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.10), 0 30px 60px -22px rgba(0, 0, 0, 0.65); }
.hero-visual-row {
  display: flex;
  gap: 14px;
  height: 168px;
  flex: none;
  min-height: 0;
}
.hero-theme-card {
  position: absolute;
  bottom: 16px;
  right: 16px;
  max-width: 38%;
  padding: 12px 16px;
  background: linear-gradient(135deg, var(--gold-400), var(--gold-500));
  color: var(--navy-900);
  border-radius: 16px;
  box-shadow: 0 18px 44px -10px rgba(245, 176, 38, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.35);
}
.hero-live-card {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  padding: 16px 18px;
  background: rgba(10, 17, 48, 0.5);
  backdrop-filter: blur(24px) saturate(1.5);
  -webkit-backdrop-filter: blur(24px) saturate(1.5);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 18px;
  color: white;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 20px 44px -12px rgba(0, 0, 0, 0.55);
}
/* Hero secondary CTA reads as glass beside the gold primary. */
.hero .btn-on-dark-ghost {
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
@media (max-width: 820px) {
  .hero-visual { height: auto; }
  .hero-visual > .photo-frame:first-child { height: 340px; flex: none; }
  .hero-visual-row { height: 150px; }
}
@media (max-width: 560px) {
  /* Phones: keep the anchor image + live card, drop the filler photo. */
  .hero-visual > .photo-frame:first-child { height: 300px; }
  .hero-visual-row { height: auto; }
  .hero-visual-row > .photo-frame { display: none; }
  .hero-live-card { flex-direction: row; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px; }
  .hero-theme-card { max-width: 46%; padding: 10px 14px; }
}

/* ============================================================
   7y. VOLUNTEER REGISTRATION — /volunteer
   Minimalist selectable lanes + course chips. Same tokens as
   the rest of the site; gold ring marks the active choice.
   ============================================================ */
.vol-lanes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
.vol-lane {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  padding: 22px 20px;
  background: white;
  border: 1px solid rgba(12, 20, 50, 0.10);
  border-radius: 18px;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}
.vol-lane:hover { transform: translateY(-2px); border-color: rgba(12, 20, 50, 0.22); box-shadow: 0 12px 28px -14px rgba(12, 20, 50, 0.25); }
.vol-lane.is-active {
  border-color: var(--gold-500);
  box-shadow: 0 0 0 3px rgba(245, 176, 38, 0.25), 0 12px 28px -14px rgba(176, 124, 18, 0.35);
}
.vol-lane-icon { font-size: 26px; line-height: 1; }
.vol-lane-name { font-family: var(--font-display); font-weight: 800; font-size: 19px; color: var(--ink-900); }
.vol-lane-line { font-size: 13px; color: var(--ink-500); line-height: 1.45; }
.vol-lane.is-active .vol-lane-name::after { content: " ✓"; color: var(--gold-500); }
.vol-chip {
  padding: 10px 18px;
  border-radius: 999px;
  background: white;
  border: 1px solid rgba(12, 20, 50, 0.14);
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  color: var(--ink-900);
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}
.vol-chip:hover { border-color: rgba(12, 20, 50, 0.3); }
.vol-chip.is-active {
  background: var(--navy-900);
  border-color: var(--navy-900);
  color: var(--gold-400);
  box-shadow: 0 8px 20px -10px rgba(12, 20, 50, 0.5);
}
/* The roles grid on /volunteers: three across, one on a phone. */
.vol-role-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
@media (max-width: 720px) {
  .vol-lanes { grid-template-columns: 1fr; }
  .vol-fields:not(#_):not(#_) { grid-template-columns: 1fr; }
}
@media (max-width: 820px) { .vol-role-grid { grid-template-columns: minmax(0, 1fr); } }

/* ============================================================
   8a. PRE-FOOTER + FOOTER UPGRADES
   ============================================================ */
.prefooter {
  background: var(--navy-900);
  color: white;
  padding: 96px 0 88px;
  position: relative;
  overflow: hidden;
}
.prefooter::before,
.prefooter::after {
  content: "";
  position: absolute;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(60px);
}
.prefooter::before {
  top: -160px; left: -120px;
  width: 360px; height: 360px;
  background: rgba(245, 176, 38, 0.22);
  opacity: 0.9;
}
.prefooter::after {
  bottom: -120px; right: -120px;
  width: 380px; height: 380px;
  background: rgba(208, 255, 58, 0.14);
}
.prefooter-inner {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 56px;
  align-items: center;
  position: relative;
  z-index: 1;
}
.prefooter-eyebrow {
  font-size: 11px;
  letter-spacing: 0.28em;
  color: var(--gold-400);
}
.prefooter-h {
  font-size: clamp(40px, 7vw, 88px);
  line-height: 0.95;
  letter-spacing: -0.03em;
  margin: 16px 0 0;
}
.prefooter-h-em {
  color: var(--gold-500);
  font-style: italic;
}
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .prefooter-h-em {
    background: linear-gradient(92deg, var(--gold-400), var(--gold-500) 55%, var(--lime));
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }
}
.prefooter-p {
  font-size: 17px;
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.7);
  max-width: 540px;
  margin: 24px 0 0;
}
.prefooter-actions {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: stretch;
  justify-self: end;
  min-width: 260px;
}
.prefooter-actions .btn { white-space: nowrap; }

@media (max-width: 820px) {
  .prefooter { padding: 64px 0; }
  .prefooter-inner { grid-template-columns: minmax(0, 1fr); gap: 28px; }
  .prefooter-actions { min-width: 0; justify-self: stretch; }
}

/* Footer status strip + centres */
.footer-status {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-top: 18px;
  padding: 12px 18px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 16px;
  flex-wrap: wrap;
}
.footer-status-left { display: inline-flex; align-items: center; gap: 12px; }
.footer-status-dot {
  width: 9px; height: 9px;
  border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 0 3px rgba(208, 255, 58, 0.2);
  animation: pulse-dot 2.4s ease-in-out infinite;
}
@keyframes pulse-dot {
  0%, 100% { box-shadow: 0 0 0 3px rgba(208, 255, 58, 0.2); }
  50%      { box-shadow: 0 0 0 8px rgba(208, 255, 58, 0); }
}
.footer-status-label {
  font-size: 10px;
  letter-spacing: 0.24em;
  color: rgba(255, 255, 255, 0.75);
  text-transform: uppercase;
}
.footer-status-pill {
  display: inline-flex; align-items: center; gap: 10px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  padding: 6px 18px 6px 6px;
  color: white;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease;
}
.footer-status-pill:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: var(--gold-400);
}
.footer-status-avatar {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: var(--gold-500);
  color: var(--navy-900);
  display: grid; place-items: center;
  font-weight: 800;
  font-size: 13px;
}

/* Giant outlined wordmark — the footer's editorial signature. */
.footer-wordmark {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(30px, 9.6vw, 148px);
  line-height: 0.9;
  letter-spacing: -0.04em;
  text-transform: uppercase;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.04);
  -webkit-text-stroke: 1px rgba(255, 255, 255, 0.10);
  user-select: none;
  pointer-events: none;
  margin: 36px 0 -8px;
  mask-image: linear-gradient(180deg, black 15%, rgba(0, 0, 0, 0.3) 75%, transparent 100%);
  -webkit-mask-image: linear-gradient(180deg, black 15%, rgba(0, 0, 0, 0.3) 75%, transparent 100%);
}

/* Centres column inside footer-main */
.footer-col-centres { grid-column: auto; }
.footer-centres {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.footer-centre {
  padding: 13px 15px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}
.footer-centre:hover {
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(245, 176, 38, 0.4);
  transform: translateY(-2px);
}
.footer-centre-head {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 6px;
}
.footer-centre-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--gold-500);
}
.footer-centre-name {
  font-weight: 700;
  color: white;
  font-size: 14px;
}
.footer-centre-meta {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.55);
}
.footer-centre-line {
  font-size: 10px;
  letter-spacing: 0.16em;
  color: var(--gold-400);
  margin-top: 4px;
}

/* Contact lines */
.footer-contact {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.footer-contact-line {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  font-size: 14px;
  padding: 4px 0;
}
.footer-contact-line:hover { color: var(--gold-400); }
.footer-contact-icon {
  display: inline-grid;
  place-items: center;
  width: 26px; height: 26px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  font-size: 13px;
}

.footer-brand-head { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.footer-link-lock {
  display: inline-block;
  margin-left: 6px;
  color: var(--gold-400);
  font-weight: 700;
}

/* Make footer-main fit 5 columns on wide screens, gracefully step down */
@media (min-width: 1100px) {
  .footer-main { grid-template-columns: 1.4fr 1fr 1fr 1fr 1.2fr; }
}
@media (max-width: 1099px) {
  .footer-main { grid-template-columns: 1.3fr 1fr 1fr; }
  .footer-col-centres { grid-column: span 3; }
  .footer-centres {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }
}
@media (max-width: 720px) {
  /* Phones: brand + centres run full width; the three link groups sit
     two-up instead of stacking into a dozen full-width rows. */
  .footer-main:not(#_):not(#_) { grid-template-columns: 1fr 1fr; gap: 30px 20px; }
  .footer-brand { grid-column: 1 / -1; }
  .footer-col-centres { grid-column: 1 / -1; }
  .footer-centres { grid-template-columns: 1fr; }
}

/* ============================================================
   ANCHOR v2 — cinematic page
   Tokens (page-local):
     --anch-paper   page background
     --anch-ink     primary text
     --anch-ink-2   muted text
     --anch-line    hairline divider
     --anch-gold    accent
     --anch-lime    bright accent (used sparingly)
   ============================================================ */
.anchor-v2 {
  --anch-paper:  #faf6ec;
  --anch-ink:    #0a1130;
  --anch-ink-2:  #5a6285;
  --anch-line:   rgba(12, 20, 50, 0.10);
  --anch-gold:   #d99c0a;
  --anch-lime:   #d0ff3a;
  background: var(--anch-paper);
  color: var(--anch-ink);
  /* Hard containment so decorative glows etc. never widen the body. */
  overflow-x: clip;
}
.anchor-v2 .anch-section { overflow: hidden; }
.anchor-v2 section { max-width: 100vw; }

/* Generic image placeholder for book/portrait photos */
.anch-img {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  background: var(--cream-100);
  width: 100%;
}
.anch-img img { width: 100%; height: 100%; object-fit: cover; display: block; }

.anch-img-placeholder {
  background: linear-gradient(135deg, #f1ead7 0%, #e9dfc4 100%);
  border: 1px solid var(--anch-line);
}
.anch-img-placeholder.is-dark {
  background: linear-gradient(135deg, #1a2350 0%, #0c1432 100%);
  border-color: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.6);
}
.anch-img-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(12, 20, 50, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(12, 20, 50, 0.04) 1px, transparent 1px);
  background-size: 32px 32px;
}
.anch-img-placeholder.is-dark .anch-img-grid {
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
}
.anch-img-meta {
  position: absolute;
  left: 16px; bottom: 14px;
  font-family: var(--font-mono);
}
.anch-img-slot {
  font-size: 9px;
  letter-spacing: 0.24em;
  color: var(--anch-ink-2);
  margin-bottom: 4px;
}
.anch-img-placeholder.is-dark .anch-img-slot { color: rgba(255, 255, 255, 0.45); }
.anch-img-label {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 13px;
  color: var(--anch-ink);
  letter-spacing: -0.01em;
}
.anch-img-placeholder.is-dark .anch-img-label { color: rgba(255, 255, 255, 0.75); }

.anch-img-cross {
  position: absolute; inset: 0;
  display: grid; place-items: center;
}
.anch-img-cross span {
  position: absolute;
  background: rgba(12, 20, 50, 0.08);
}
.anch-img-cross span:first-child { width: 100%; height: 1px; transform: rotate(8deg); }
.anch-img-cross span:last-child  { width: 1px; height: 100%; transform: rotate(8deg); }
.anch-img-placeholder.is-dark .anch-img-cross span { background: rgba(255, 255, 255, 0.06); }

/* Shared section rhythm */
.anch-section { padding: clamp(72px, 11vw, 144px) 0; }
.anch-section-head { max-width: 880px; margin-bottom: clamp(40px, 6vw, 72px); }
.anch-section-eyebrow {
  font-size: 11px;
  letter-spacing: 0.28em;
  color: var(--anch-gold);
  text-transform: uppercase;
  font-family: var(--font-mono);
}
.anch-section-h {
  font-family: var(--font-display);
  font-size: clamp(36px, 5.6vw, 72px);
  line-height: 1.02;
  letter-spacing: -0.025em;
  font-weight: 700;
  margin: 14px 0 0;
  color: var(--anch-ink);
}
.anch-section-h em { color: var(--anch-gold); font-style: normal; }

/* ─── 1 · HERO ─────────────────────────────────────────────── */
.anch-hero {
  position: relative;
  padding: clamp(80px, 13vw, 168px) 0 clamp(64px, 10vw, 120px);
  background: #0a1130;
  color: white;
  overflow: hidden;
  isolation: isolate;
}
.anch-hero-bg { position: absolute; inset: 0; z-index: -1; overflow: hidden; }
.anch-hero-bg-grad {
  position: absolute; inset: 0;
  background:
    radial-gradient(80% 60% at 65% 30%, rgba(245, 176, 38, 0.13) 0%, transparent 65%),
    linear-gradient(135deg, #0a1130 0%, #131e48 60%, #0c1432 100%);
}
.anch-hero-bg-glow {
  position: absolute;
  top: -10%; left: 35%;
  width: 460px; height: 460px; border-radius: 50%;
  background: radial-gradient(circle, rgba(208, 255, 58, 0.18) 0%, transparent 60%);
  filter: blur(20px);
}
.anch-hero-inner {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: clamp(40px, 6vw, 96px);
  align-items: center;
  position: relative;
}
.anch-hero-eyebrow {
  font-size: 11px;
  letter-spacing: 0.3em;
  color: var(--gold-400);
}
.anch-hero-h1 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(48px, 8.4vw, 124px);
  line-height: 0.92;
  letter-spacing: -0.035em;
  margin: 22px 0 0;
}
.anch-hero-h1-em { color: var(--gold-500); font-style: italic; }
.anch-hero-p {
  margin-top: 32px;
  font-size: clamp(16px, 1.4vw, 19px);
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.72);
  max-width: 540px;
}
.anch-hero-p em { color: var(--gold-400); font-style: italic; }
.anch-hero-ctas {
  display: flex; gap: 12px; margin-top: 36px; flex-wrap: wrap;
}
.anch-hero-meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  margin-top: 56px;
  padding-top: 28px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  max-width: 480px;
}
.anch-hero-meta-l { font-size: 10px; letter-spacing: 0.22em; color: rgba(255, 255, 255, 0.45); }
.anch-hero-meta-v { font-weight: 700; font-size: 15px; margin-top: 5px; }

.anch-hero-art {
  position: relative;
  display: grid; place-items: center;
}
.anch-hero-art .anch-img {
  max-width: min(380px, 100%);
  transform: rotate(-2deg);
  transition: transform 0.5s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.anch-hero-art:hover .anch-img { transform: rotate(0deg) scale(1.02); }
.anch-hero-art-shadow {
  position: absolute;
  bottom: -10%; left: 10%; right: 10%;
  height: 60px;
  background: radial-gradient(ellipse, rgba(0,0,0,0.45) 0%, transparent 70%);
  filter: blur(20px);
  z-index: -1;
}

@media (max-width: 900px) {
  .anch-hero-inner { grid-template-columns: minmax(0, 1fr); }
  .anch-hero-art { order: -1; }
  .anch-hero-art .anch-img { max-width: 240px; }
  .anch-hero-meta { grid-template-columns: 1fr 1fr; max-width: none; }
}

/* ─── 2 · MANIFESTO ────────────────────────────────────────── */
.anch-manifesto { background: var(--anch-paper); }
.anch-pillars { list-style: none; padding: 0; margin: 0; max-width: 960px; }
.anch-pillar {
  position: relative;
  display: grid;
  grid-template-columns: 88px minmax(0, 1fr) 32px;
  gap: 32px;
  align-items: start;
  padding: 36px 0;
  border-top: 1px solid var(--anch-line);
  transition: padding-left 0.32s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.anch-pillar:last-child { border-bottom: 1px solid var(--anch-line); }
.anch-pillar:hover { padding-left: 12px; }
.anch-pillar-n {
  font-family: var(--font-mono);
  font-size: 12px;
  letter-spacing: 0.18em;
  color: var(--anch-gold);
  padding-top: 8px;
}
.anch-pillar-verb {
  font-family: var(--font-display);
  font-size: clamp(36px, 5.2vw, 64px);
  font-weight: 700;
  line-height: 0.96;
  letter-spacing: -0.025em;
  margin: 0 0 14px;
}
.anch-pillar-line {
  font-family: var(--font-display);
  font-size: clamp(18px, 1.7vw, 22px);
  line-height: 1.35;
  color: var(--anch-ink);
  margin: 0 0 14px;
  max-width: 520px;
}
.anch-pillar-detail {
  font-size: 15px;
  line-height: 1.55;
  color: var(--anch-ink-2);
  margin: 0;
  max-width: 560px;
}
.anch-pillar-tick {
  display: inline-block;
  width: 12px; height: 12px;
  border-radius: 50%;
  background: transparent;
  border: 2px solid var(--anch-line);
  margin-top: 12px;
  transition: background 0.3s ease, border-color 0.3s ease;
}
.anch-pillar:hover .anch-pillar-tick {
  background: var(--anch-gold);
  border-color: var(--anch-gold);
}

@media (max-width: 720px) {
  .anch-pillar { grid-template-columns: 56px minmax(0, 1fr); gap: 18px; }
  .anch-pillar-tick { display: none; }
}

/* ─── 3 · BOOK SPREAD ──────────────────────────────────────── */
.anch-book {
  background: linear-gradient(180deg, var(--anch-paper) 0%, #f1ead7 100%);
}
.anch-book-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(40px, 6vw, 96px);
  align-items: center;
  margin-bottom: clamp(60px, 8vw, 96px);
}
.anch-book-art {
  position: relative;
  max-width: 460px;
  margin: 0 auto;
}
.anch-book-art .anch-img:first-child {
  transform: rotate(-4deg);
  box-shadow: 0 30px 60px -20px rgba(12, 20, 50, 0.35);
  position: relative;
  z-index: 2;
}
.anch-book-art-stack {
  position: absolute;
  inset: 12px -16px -16px 16px;
  z-index: 1;
}
.anch-book-art-stack .anch-img {
  transform: rotate(5deg);
  opacity: 0.85;
  box-shadow: 0 20px 40px -16px rgba(12, 20, 50, 0.25);
}
.anch-book-lede {
  margin-top: 28px;
  font-family: var(--font-display);
  font-size: clamp(20px, 1.9vw, 26px);
  line-height: 1.35;
  color: var(--anch-ink);
  letter-spacing: -0.01em;
  max-width: 540px;
}
.anch-book-list {
  list-style: none; padding: 0; margin: 28px 0 32px;
  display: flex; flex-direction: column; gap: 12px;
  max-width: 540px;
}
.anch-book-list li {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 12px;
  align-items: baseline;
  font-size: 16px; line-height: 1.5;
  color: var(--anch-ink);
}
.anch-book-list li span {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  color: var(--anch-gold);
}
.anch-book-list li:nth-child(1) span::before { content: "01"; }
.anch-book-list li:nth-child(2) span::before { content: "02"; }
.anch-book-list li:nth-child(3) span::before { content: "03"; }
.anch-book-list li:nth-child(4) span::before { content: "04"; }
.anch-book-ctas { display: flex; gap: 12px; flex-wrap: wrap; }

.anch-book-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

@media (max-width: 900px) {
  .anch-book-grid { grid-template-columns: minmax(0, 1fr); gap: 40px; }
  .anch-book-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* ─── 4 · 12 WEEKS MAP ─────────────────────────────────────── */
.anch-weeks { background: var(--anch-paper); }
.anch-current-mark {
  display: inline-block;
  padding: 0 14px;
  background: var(--anch-lime);
  border-radius: 8px;
  color: var(--lime-ink);
}
.anch-weeks-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(20px, 3vw, 40px);
}
.anch-weeks-col { list-style: none; padding: 0; margin: 0; }
.anch-week-row {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 22px 8px;
  border-top: 1px solid var(--anch-line);
  transition: background 0.18s ease, padding-left 0.24s ease;
  cursor: default;
}
.anch-weeks-col li:last-child { border-bottom: 1px solid var(--anch-line); }
.anch-week-row:hover { background: rgba(245, 176, 38, 0.04); padding-left: 16px; }
.anch-week-n {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 800;
  color: var(--anch-ink-2);
  line-height: 1;
  letter-spacing: -0.02em;
}
.anch-week-row.is-current .anch-week-n { color: var(--anch-ink); }
.anch-week-row.is-done .anch-week-n { color: var(--anch-gold); }
.anch-week-theme {
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--anch-ink);
}
.anch-week-verb {
  font-size: 13px;
  line-height: 1.4;
  color: var(--anch-ink-2);
  margin-top: 4px;
}
.anch-week-side {
  display: flex; flex-direction: column;
  align-items: flex-end; gap: 8px;
}
.anch-week-missions {
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.18em;
  color: var(--anch-ink-2);
}
.anch-pip {
  width: 9px; height: 9px; border-radius: 50%;
  display: inline-block;
  border: 2px solid var(--anch-line);
  background: transparent;
}
.anch-pip.done    { background: var(--anch-ink); border-color: var(--anch-ink); }
.anch-pip.current { background: var(--anch-lime); border-color: var(--anch-lime); box-shadow: 0 0 0 3px rgba(208, 255, 58, 0.25); }
.anch-pip.future  { background: transparent; border-color: var(--anch-line); }

.anch-weeks-legend {
  display: flex;
  gap: 22px;
  flex-wrap: wrap;
  margin-top: 24px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  color: var(--anch-ink-2);
}
.anch-weeks-legend > span { display: inline-flex; align-items: center; gap: 8px; }

@media (max-width: 820px) {
  .anch-weeks-grid { grid-template-columns: minmax(0, 1fr); gap: 0; }
}

/* ─── 5 · WEEK DEEP-DIVE ───────────────────────────────────── */
.anch-deep { background: #0a1130; color: white; }
.anch-deep .anch-section-eyebrow { color: var(--gold-400); }
.anch-deep .anch-section-h { color: white; }
.anch-deep-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
