  font-size: clamp(40px, 5.6vw, 72px);
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1;
  margin: 12px 0 18px;
  color: white;
}
.anch-deep-verb {
  font-family: var(--font-display);
  font-style: italic;
