}
.anch-deep-mission:last-child { border-bottom: none; }
.anch-deep-mission-n {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.22em;
  color: var(--gold-400);
  padding-top: 4px;
}
.anch-deep-mission-t {
  font-family: var(--font-display);
  font-size: clamp(17px, 1.5vw, 20px);
  line-height: 1.35;
  color: white;
  margin: 0;
  letter-spacing: -0.01em;
}
.anch-deep-mission-meta {
  font-size: 10px;
  letter-spacing: 0.22em;
  color: rgba(255, 255, 255, 0.5);
