/* ─── 6 · STORIES ──────────────────────────────────────────── */
.anch-stories { background: var(--anch-paper); }
.anch-stories-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
}
.anch-story {
  background: white;
  border-radius: 18px;
  overflow: hidden;
  display: flex; flex-direction: column;
  border: 1px solid var(--anch-line);
  transition: transform 0.32s cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 0.32s ease;
}
.anch-story:hover {
  transform: translateY(-6px);
  box-shadow: 0 24px 60px -20px rgba(12, 20, 50, 0.2);
}
.anch-story .anch-img { border-radius: 0; }
.anch-story-body { padding: 24px; display: flex; flex-direction: column; gap: 14px; flex: 1; }
.anch-story-head {}
.anch-story-name {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 22px;
  letter-spacing: -0.01em;
}
.anch-story-meta {
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--anch-ink-2);
  margin-top: 4px;
}
.anch-story-q {
  font-family: var(--font-display);
  font-style: italic;
  font-size: 16px;
  line-height: 1.5;
  color: var(--anch-ink);
