  padding-top: 16px;
  border-top: 1px solid var(--anch-line);
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--anch-gold);
}
.anch-story-badge-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--anch-gold);
}

@media (max-width: 900px) {
  .anch-stories-grid { grid-template-columns: minmax(0, 1fr); }
}

/* ─── 7 · PROOF ───────────────────────────────────────────── */
.anch-proof {
  background: #f1ead7;
  padding: clamp(56px, 8vw, 96px) 0;
  border-top: 1px solid var(--anch-line);
  border-bottom: 1px solid var(--anch-line);
}
.anch-proof-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(20px, 3vw, 48px);
}
.anch-proof-cell {
  padding-left: 20px;
  border-left: 2px solid var(--anch-gold);
}
.anch-proof-n {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(40px, 5vw, 64px);
  line-height: 1;
  letter-spacing: -0.03em;
  color: var(--anch-ink);
}
.anch-proof-l {
