}
@media (max-width: 480px) {
  .anch-proof-grid { grid-template-columns: minmax(0, 1fr); }
}

/* ─── 8 · CTA ─────────────────────────────────────────────── */
.anch-cta {
  background: #0a1130;
  color: white;
  padding: clamp(80px, 12vw, 160px) 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.anch-cta::before {
  content: "";
  position: absolute;
  top: 50%; left: 50%;
  width: 700px; height: 700px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(245, 176, 38, 0.12) 0%, transparent 60%);
  transform: translate(-50%, -50%);
