.summer-rate-fill { height: 100%; border-radius: 99px; }

/* ── The attendance register's controls ──────────────────────────────────────
   Grouped in one panel rather than strung along a line: who the register is
   about, over which dates, in which situation. The three used to be a search
   box and one unlabelled dropdown, with no way to see how many rows a filter
   held before choosing it. */
.att-controls { margin-top: 22px; padding: 14px 16px; border: 1px solid var(--line, #e6e2d6); border-radius: 14px; background: var(--paper-50, #fbf9f4); display: flex; flex-direction: column; gap: 12px; }
.att-controls-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.att-seg { display: inline-flex; padding: 3px; gap: 3px; border-radius: 999px; background: rgba(12,20,50,0.06); }
.att-seg-btn { font: inherit; font-size: 13.5px; font-weight: 600; padding: 7px 14px; border: none; border-radius: 999px; background: transparent; color: var(--ink-700, #2a335c); cursor: pointer; display: inline-flex; align-items: center; gap: 7px; }
.att-seg-btn.is-on { background: var(--navy-900, #0c1432); color: #fff; }
.att-seg-n { font-family: var(--font-mono); font-size: 10.5px; padding: 1px 6px; border-radius: 999px; background: rgba(12,20,50,0.10); }
.att-seg-btn.is-on .att-seg-n { background: rgba(255,255,255,0.22); }
.att-chips { display: flex; flex-wrap: wrap; gap: 7px; }
.att-chip { font: inherit; font-size: 12.5px; font-weight: 600; padding: 6px 12px; border-radius: 999px; cursor: pointer; background: #fff; border: 1px solid var(--line, #e6e2d6); color: var(--ink-700, #2a335c); display: inline-flex; align-items: center; gap: 7px; }
.att-chip:hover { border-color: rgba(12,20,50,0.28); }
.att-chip-n { font-family: var(--font-mono); font-size: 10.5px; font-weight: 700; color: var(--ink-500); }
.att-chip.is-on { background: var(--navy-900, #0c1432); border-color: var(--navy-900, #0c1432); color: #fff; }
.att-chip.is-on .att-chip-n { color: rgba(255,255,255,0.75); }
/* A scenario that is a problem reads as one even before it is selected — but
   only when it actually has somebody in it, which is why the tone is on the
   chip and the count is what makes it visible. */
.att-chip[data-tone="bad"]  .att-chip-n { color: #b91c1c; }
.att-chip[data-tone="warn"] .att-chip-n { color: #b45309; }
.att-chip[data-tone="good"] .att-chip-n { color: #15803d; }
.att-chip.is-on[data-tone="bad"]  { background: #b91c1c; border-color: #b91c1c; }
.att-chip.is-on[data-tone="warn"] { background: #b45309; border-color: #b45309; }
.att-chip.is-on[data-tone="good"] { background: #15803d; border-color: #15803d; }
.att-chip.is-on[data-tone] .att-chip-n { color: rgba(255,255,255,0.8); }
@media (max-width: 640px) {
  .att-controls-row > .admin-input[type="date"] { flex: 1 1 42%; min-width: 0; }
  .att-seg { width: 100%; }
  .att-seg-btn { flex: 1; justify-content: center; }
}

/* ── One day, opened from its bar ─────────────────────────────────────────── */
.summer-attbar-col { border: none; background: transparent; padding: 0; cursor: pointer; font: inherit; }
.summer-attbar-col:disabled { cursor: progress; }
.summer-attbar-col:hover .summer-attbar-track,
.summer-attbar-col:focus-visible .summer-attbar-track { outline: 2px solid var(--gold-500, #f5b026); outline-offset: 1px; }
.summer-attbar-col.is-open .summer-attbar-track { outline: 2px solid var(--navy-900, #0c1432); outline-offset: 1px; }
.att-day { margin-top: 12px; padding: 14px 16px; border: 1px solid var(--line, #e6e2d6); border-left: 3px solid var(--navy-900, #0c1432); border-radius: 12px; background: #fff; }
.att-day-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }
.att-day-tag { margin-left: 10px; font-family: var(--font-mono); font-size: 11px; color: var(--ink-500); }
.att-day-tag[data-tone="muted"] { color: var(--gold-700, #7a5600); }
.att-day-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
@media (max-width: 720px) { .att-day-cols { grid-template-columns: 1fr; } }
.att-day-names { display: flex; flex-wrap: wrap; gap: 6px; }
.att-day-name { display: inline-flex; align-items: baseline; gap: 6px; padding: 4px 10px; border-radius: 999px; background: rgba(12,20,50,0.05); font-size: 13px; }
.att-day-name[data-late="1"] { background: rgba(245,176,38,0.16); }
.att-day-meta { font-family: var(--font-mono); font-style: normal; font-size: 10.5px; color: var(--ink-500); }
.summer-insight { margin: 4px 0 18px; padding: 16px 18px; border-radius: 16px; background: linear-gradient(135deg, rgba(139,92,246,0.08), rgba(208,255,58,0.06)); border: 1px solid var(--line, #e6e2d6); }
.summer-insight-head { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.summer-insight-head .eyebrow { display: inline-flex; align-items: center; gap: 6px; }
.summer-insight-src { font-family: var(--font-mono); font-size: 10px; color: var(--ink-500); padding: 2px 8px; border-radius: 99px; background: rgba(12,20,50,0.06); }
.summer-insight-head .btn { margin-left: auto; }
.summer-insight-body { font-size: 14px; line-height: 1.6; white-space: pre-line; color: var(--ink-800, #1a2340); }
.summer-insight-hint { margin-top: 10px; font-size: 12px; color: var(--ink-500); }
.summer-archive { margin-top: 26px; padding: 16px 18px; border-radius: 16px; border: 1px dashed var(--line, #e6e2d6); display: flex; align-items: center; gap: 16px; justify-content: space-between; flex-wrap: wrap; }
.admin-anchor-list { display: flex; flex-direction: column; gap: 10px; }
.admin-anchor-row { display: flex; gap: 10px; align-items: flex-start; }
.admin-anchor-n { color: var(--gold-500); font-size: 12px; padding-top: 12px; }
.admin-anchor-rm { flex: none; width: 38px; height: 38px; border-radius: 10px; border: 1px solid var(--line, #e6e2d6); background: #fff; cursor: pointer; color: var(--coral); font-size: 14px; }
.admin-anchor-rm:hover { background: rgba(255,90,60,0.08); }
.admin-anchor-rowtools { display: flex; gap: 4px; flex: none; }
.admin-anchor-mv { width: 34px; height: 38px; border-radius: 10px; border: 1px solid var(--line, #e6e2d6); background: #fff; cursor: pointer; color: var(--ink-700); font-size: 13px; }
.admin-anchor-mv:hover:not(:disabled) { background: rgba(12,20,50,0.05); }
.admin-anchor-mv:disabled { opacity: 0.35; cursor: default; }
.admin-anchor-wk-tools { margin-left: auto; display: inline-flex; gap: 4px; }
.admin-anchor-del { color: var(--coral); }
.admin-anchor-del:hover:not(:disabled) { background: rgba(255,90,60,0.08); }
.admin-anchor-weeks-bar { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
.admin-anchor-restore { display: flex; align-items: center; gap: 10px; margin: 0 0 14px; padding: 10px 14px; border-radius: 12px; background: rgba(139,92,246,0.1); border: 1px solid rgba(139,92,246,0.35); color: #4c1f9c; font-size: 13px; font-weight: 500; }
.admin-anchor-complete { display: flex; align-items: center; gap: 12px; margin: 0 0 16px; font-size: 12px; color: var(--ink-500); }
.admin-anchor-wk-pct { font-family: var(--font-mono); font-size: 10px; padding: 2px 7px; border-radius: 999px; background: rgba(12,20,50,0.06); color: var(--ink-500); margin-left: 8px; }
.admin-anchor-wk-pct.is-full { background: rgba(208,255,58,0.25); color: #2e4400; }
/* In-manager live preview (mirrors the Anchor Journal PWA violet theme) */
.admin-anchor-preview-bar { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.aj-preview-shell { background: #17123a; background-image: radial-gradient(60% 50% at 20% 10%, rgba(139,92,246,0.35), transparent 60%), radial-gradient(50% 40% at 90% 20%, rgba(217,110,194,0.25), transparent 60%); border-radius: 20px; padding: 26px; color: #fff; }
.aj-preview-quote { font-family: var(--font-display, serif); font-size: 18px; font-style: italic; color: #e9deff; line-height: 1.4; margin-bottom: 18px; }
.aj-preview-card { background: rgba(255,255,255,0.07); border: 1px solid rgba(255,255,255,0.14); border-radius: 16px; padding: 20px; backdrop-filter: blur(8px); }
.aj-preview-wk { font-family: var(--font-mono, monospace); font-size: 10px; letter-spacing: 0.24em; color: #c9f24e; }
.aj-preview-title { font-family: var(--font-display, sans-serif); font-weight: 800; font-size: 24px; letter-spacing: -0.02em; margin: 6px 0 4px; }
.aj-preview-system { font-size: 13px; color: #ffce54; margin-bottom: 8px; }
.aj-preview-focus { font-size: 15px; color: rgba(255,255,255,0.85); margin: 0 0 14px; line-height: 1.45; }
.aj-preview-rows { display: flex; flex-direction: column; gap: 8px; }
.aj-preview-row { display: flex; gap: 10px; font-size: 13px; color: rgba(255,255,255,0.82); }
.aj-preview-k { flex: none; width: 78px; font-family: var(--font-mono, monospace); font-size: 10px; letter-spacing: 0.12em; text-transform: uppercase; color: #b79cf5; padding-top: 2px; }
.aj-preview-journal { display: flex; gap: 10px; margin-top: 14px; padding-top: 14px; border-top: 1px solid rgba(255,255,255,0.12); font-size: 14px; color: #fff; font-style: italic; }
.aj-preview-systems { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 18px; }
.aj-preview-sys { font-size: 11px; padding: 5px 10px; border-radius: 999px; background: rgba(201,242,78,0.16); color: #d7f79a; }
.admin-anchor-warn { margin: 0 0 16px; padding: 10px 14px; border-radius: 12px; background: rgba(245,176,38,0.12); border: 1px solid rgba(245,176,38,0.4); color: #7a5300; font-size: 13px; font-weight: 500; }

/* Admin nav group headings + RBAC role banner */
.admin-nav-group { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--ink-400); padding: 14px 14px 6px; }
.admin-nav-group:first-child { padding-top: 4px; }
.admin-role-banner { display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap; background: #fff; border: 1px solid var(--line, #e6e2d6); border-radius: 16px; padding: 16px 20px; margin-bottom: 18px; }
.admin-role-eyebrow { font-size: 10px; letter-spacing: 0.2em; color: var(--ink-400); }
.admin-role-name { font-family: var(--font-display); font-weight: 800; font-size: 20px; letter-spacing: -0.02em; margin-top: 4px; display: flex; align-items: center; gap: 10px; }
.admin-role-caps { display: flex; gap: 6px; flex-wrap: wrap; }
.admin-cap-chip { font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; }
.admin-cap-chip.is-on { background: rgba(208,255,58,0.25); color: #2e4400; }
.admin-cap-chip.is-off { background: rgba(12,20,50,0.05); color: var(--ink-400); text-decoration: line-through; }

/* Mentorship manager */
.admin-av-panel { display: flex; justify-content: space-between; align-items: center; gap: 20px; flex-wrap: wrap; background: var(--navy-900); color: #fff; border-radius: 16px; padding: 18px 22px; margin: 4px 0 18px; }
.admin-av-eyebrow { font-size: 10px; letter-spacing: 0.2em; color: var(--gold-400); }
.admin-av-prog { font-family: var(--font-display); font-weight: 800; font-size: 22px; letter-spacing: -0.02em; margin-top: 4px; }
.admin-av-note { color: rgba(255,255,255,0.72); font-size: 13px; margin: 6px 0 0; max-width: 520px; line-height: 1.5; }
.admin-av-links { display: flex; gap: 8px; flex-wrap: wrap; }
.admin-av-panel .btn-ghost { color: #fff; border-color: rgba(255,255,255,0.28); }
.admin-av-panel .btn-ghost:hover { background: rgba(255,255,255,0.08); }
.admin-mentor-app { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; padding: 12px 0; border-top: 1px solid var(--line, #e6e2d6); }
.admin-mentor-app:first-of-type { border-top: none; }
.admin-roster { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 14px; }
.admin-roster-card { border: 1px solid var(--line, #e6e2d6); border-radius: 16px; background: #fff; padding: 16px; display: flex; flex-direction: column; gap: 10px; }
.admin-roster-head { display: flex; align-items: center; gap: 12px; }
.admin-roster-avatar { width: 44px; height: 44px; border-radius: 50%; object-fit: cover; flex: none; display: grid; place-items: center; }
.admin-roster-name { font-weight: 700; font-size: 15px; display: flex; align-items: center; flex-wrap: wrap; }
.admin-roster-cap { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 12px; color: var(--ink-500); }
.admin-roster-mentees { display: flex; flex-wrap: wrap; gap: 6px; }
.admin-roster-pair { width: 100%; }
.admin-mentee-chip { display: inline-flex; align-items: center; gap: 6px; }
.admin-mentee-x { border: none; background: none; cursor: pointer; color: var(--coral); font-size: 11px; line-height: 1; padding: 0; }
.admin-mentee-x:hover { color: #a3331c; }

/* Admin overview analytics + attention */
.admin-attn { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.admin-attn-card { display: flex; align-items: center; gap: 10px; padding: 14px 18px; border-radius: 14px; border: 1px solid rgba(245,176,38,0.4); background: rgba(245,176,38,0.1); cursor: pointer; font-family: inherit; }
.admin-attn-card.admin-attn-warn { border-color: rgba(228,21,95,0.45); background: rgba(228,21,95,0.09); }
.admin-tabs { display: flex; gap: 6px; margin-bottom: 20px; border-bottom: 1px solid rgba(12,20,50,0.1); }
.admin-tab { appearance: none; background: none; border: none; border-bottom: 2px solid transparent; padding: 10px 14px; font-family: inherit; font-size: 14px; font-weight: 600; color: var(--ink-500); cursor: pointer; margin-bottom: -1px; transition: color 0.15s ease, border-color 0.15s ease; }
.admin-tab:hover { color: var(--ink-900); }
.admin-tab.is-active { color: var(--navy-900); border-bottom-color: var(--gold-500); }
.admin-attn-card b { font-family: var(--font-display); font-size: 24px; color: var(--gold-500); }
.admin-attn-card span { font-weight: 600; color: var(--ink-900); }
.admin-attn-card i { margin-left: 6px; color: var(--gold-500); font-style: normal; }
.admin-home-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-top: 20px; }
@media (max-width: 900px) { .admin-home-grid { grid-template-columns: 1fr; } }
.admin-panel { background: #fff; border: 1px solid var(--line, #e6e2d6); border-radius: 16px; padding: 18px; }
.admin-bar-row { display: flex; align-items: center; gap: 10px; margin-top: 10px; font-size: 13px; }
.admin-bar-row span { width: 120px; color: var(--ink-700); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.admin-bar-row b { width: 32px; text-align: right; font-family: var(--font-mono); font-size: 12px; }
.admin-bar { flex: 1; height: 9px; border-radius: 99px; background: #eee; overflow: hidden; }
.admin-bar-fill { height: 100%; background: var(--navy-700); border-radius: 99px; }
.admin-bar-fill.alt { background: var(--gold-500); }
.admin-activity { display: flex; flex-direction: column; gap: 8px; }
.admin-activity-row { display: flex; gap: 10px; align-items: baseline; font-size: 12px; }
.admin-activity-when { color: var(--ink-400); white-space: nowrap; }
.admin-activity-ev { color: var(--navy-700); }
.admin-activity-sub { color: var(--ink-500); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* Member 360° detail */
.admin-row-click { cursor: pointer; }
.admin-row-click:hover { background: #faf9f6; }
.admin-detail { display: flex; flex-direction: column; gap: 18px; }
.admin-prewrap { white-space: pre-wrap; }
.admin-detail-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.admin-detail-stats { display: flex; gap: 10px; flex-wrap: wrap; }
.admin-detail-stats > div { flex: 1; min-width: 72px; background: var(--paper); border: 1px solid var(--line, #e6e2d6); border-radius: 12px; padding: 12px; text-align: center; }
.admin-detail-stats b { display: block; font-family: var(--font-display); font-size: 22px; }
.admin-detail-stats span { font-family: var(--font-mono); font-size: 9px; letter-spacing: .14em; text-transform: uppercase; color: var(--ink-500); }
.admin-detail-section { border-top: 1px solid var(--line, #e6e2d6); padding-top: 14px; }
.admin-detail-h { font-family: var(--font-mono); font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--ink-500); margin-bottom: 10px; }
.admin-detail-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.admin-detail-kv > div { display: flex; gap: 10px; font-size: 14px; padding: 3px 0; }
.admin-detail-kv span { width: 100px; color: var(--ink-500); font-size: 12px; }
.admin-detail-row { display: flex; justify-content: space-between; align-items: center; padding: 8px 0; border-bottom: 1px solid #f0eee8; font-size: 14px; }
.admin-detail-journal { padding: 8px 0; border-bottom: 1px solid #f0eee8; }
.admin-detail-journal p { margin: 4px 0 0; font-size: 14px; color: var(--ink-700); }
.admin-detail-jdate { font-size: 11px; color: var(--ink-400); }

/* Applications */
.admin-app-list { display: flex; flex-direction: column; gap: 12px; }
.admin-app { background: #fff; border: 1px solid var(--line, #e6e2d6); border-radius: 14px; padding: 16px; }
.admin-app-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.admin-app-why { margin: 10px 0; padding: 10px 12px; background: var(--paper); border-radius: 10px; font-size: 14px; line-height: 1.5; color: var(--ink-700); }

/* Why somebody reported this. Sits under the content it is about, because the
   moderator's question is "is this reasonable", and that needs both halves. */
.admin-reports { margin: 10px 0; padding: 10px 12px; border-radius: 10px;
  background: #fdf2f3; border: 1px solid #f0d3d7; }
.admin-reports-h { font-size: 11px; letter-spacing: .09em; text-transform: uppercase;
  color: #8f1a28; margin-bottom: 7px; }
.admin-reports-list { list-style: none; margin: 0; padding: 0; display: flex;
  flex-direction: column; gap: 6px; }
.admin-reports-list li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 9px;
  font-size: 13.5px; line-height: 1.45; color: var(--ink-800, #26221a); }
.admin-reports-by { font-weight: 700; }
.admin-reports-why { flex: 1; min-width: 12ch; }
.admin-reports-at { font-size: 11px; color: var(--ink-500, #6b6558); white-space: nowrap; }

/* A safeguarding case. Marked, not decorated: one left stripe and the child's
   own words set as a quotation, because that is the thing to be read. */
.admin-app-urgent { border-left: 4px solid #a80f28; }
.admin-sg-body { margin: 10px 0; padding: 12px 14px; border-radius: 10px;
  background: var(--paper); border-left: 3px solid var(--line, #e6e2d6);
  font-size: 15px; line-height: 1.6; color: var(--ink-900, #14110b);
  white-space: pre-wrap; font-style: normal; }
.admin-app-actions { display: flex; gap: 10px; align-items: center; margin-top: 4px; flex-wrap: wrap; }
.admin-app-status { max-width: 160px; }

/* Structured applicant / volunteer detail — a readable labelled grid, opened
   from "View details". Cool hairline rows so the data reads clearly. */
.admin-detail { margin: 10px 0; padding: 6px 16px 12px; background: var(--cream-50, #faf6ec); border: 1px solid var(--line-cool, #e5e8ee); border-radius: 12px; }
.admin-detail-photo { width: 72px; height: 72px; border-radius: 12px; object-fit: cover; margin: 12px 0 6px; border: 1px solid var(--line-cool, #e5e8ee); }
.admin-detail-row { display: grid; grid-template-columns: 148px 1fr; gap: 14px; padding: 8px 0; border-top: 1px solid var(--line-cool-soft, #eef0f4); }
.admin-detail-row:first-of-type { border-top: 0; }
.admin-detail-key { font-size: 10.5px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-400); padding-top: 1px; }
.admin-detail-val { font-size: 14px; color: var(--ink-700); line-height: 1.55; word-break: break-word; }
@media (max-width: 560px) { .admin-detail-row { grid-template-columns: 1fr; gap: 2px; } }
.admin-section-actions { display: flex; gap: 8px; align-items: center; }

/* Legal & data-protection page — sticky side-nav collapses on mobile. */
.legal-layout { display: grid; grid-template-columns: 220px 1fr; gap: 40px; align-items: start; }
.legal-nav { position: sticky; top: 90px; display: flex; flex-direction: column; gap: 4px; }
@media (max-width: 760px) {
  .legal-layout { grid-template-columns: 1fr; gap: 20px; }
  .legal-nav { position: static; flex-direction: row; flex-wrap: wrap; gap: 6px; }
  .legal-nav-item { border: 1px solid rgba(12,20,50,0.1); }
}

/* Registration form builder (Summer portal → Form builder tab) */
.fb-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
.fb-field { display: flex; gap: 10px; background: var(--surface, #fff); border: 1px solid rgba(12,20,50,0.1); border-radius: 14px; padding: 14px; }
.fb-field-rail { display: flex; flex-direction: column; gap: 4px; flex: 0 0 auto; }
.fb-move { width: 26px; height: 26px; border-radius: 7px; border: 1px solid rgba(12,20,50,0.12); background: #fff; cursor: pointer; font-size: 13px; color: var(--ink-700); }
.fb-move:disabled { opacity: 0.3; cursor: default; }
.fb-field-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 8px; }
.fb-field-top { display: flex; gap: 8px; align-items: flex-start; }
.fb-label { flex: 1; min-width: 0; font-weight: 600; }
.fb-del { width: 30px; height: 30px; border-radius: 8px; border: 1px solid rgba(228,21,95,0.25); background: rgba(228,21,95,0.06); color: #b03535; cursor: pointer; flex: 0 0 auto; }
.fb-field-meta { display: flex; gap: 16px; align-items: center; flex-wrap: wrap; }
.fb-key { font-size: 11px; color: var(--ink-500); }
.fb-toggle { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--ink-700); }
.fb-options { display: flex; flex-direction: column; gap: 6px; padding-left: 4px; border-left: 2px solid rgba(12,20,50,0.08); }
.fb-option { display: flex; gap: 6px; align-items: center; }
.fb-option .admin-input { flex: 1; }
.fb-help { font-size: 13px; }
/* Builder-only note on a locked field. Indented and quieter than the help
   input above it so it reads as a fact about the field, not as more copy the
   admin is expected to edit. */
.fb-adminhelp {
  margin: 6px 0 0; padding-left: 10px; font-size: 12px; line-height: 1.5;
  border-left: 2px solid var(--line, rgba(12,20,50,.14));
}
.fb-add { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin-top: 16px; padding-top: 16px; border-top: 1px dashed rgba(12,20,50,0.14); }
:root[data-theme="dark"] .fb-field, :root[data-theme="dark"] .fb-move { background: var(--surface-2, #1a1a24); }

/* Site content editor — stack the preview under the form on narrow screens. */
.site-editor { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: start; }
.site-editor-preview { position: sticky; top: 90px; }
@media (max-width: 900px) { .site-editor { grid-template-columns: 1fr; } .site-editor-preview { position: static; } }

/* Programme & policy — the one-line status banner above the calendar editor.
   Tone is data-driven so "today is closed" reads differently from "enforcement
   is on but no calendar is set", which is the mistake worth shouting about. */
.policy-callout {
  margin: 12px 0; padding: 11px 14px; border-radius: 12px;
  font-size: 13.5px; line-height: 1.5;
  border: 1px solid var(--line, #e6e2d6); background: var(--cream-50, #faf7f0);
}
.policy-callout[data-tone="ok"]    { border-color: rgba(110,156,29,.35); background: rgba(110,156,29,.08); }
.policy-callout[data-tone="muted"] { color: var(--ink-500); }
.policy-callout[data-tone="warn"]  { border-color: rgba(224,84,60,.4); background: rgba(224,84,60,.08); }

/* A day the programme did not run is drawn as closed, not as zero attendance:
   a flat Sunday beside a full Friday read as a collapse. */
.summer-attbar-col.is-closed .summer-attbar-track {
  background: repeating-linear-gradient(45deg, rgba(12,20,50,.05) 0 4px, transparent 4px 8px);
}
.summer-attbar-col.is-closed .summer-attbar-lbl { opacity: .45; }
.summer-result-tags { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; margin-top: 8px; }
.summer-result.late { border-color: rgba(224,84,60,.45); }

/* Form-builder conditional logic. Set apart from the field's own settings —
   it describes WHEN the field appears, not what it collects, and reading the
   two as one list makes both harder to scan. */
.fb-logic { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 10px; }
.fb-logic.is-on {
  padding: 9px 11px; border-radius: 10px;
  background: rgba(59, 91, 219, 0.06);
  border: 1px dashed rgba(59, 91, 219, 0.35);
}
.fb-logic-lead { font-size: 10px; font-weight: 800; letter-spacing: 0.13em; color: #3b5bdb; }
.fb-logic .admin-select, .fb-logic .admin-input { font-size: 13px; padding: 6px 9px; }
.fb-logic-warn { flex-basis: 100%; font-size: 12px; color: var(--coral, #e0543c); }

/* Kiosk camera flip — a desk points the rear lens at the card, an all-in-one
   kiosk only has a front one, and a tablet gets turned around mid-shift. */
.summer-cam-flip {
  position: absolute; top: 10px; right: 10px; z-index: 2;
  width: 40px; height: 40px; border-radius: 50%; cursor: pointer; line-height: 1; font-size: 17px;
  border: 1px solid rgba(255,255,255,0.35); background: rgba(0,0,0,0.45); color: #fff;
}

/* ============================================================
   ADMIN ON A PHONE
   The console was built for a desk and measured badly at 390px:
   10px mono labels, table columns you had to scroll to blind, and
   nav rows under the 44px touch minimum. Everything below is
   density and reach — no desktop layout is touched.
   ============================================================ */
@media (max-width: 820px) {
  /* Tabs are the section switcher inside a screen; wrapped onto two lines they
     read as broken headings. Scroll them instead. */
  .admin-tabs {
    flex-wrap: nowrap; overflow-x: auto; gap: 2px;
    scrollbar-width: none; -webkit-overflow-scrolling: touch;
  }
  .admin-tabs::-webkit-scrollbar { display: none; }
  .admin-tab { white-space: nowrap; flex-shrink: 0; }

  /* Pin the first column so the person's name stays on screen while you scroll
     out to their status. Without it you scroll right and lose track of whose
     row you are reading. */
  .admin-table th:first-child,
  .admin-table td:first-child {
    position: sticky; left: 0; z-index: 2;
    background: white;
    box-shadow: 1px 0 0 rgba(12, 20, 50, 0.09);
  }
  .admin-table thead th:first-child { z-index: 3; background: var(--cream-50); }
  /* Right-edge shadow that fades out once you have scrolled to the end — the
     only cue that there is more table off-screen. */
  .admin-table-wrap {
    background:
      linear-gradient(to left, white, rgba(255, 255, 255, 0)) right center,
      radial-gradient(farthest-side at 100% 50%, rgba(12, 20, 50, 0.16), rgba(12, 20, 50, 0)) right center;
    background-repeat: no-repeat;
    background-size: 26px 100%, 12px 100%;
    background-attachment: local, scroll;
  }

  /* 10px mono with 0.18em tracking is a design detail at desk distance and
     unreadable on a phone. Lift the small print, drop the tracking so the
     bigger text does not also get wider. */
  .admin-table th { font-size: 12px; letter-spacing: 0.06em; }
  .admin-cell-sub { font-size: 12px; letter-spacing: 0.01em; }
  .admin-card-meta { font-size: 12px; letter-spacing: 0.04em; }
  .admin-field > span { font-size: 12px; letter-spacing: 0.06em; }
  .admin-nav-group { font-size: 12px; letter-spacing: 0.1em; }
  .admin-main .chip { font-size: 12px; letter-spacing: 0.05em; }

  /* Two name fields side by side leaves ~150px each. Stack them. */
  .admin-fields-row,
  .admin-fields-row:has(> *:nth-child(3)) { grid-template-columns: minmax(0, 1fr); }

  /* The topbar carries the account name plus up to five buttons; on a phone the
     name is the first thing to go — the buttons are the part you tap. */
  .admin-topbar { gap: 10px; }
  .admin-topbar-r { justify-content: flex-end; gap: 8px; }
  .admin-topbar-r > .mono { display: none; }
  .admin-topbar-section { font-size: 16px; }
  /* "NGG · CONTROL ROOM" wrapped to two lines in the corner; the picker below
     already says which section you are in, so the eyebrow can go. */
  .admin-topbar-eyebrow { display: none; }
}

/* Reach, not looks: applies to any touch screen, including a tablet above the
   820px breakpoint where the sidebar is still in use. */
@media (pointer: coarse) {
  .admin-nav-item { min-height: 44px; }
  .admin-tab { min-height: 44px; }
  .admin-card { min-height: 44px; }
  .admin-input, .admin-select { min-height: 44px; }
  .admin-field-check input { width: 22px; height: 22px; }
  /* The console leans on .btn-sm — 32px painted, and it is what "Resend link",
     "+ New member" and the pager arrows all are. These sit inside dense lists
     where 44px would push every row apart; 40px still clears a fingertip. */
  .admin-main .btn-sm,
  .admin-main .btn { min-height: 40px; }
  /* The topbar is NOT a dense list, so the 40px concession above does not
     reach it: its controls sit on one uncrowded row and there is nothing for
     44px to push apart. The Analyst toggle paints 32px and the four ghost
     buttons beside it are .btn-sm, so without this the whole strip a tablet
     operator reaches for first is under the floor. */
  .admin-topbar-r .btn,
  .admin-topbar-r .btn-sm,
  .admin-analyst-btn { min-height: 44px; }

  /* A second tab vocabulary. `.admin-tab` was raised above and
     `.admin-anchor-tab` — the strip on ID cards, the Anchor Journal and the
     Club desk — was not, which is what a parallel vocabulary costs. A tab
     strip is not a dense list, so it takes the full 44 like its twin. */
  .admin-anchor-tab { min-height: 44px; }

  /* Rows in the mission planner: four per week, not forty, so the dense-list
     concession does not apply and they take the full floor. */
  .admin-mission-row { min-height: 44px; }

  /* A checkbox is only as tappable as the label wrapping it, and these labels
     were 28px. The classed form first. */
  .admin-field-check { min-height: 44px; }
  /* Then the ones written inline. `:has()` reaches what a stylesheet otherwise
     cannot — CLAUDE.md §11 is exactly right that inline chrome is where drift
     hides, and these labels are ~30 copies of `display:flex; align-items:center`
     across the console. A net, not an excuse: new checkbox rows should use
     `.admin-field-check`. Browsers without `:has()` keep today's behaviour
     rather than breaking, which is the correct failure for a reach floor. */
  .admin-main label:has(input[type="checkbox"]) { min-height: 44px; }

  /* Two controls styled as text because they sit inside a sentence. They stay
     looking like text and take their reach from padding, so the sentence does
     not grow a button in the middle of it. */
  .admin-guide-toggle,
  .admin-bulk-link { min-height: 44px; padding-top: 12px; padding-bottom: 12px; }
}

/* ============================================================
   WHICH CENTRE, WITHOUT READING
   Centres already carried their own colour and nothing showed it.
   On a list of forty volunteers the centre was a word in small grey
   type, in the same place on every row, so nobody could tell at a
   glance who worked where. The ring is the colour; the code beside
   it is the label, because colour alone is not one.
   ============================================================ */
.centre-ring {
  position: relative; display: inline-block; flex: none;
  border-radius: 50%;
  border: 3px solid rgba(12, 20, 50, 0.18);
  padding: 2px;
  background: white;
}
.centre-ring-img {
  display: block; width: 100%; height: 100%;
  border-radius: 50%; object-fit: cover;
}
.centre-ring-fallback {
  display: grid; place-items: center;
  color: white; font-family: var(--font-display); font-weight: 800;
  font-size: 0.9em; line-height: 1;
}
.centre-ring-code {
  position: absolute; right: -4px; bottom: -4px;
  min-width: 20px; padding: 1px 5px;
  border-radius: 999px; border: 2px solid white;
  color: white; font-size: 10px; font-weight: 800; letter-spacing: 0.02em;
  line-height: 1.4; text-align: center;
  /* White and the shadow are only the fallback for an unparseable colour. The
     real ink comes from inkOn(centre.color) inline, because a shadow does not
     rescue white text on the pale yellow an admin can pick in one click — it
     smudges it. */
  text-shadow: 0 0 2px rgba(0, 0, 0, 0.55);
}

/* Candidate rows in the promote picker. */
.admin-pick-row {
  display: flex; align-items: center; gap: 10px;
  width: 100%; padding: 9px 11px; min-height: 44px;
  background: none; border: none; border-bottom: 1px solid rgba(12, 20, 50, 0.06);
  font-family: inherit; font-size: 14px; color: var(--ink-900); cursor: pointer;
  text-align: left;
}
.admin-pick-row:last-child { border-bottom: none; }
.admin-pick-row:hover { background: rgba(12, 20, 50, 0.04); }
.admin-pick-row.is-on { background: rgba(245, 176, 38, 0.14); box-shadow: inset 3px 0 0 var(--gold-500); }
.admin-pick-row:focus-visible { outline: 2px solid var(--gold-500); outline-offset: -2px; }

/* ============================================================
   WHICH CENTRE SOMEBODY BELONGS TO
   Centres already carried their own colour and nothing showed
   it. On a list of forty volunteers the centre was a word in
   small grey type, in the same place on every row, so nobody
   could tell at a glance who worked where. The ring puts it on
   the photo; the code stays next to it, because colour alone
   is not a label — and one man in twelve cannot read it.
   ============================================================ */
.centre-ring {
  position: relative;
  display: inline-grid;
  place-items: center;
  flex: none;
  border-radius: 50%;
  border: 3px solid rgba(12, 20, 50, 0.18);
  padding: 2px;
  background: white;
}
.centre-ring-img {
  width: 100%; height: 100%;
  border-radius: 50%;
  object-fit: cover;
  display: block;
}
.centre-ring-fallback {
  display: grid; place-items: center;
  color: white;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 0.9em;
}
.centre-ring-code {
  position: absolute;
  bottom: -5px; right: -6px;
  padding: 1px 5px;
  border-radius: 999px;
  border: 2px solid white;
  color: white;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  line-height: 1.4;
  /* The code is small by necessity — it rides on a photo. White plus a shadow is
     the fallback for an unparseable colour; the ink that actually ships is
     inkOn(centre.color), set inline, because a shadow under white on a pale
     centre colour is a smudge rather than a rescue. */
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
  white-space: nowrap;
}

/* A row in the "make someone a mentor" picker. */
.admin-pick-row {
  display: flex; align-items: center; gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border: none;
  border-bottom: 1px solid rgba(12, 20, 50, 0.06);
  background: transparent;
  font-family: inherit; font-size: 14px; color: var(--ink-900);
  text-align: left; cursor: pointer;
}
.admin-pick-row:last-child { border-bottom: none; }
.admin-pick-row:hover { background: rgba(12, 20, 50, 0.04); }
.admin-pick-row.is-on { background: rgba(245, 176, 38, 0.14); box-shadow: inset 3px 0 0 var(--gold-500); }
.admin-pick-row:focus-visible { outline: 2px solid var(--gold-500); outline-offset: -2px; }
@media (pointer: coarse) { .admin-pick-row { min-height: 52px; } }

/* The review desk reads as two columns on a desktop and one on a phone. The
   photo and the answers belong side by side when there is room — a reviewer
   comparing a face against a name should not be scrolling between them. */
.review-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; }
@media (min-width: 900px) {
  .review-grid { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .review-grid > :nth-child(3) { grid-column: 1 / -1; }
}

/* ── Programme journal (community destination) ─────────────────────────────── */
.cm-pj { padding: 18px 20px 60px; max-width: 900px; }
.cm-pj-intro { margin-bottom: 18px; }
.cm-pj-hint { color: var(--ink-500, #5b6478); font-size: 13px; line-height: 1.6; }
.cm-pj-empty { padding: 34px 18px; text-align: center; color: var(--ink-400, #7b8496); font-size: 14px;
  border: 1px dashed rgba(0,0,0,.12); border-radius: 14px; }
.cm-pj-filters { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin: 16px 0 14px; }
.cm-pj-list { display: grid; gap: 12px; }
.cm-pj-card { border: 1px solid rgba(0,0,0,.1); border-radius: 14px; padding: 14px 15px; background: #fff; }
.cm-pj-head { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin-bottom: 8px; }
.cm-pj-title { margin: 0 0 5px; font-size: 15.5px; line-height: 1.35; }
.cm-pj-body { margin: 0 0 8px; font-size: 13.5px; line-height: 1.62; color: var(--ink-600, #46506a); white-space: pre-wrap; }
.cm-pj-meta { font: 600 11.5px var(--font-mono, ui-monospace, monospace); color: var(--ink-400, #7b8496); }
.cm-pj-people { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 9px; }
.cm-pj-person { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 600;
  padding: 3px 9px; border-radius: 999px; background: rgba(0,0,0,.05); }
.cm-pj-person i { font-style: normal; font-size: 10.5px; font-weight: 700; opacity: .6; text-transform: uppercase; letter-spacing: .04em; }
.cm-pj-actions { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 11px; padding-top: 10px; border-top: 1px solid rgba(0,0,0,.07); }
/* Memories — a horizontal rail per collection, like a photo app's resurfacing. */
.cm-pj-mem { display: grid; gap: 16px; margin-bottom: 6px; }
.cm-pj-memhead { display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap; margin-bottom: 8px; }
.cm-pj-memhead b { font-size: 14.5px; }
.cm-pj-memhead span { font-size: 12px; color: var(--ink-400, #7b8496); }
.cm-pj-memscroll { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 6px; scroll-snap-type: x proximity; }
.cm-pj-memscroll > * { scroll-snap-align: start; flex: 0 0 auto; }
/* Editor sheet */
.cm-pj-modal { position: fixed; inset: 0; z-index: 320; background: rgba(6,10,24,.6);
  display: grid; place-items: center; padding: 18px; }
.cm-pj-sheet { background: #fff; border-radius: 16px; padding: 20px; width: 100%; max-width: 560px;
  max-height: 90vh; overflow-y: auto; }
.cm-pj-lab { display: block; font-size: 12.5px; font-weight: 700; margin-bottom: 10px; }
.cm-pj-in { display: block; width: 100%; box-sizing: border-box; margin-top: 4px; padding: 9px 11px;
  font: inherit; font-size: 14px; border: 1px solid rgba(0,0,0,.16); border-radius: 10px; }
.cm-pj-row { display: flex; gap: 10px; flex-wrap: wrap; }
.cm-pj-row .cm-pj-lab { flex: 1 1 130px; }
@media (max-width: 620px) { .cm-pj { padding: 14px 14px 60px; } }

/* Surfaces that own the whole screen (see OWN_CHROME_PAGES in app.jsx): the
   staff console and portals, the gate desk, the guardian pages and the public
   registration form. The floating helpers are positioned for a normal page with
   a footer below it; over a full-screen form they land on top of content — on a
   phone the ⌘K hint sat directly on a field's help text. Belt and braces with
   CommandHint's own check, so a float added later is suppressed by default. */
body.own-chrome .cmdk-hint,
body.own-chrome .fab-top { display: none; }

/* ============================================================
   ID DESIGNER
   Three columns: layers, canvas, properties. The canvas column
   is the only one that grows — the rails hold controls whose
   width is set by their content, and a designer needs the card
   as large as the screen allows, not a fair split.
   ============================================================ */
.dsn-grid {
  display: grid;
  grid-template-columns: 210px minmax(0, 1fr) 300px;
  gap: 16px;
  align-items: start;
}
/* The designer runs on the studio's navy shell, and .btn-ghost / .admin-select
   are drawn for the LIGHT admin console — a ghost button there is dark ink on a
   transparent background, which on navy is invisible rather than subtle. Scoped
   here rather than changed globally, because every other screen using them is on
   white and is correct as it is. */
.dsn-bar { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-bottom: 14px; }
/* The ghost button on a DARK surface.
   `.btn-ghost` is `color: var(--ink-900)` — near-black navy — because every
   other screen that uses it is on white. The studio is not, and this override
   was scoped to the toolbar and the rail only, so the same button rendered
   dark-navy-on-dark-navy everywhere else in the studio: Close, Select all,
   Clear, Prev, Next, "PDF · imposed sheet" and "ZIP of images" were all around
   1.1:1, which is not "hard to read", it is invisible. Enabled controls that
   look like nothing at all.

   Scoped to the studio's panels rather than fixed globally, because the light
   screens are correct as they are. */
.dsn-bar .btn-ghost,
.dsn-rail .btn-ghost,
.dsn-merge .btn-ghost,
.dsn-exports .btn-ghost,
.dsn-flight .btn-ghost,
.dsn-props .btn-ghost {
  border: 1px solid rgba(255, 255, 255, 0.25);
  background: transparent; color: #eef2fb;
}
.dsn-bar .btn-ghost:hover:not(:disabled) { background: rgba(255, 255, 255, 0.1); }
.dsn-merge .btn-ghost:hover:not(:disabled),
.dsn-exports .btn-ghost:hover:not(:disabled),
.dsn-flight .btn-ghost:hover:not(:disabled) { background: rgba(255, 255, 255, 0.1); }
/* Disabled has to read as DISABLED and not as broken. The global rule dims to
   an opacity that, over an already-dim ghost on dark, lands somewhere nobody
   can classify — so on this surface it keeps its outline and loses its fill,
   which is legible as "not now" rather than as a rendering fault. */
.dsn-merge .btn-ghost:disabled,
.dsn-exports .btn-ghost:disabled {
  opacity: 1; color: rgba(238, 242, 251, 0.42);
  border-color: rgba(255, 255, 255, 0.12); cursor: default;
}
.dsn-bar .btn-primary { background: #f5b026; color: #2b2100; border: none; }
.dsn-bar .btn-primary:disabled { opacity: 0.45; }
.dsn-bar .admin-select, .dsn-bar .admin-input {
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.07);
  color: #fff;
}
.dsn-bar .admin-select option, .dsn-bar .admin-select optgroup { color: #16223e; }
.dsn-rail .btn-ghost {
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: transparent; color: #eef2fb;
}
.dsn-rail .btn-ghost:hover:not(:disabled) { background: rgba(255, 255, 255, 0.1); }
@media (max-width: 1080px) { .dsn-grid { grid-template-columns: 1fr; } }
.dsn-rail {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 14px;
  padding: 12px;
  max-height: 620px;
  overflow-y: auto;
}
.dsn-rail-head {
  font: 700 10px var(--font-mono, monospace);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(230, 238, 255, 0.6);
  margin-bottom: 8px;
}
.dsn-layer {
  display: flex; align-items: center; gap: 7px;
  width: 100%; padding: 7px 9px; margin-bottom: 4px;
  border-radius: 9px; border: 1px solid transparent;
  background: rgba(255, 255, 255, 0.05); color: #eef2fb;
  font: inherit; font-size: 12.5px; text-align: left; cursor: pointer;
}
.dsn-layer:hover { background: rgba(255, 255, 255, 0.1); }
.dsn-layer.is-on { border-color: #f5b026; background: rgba(245, 176, 38, 0.16); }
.dsn-layer-type {
  font: 700 9px var(--font-mono, monospace); letter-spacing: 0.08em;
  text-transform: uppercase; color: rgba(230, 238, 255, 0.5); flex: none;
}
.dsn-layer-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* A bound element is the whole point of the tool, so it is marked in the layer
   list rather than only discoverable by selecting it. */
.dsn-bound {
  flex: none; font: 700 9px var(--font-mono, monospace); letter-spacing: 0.06em;
  padding: 2px 5px; border-radius: 5px; background: rgba(111, 220, 157, 0.2); color: #6fdc9d;
}
.dsn-adds { display: flex; flex-wrap: wrap; gap: 6px; }
.dsn-stage {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px; padding: 18px;
  display: flex; flex-direction: column; align-items: center; gap: 10px;
}
.dsn-canvas-host { line-height: 0; box-shadow: 0 18px 46px rgba(0, 0, 0, 0.42); border-radius: 6px; overflow: hidden; }
.dsn-stage-note { font: 400 11.5px var(--font-mono, monospace); color: rgba(230, 238, 255, 0.5); }
.dsn-hint { font-size: 12.5px; color: rgba(230, 238, 255, 0.55); line-height: 1.5; }
/* The merge run's progress bar. Determinate, because the run knows exactly how
   many pieces it has — an indeterminate spinner on a job that can last minutes
   tells somebody nothing they can act on. */
.dsn-run { flex: 1 1 120px; min-width: 90px; max-width: 220px; height: 6px;
  border-radius: 999px; background: rgba(255, 255, 255, 0.12); overflow: hidden; }
.dsn-run span { display: block; height: 100%; border-radius: 999px;
  background: var(--gold-500, #f5b026); transition: width .18s linear; }
@media (prefers-reduced-motion: reduce) { .dsn-run span { transition: none; } }
/* A hint that is bad news, and one that is a caveat.

   Contrast was never the problem here — the old #ff9a9a measured 8.5:1 on this
   panel. The problem was that colour was the ONLY signal: two paragraphs in
   the same place, the same size and the same weight, differing by hue, one of
   them meaning "your roster did not load" and neither of them announced. Red
   and amber are also the pair most people with a colour vision deficiency
   cannot separate.

   So: a bold lead sentence that says which it is in words, a left bar and a
   tinted well so it is visibly not ordinary help text, and role="alert" /
   role="status" in the markup so it is heard as well as seen. */
.dsn-hint-bad, .dsn-hint-warn {
  margin-top: 10px; padding: 8px 11px; border-radius: 8px;
  border-left: 3px solid currentColor; background: rgba(255, 255, 255, 0.05);
}
.dsn-hint-bad { color: #ffb0b0; }
.dsn-hint-warn { color: #ffd68a; }
.dsn-hint-bad b, .dsn-hint-warn b { display: block; }
/* minmax(0, 1fr), not 1fr: a grid track sized 1fr has an automatic MINIMUM of
   its content, so a number input with a default size pushes the column wider
   than the rail and the second one is simply cut off the edge. */
.dsn-props { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 8px; margin-bottom: 10px; }
.dsn-props input, .dsn-props select { min-width: 0; width: 100%; box-sizing: border-box; }
.dsn-prop-wide input, .dsn-prop-wide select { min-width: 0; width: 100%; box-sizing: border-box; }
.dsn-rail { overflow-x: hidden; }
.dsn-prop, .dsn-prop-wide { display: flex; flex-direction: column; gap: 4px; margin-bottom: 8px; }
.dsn-prop span, .dsn-prop-wide span {
  font: 700 9.5px var(--font-mono, monospace); letter-spacing: 0.1em;
  text-transform: uppercase; color: rgba(230, 238, 255, 0.55);
}
.dsn-prop input, .dsn-prop-wide input, .dsn-prop select, .dsn-prop-wide select {
  padding: 7px 9px; border-radius: 8px; font-size: 13px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.07); color: #fff;
}
.dsn-prop input[type="color"] { padding: 2px; height: 32px; }
.dsn-check {
  display: flex; align-items: center; gap: 7px;
  font-size: 12.5px; color: rgba(230, 238, 255, 0.8); margin-bottom: 7px; cursor: pointer;
}
/* Preflight. Colour-coded, but never colour ALONE — the heading says which
   state it is in, because one reader in twelve cannot tell the border colours
   apart and this is the panel that decides whether 300 cards print. */
.dsn-flight {
  margin-top: 16px; padding: 12px 16px; border-radius: 12px;
  font-size: 13px; line-height: 1.55;
  background: rgba(111, 220, 157, 0.08); border: 1px solid rgba(111, 220, 157, 0.35);
}
.dsn-flight.is-warn { background: rgba(245, 176, 38, 0.09); border-color: rgba(245, 176, 38, 0.4); }
.dsn-flight.is-bad { background: rgba(255, 90, 90, 0.09); border-color: rgba(255, 90, 90, 0.42); }
.dsn-flight ul { margin: 7px 0 0; padding-left: 18px; }
.dsn-flight li { margin: 3px 0; color: rgba(230, 238, 255, 0.78); }
.dsn-flight li.is-bad { color: #ff9a9a; }
/* The photo editors mount into a panel that is always in the DOM: Filerobot
   calls createRoot on it, and a display:none element has no layout for it to
   measure — the same reason the card exporter stages off-screen. */
.dsn-photo { margin-top: 18px; display: none; }
.dsn-photo.is-open { display: block; }
.dsn-photo-bar {
  display: flex; align-items: center; gap: 10px; margin-bottom: 8px;
  font-size: 13.5px; color: #eef2fb;
}
.dsn-photo-bar b { flex: 1; }

/* ── Designer: the tool row and the brand kit ──────────────────────────────
   Separate from .dsn-bar because these act on the CANVAS, not on the document,
   and mixing the two into one strip made "Publish" sit next to "zoom in". */
.dsn-tools {
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px;
  margin: 0 0 14px;
  padding: 8px 10px; border-radius: 12px;
  background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.12);
}
.dsn-tool-grp {
  display: flex; gap: 2px; padding-right: 8px;
  border-right: 1px solid rgba(255, 255, 255, 0.12);
}
.dsn-tool-grp:last-of-type { border-right: none; }
.dsn-tool {
  min-width: 32px; height: 32px; padding: 0 8px;
  border-radius: 8px; border: 1px solid transparent;
  background: transparent; color: #eef2fb;
  font: inherit; font-size: 14px; line-height: 1; cursor: pointer;
}
.dsn-tool:hover:not(:disabled) { background: rgba(255, 255, 255, 0.12); }
.dsn-tool:disabled { opacity: 0.3; cursor: not-allowed; }
.dsn-tool.is-on { background: rgba(245, 176, 38, 0.22); border-color: #f5b026; }
.dsn-size-note {
  margin-left: auto; font: 400 11.5px var(--font-mono, monospace);
  color: rgba(230, 238, 255, 0.55);
}
.dsn-exports { display: flex; gap: 4px; }
/* Layer rows carry actions now, so the row is a flex container and the label is
   the button — a nested button inside a button is invalid and swallows clicks. */
.dsn-layer { padding: 0; overflow: hidden; }
.dsn-layer-hit {
  flex: 1; min-width: 0; display: flex; align-items: center; gap: 7px;
  padding: 7px 4px 7px 9px; border: none; background: none; color: inherit;
  font: inherit; font-size: 12.5px; text-align: left; cursor: pointer;
}
.dsn-layer-ic {
  flex: none; width: 24px; height: 26px; padding: 0;
  border: none; background: none; cursor: pointer;
  font-size: 11px; line-height: 1; opacity: 0.65;
}
.dsn-layer-ic:hover { opacity: 1; }
.dsn-swatches { display: grid; grid-template-columns: repeat(8, 1fr); gap: 4px; }
.dsn-swatch {
  aspect-ratio: 1 / 1; border-radius: 6px; cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.25); padding: 0;
}
.dsn-swatch:hover { outline: 2px solid #f5b026; outline-offset: 1px; }

/* The design asset library. A grid of thumbnails rather than a list: you
   recognise a photograph by looking at it, and a filename tells you nothing
   about which of four crops of the same face this one is. */
.dsn-assets {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px;
  max-height: 210px; overflow-y: auto;
}
.dsn-asset {
  position: relative; padding: 0; border-radius: 7px; overflow: hidden; cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.16); background: rgba(255, 255, 255, 0.06);
  aspect-ratio: 1 / 1;
}
.dsn-asset:hover { border-color: #f5b026; }
.dsn-asset img { width: 100%; height: 100%; object-fit: cover; display: block; }
/* The name sits over the image because the tile is small and a caption row
   would halve the thumbnail — the picture is the thing being chosen. */
.dsn-asset-name {
  position: absolute; left: 0; right: 0; bottom: 0; padding: 6px 4px 3px;
  font-size: 9px; line-height: 1.1; color: #fff; text-align: left;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.72));
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

/* ── Data merge ──────────────────────────────────────────────────────────────
   One design, one piece per person. It sits above the canvas rather than in a
   modal so the proof is still on screen while a run is being cut — the whole
   value of a merge is knowing what the two hundred and fortieth one looks
   like. */
.dsn-merge {
  border: 1px solid rgba(255, 255, 255, 0.14); border-radius: 14px;
  background: rgba(255, 255, 255, 0.045); padding: 14px 16px; margin-bottom: 14px;
}
.dsn-merge-head { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.dsn-merge-head b { font-size: 14px; }
.dsn-merge-note {
  flex: 1; font: 400 12px var(--font-mono, monospace); color: rgba(230, 238, 255, 0.6);
}
.dsn-merge-filters {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 8px 10px;
}
.dsn-merge-filters .dsn-prop { margin-bottom: 0; }
.dsn-merge-q { grid-column: span 2; }
/* "Summer School participants" is 24 characters against a 150px auto-fit
   column, and a native select clips rather than wraps — so the widest option
   in the set decides the cell, not the cell the option. */
.dsn-merge-who { grid-column: span 2; }
/* The caveat under the date pair. Its own grid cell rather than a title
   attribute: a hint nobody can see until they hover is a hint for nobody. */
.dsn-date-fmt {
  grid-column: 1 / -1; align-self: center;
  font: 400 11px var(--font-mono, monospace); color: rgba(230, 238, 255, 0.62);
}
.dsn-merge-picks { display: flex; align-items: center; gap: 6px; margin: 12px 0 8px; }
/* A TABLE, not a wall of tick-boxes.
   It was a wrapping grid of cards in insertion order inside a 520px box, which
   is fine at two hundred and unusable at a thousand: no landmarks, no way to
   bring the ones you want to the top, and no way to answer "which of these
   will print with a hole in it" short of reading every row. Columns you can
   order by, a page at a time. */
.dsn-merge-list { max-height: min(48vh, 460px); overflow: auto; }
.dsn-tbl { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.dsn-tbl th, .dsn-tbl td {
  padding: 0 10px; height: 34px; text-align: left; white-space: nowrap;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}
.dsn-tbl thead th {
  position: sticky; top: 0; z-index: 1; padding: 0;
  background: #141c31; border-bottom-color: rgba(255, 255, 255, 0.16);
}
.dsn-th button {
  display: flex; align-items: center; gap: 6px; width: 100%; height: 34px;
  padding: 0 10px; border: 0; background: none; cursor: pointer;
  font: 700 9.5px var(--font-mono, monospace); letter-spacing: .12em; text-transform: uppercase;
  color: rgba(230, 238, 255, 0.55);
}
.dsn-th.is-num button { justify-content: flex-end; }
.dsn-th button:hover { background: rgba(255, 255, 255, 0.06); color: #fff; }
.dsn-th button:focus-visible { outline: 2px solid var(--gold-500, #f5b026); outline-offset: -2px; }
.dsn-th-ind { font-size: 8px; opacity: .35; }
.dsn-th.is-on button { color: #fff; }
.dsn-th.is-on .dsn-th-ind { opacity: 1; color: var(--gold-500, #f5b026); }
.dsn-th-tick { width: 34px; }
.dsn-th-tick:not(#_):not(#_) { padding: 0 0 0 10px; }
.dsn-tbl tbody tr:hover td { background: rgba(255, 255, 255, 0.04); }
.dsn-tbl tbody tr.is-on td { background: rgba(245, 176, 38, 0.09); }
.dsn-td-who { max-width: 190px; overflow: hidden; text-overflow: ellipsis; }
.dsn-td-mono {
  font: 400 11px var(--font-mono, monospace); color: rgba(230, 238, 255, 0.62);
  max-width: 150px; overflow: hidden; text-overflow: ellipsis;
}
.dsn-td-mono.is-num { text-align: right; font-variant-numeric: tabular-nums; }

/* The two filters an operator actually reaches for, as chips rather than a
   third select nobody opens. */
.dsn-chips { display: inline-flex; gap: 4px; margin-left: 4px; }
.dsn-chip {
  min-height: 28px; padding: 0 11px; border-radius: 999px; cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.16); background: none;
  font-weight: 600; font-size: 11.5px; font-family: inherit; color: rgba(230, 238, 255, 0.72);
}
.dsn-chip:hover { border-color: rgba(255, 255, 255, 0.34); color: #fff; }
.dsn-chip.is-on { background: var(--gold-500, #f5b026); border-color: var(--gold-500, #f5b026); color: #2b2100; }
.dsn-chip:focus-visible { outline: 2px solid var(--gold-500, #f5b026); outline-offset: 2px; }
.dsn-chip-n {
  font: 700 10px var(--font-mono, monospace); font-variant-numeric: tabular-nums;
  opacity: .72; margin-left: 3px;
}
/* A count worth acting on, marked as one. Amber and a number, not a red dot:
   twelve children with no photograph is a fact to deal with before the run,
   not an error state. Off entirely when the count is zero, because a warning
   that is always on is furniture. */
.dsn-chip.is-warn { border-color: rgba(255, 214, 138, 0.5); color: #ffd68a; }
.dsn-chip.is-warn.is-on { background: #ffd68a; border-color: #ffd68a; color: #2b2100; }

.dsn-merge-all { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; cursor: pointer; }
.dsn-merge-pager {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding-top: 8px; margin-top: 2px;
}
.dsn-merge-size:not(#_):not(#_) { margin-bottom: 0; }
.dsn-merge-size select { min-width: 68px; }
/* Over the renderer's ceiling. Amber and a sentence, not a red dot: it is a
   fact to act on before the run, not a failure. */
.dsn-merge-note.is-over { color: #ffd68a; font-weight: 700; }

/* ── Seeing the actual card ──────────────────────────────────────────────────
   The table says Chidi has no photograph. The card SHOWS the grey rectangle
   where a face goes, which is the only form of that fact anybody can act on
   before four hundred pieces are printed. */
.dsn-cards {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
  gap: 12px; padding: 4px 2px 8px;
}
.dsn-card-art { position: relative; }
/* On the artwork, top-left, on a ground of its own.
   `accent-color` paints the CHECKED state only; unchecked, a browser draws a
   white box with a hairline border, which on the white face of an ID card is
   weak. The pad makes the control read on any artwork, light or dark.

   Worth being honest about how this got here: I twice diagnosed "the first
   row has no ticks" as a paint problem — first contrast, then a sticky
   toolbar covering them — and was wrong both times. The list's own scroller
   was simply offset, so row one was above its viewport. The pad is a real
   improvement and it fixed nothing; see the scroll reset in DsnMergePicker
   for what actually did. */
.dsn-card-tick {
  position: absolute; top: 6px; left: 6px; z-index: 1;
  width: 20px; height: 20px; accent-color: var(--dsn-gold, #f5b026); cursor: pointer;
  border-radius: 5px; box-shadow: 0 0 0 4px rgba(12, 18, 33, .82), 0 1px 3px rgba(0, 0, 0, .5);
}
.dsn-card-tick:focus-visible { outline: 2px solid var(--gold-500, #f5b026); outline-offset: 4px; }
/* What is wrong with this one, in words, across the bottom of the artwork —
   the grid exists to be scanned, and a bare "!" makes you hover to find out. */
.dsn-card-warn {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 1;
  padding: 3px 6px; text-align: center;
  font: 700 8.5px var(--font-mono, monospace); letter-spacing: .05em; text-transform: uppercase;
  color: #2b2100; background: rgba(255, 214, 138, 0.94);
}
.dsn-card {
  border-radius: 10px; overflow: hidden; background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.12);
}
.dsn-card.is-on { border-color: var(--gold-500, #f5b026); background: rgba(245, 176, 38, 0.1); }
/* The one on the canvas right now. A second, different mark from "ticked":
   proofing and including are different decisions. */
.dsn-card.is-proof { box-shadow: 0 0 0 2px #7fb2ff; }
.dsn-thumb {
  display: block; position: relative; width: 100%; height: 0;
  background: rgba(0, 0, 0, 0.25);
}
.dsn-thumb img, .dsn-thumb-wait { position: absolute; inset: 0; width: 100%; height: 100%; }
.dsn-thumb img { object-fit: contain; display: block; }
/* The frame it will fill, so a grid of forty does not jump as each one lands.
   A pulse rather than a spinner: forty spinners is a disco. */
.dsn-thumb-wait { background: rgba(255, 255, 255, 0.05); animation: dsn-thumb-pulse 1.4s ease-in-out infinite; }
@keyframes dsn-thumb-pulse { 0%, 100% { opacity: .5; } 50% { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .dsn-thumb-wait { animation: none; } }

.dsn-card-name {
  display: flex; flex-direction: column; gap: 1px; width: 100%; min-width: 0;
  padding: 7px 9px 8px; border: 0; background: none; cursor: pointer; text-align: left; font: inherit;
}
.dsn-card-name b { font-size: 11.5px; color: #eef2fb; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dsn-card-name span { font: 400 9.5px var(--font-mono, monospace); color: rgba(230, 238, 255, 0.5); }
.dsn-card-name:hover b { text-decoration: underline; }
.dsn-card-name:focus-visible, .dsn-proof:focus-visible {
  outline: 2px solid var(--gold-500, #f5b026); outline-offset: 2px; border-radius: 3px; }
.dsn-card .dsn-merge-flag { flex: none; padding: 1px 6px; }

/* The name in the list view is the same control as the name on a card. */
.dsn-proof {
  padding: 0; border: 0; background: none; cursor: pointer;
  font: inherit; font-weight: 600; color: inherit; text-align: left;
}
.dsn-proof:hover { text-decoration: underline; }
.dsn-tbl tbody tr.is-proof td { box-shadow: inset 2px 0 0 #7fb2ff; }
.dsn-view { margin-left: 0; }
/* Amber, not red: a child with no photograph is not an error, it is a fact the
   operator has to decide about before three hundred pieces are printed. */
.dsn-merge-flag {
  font: 700 9px var(--font-mono, monospace); letter-spacing: .06em; text-transform: uppercase;
  color: #ffce54; border: 1px solid rgba(255, 206, 84, 0.42); border-radius: 5px;
  padding: 2px 5px; white-space: nowrap;
}
.dsn-merge-run {
  display: flex; align-items: center; flex-wrap: wrap; gap: 8px;
  margin-top: 12px; padding-top: 12px; border-top: 1px solid rgba(255, 255, 255, 0.1);
}
.dsn-merge-run .dsn-prop { margin-bottom: 0; min-width: 150px; }

/* ══════════════════════════════════════════════════════════════════════════
   The Analyst pane
   ══════════════════════════════════════════════════════════════════════════
   Briefs, not bubbles. Each answer opens with what happened, states the
   finding, and carries its confidence, its sources and its next steps as real
   targets — the same rhythm the analytics sections use, so the pane reads as
   part of the console rather than as a chat window bolted to it.

   Your own questions are a quiet mono line rather than a bubble: the analyst is
   the one doing the talking and should look like it.                          */
.anp {
  display: flex; flex-direction: column; min-height: 0;
  background: #fcfcfd; border-left: 1px solid #e2e6ee;
  font-size: 13.5px; color: var(--ink-900, #0a1130);
}
.anp-head {
  flex: none; display: flex; align-items: center; gap: 8px;
  background: #fff; border-bottom: 1px solid #e8ebf1; padding: 12px 12px 12px 16px;
}
.anp-title { font-family: var(--font-display, Sora, sans-serif); font-size: 15px; font-weight: 800; letter-spacing: -0.01em; }
.anp-level {
  font-family: var(--font-mono, monospace); font-size: 10.5px;
  letter-spacing: 0.16em; text-transform: uppercase; color: #7a5600;
}
.anp-new {
  display: inline-flex; align-items: center; gap: 5px; height: 28px; padding: 0 11px;
  border: 0; border-radius: 10px; background: var(--navy-900, #0c1432); color: #fff;
  font-family: inherit; font-size: 12px; font-weight: 700; cursor: pointer; white-space: nowrap;
}
.anp-ic {
  width: 28px; height: 28px; border-radius: 10px; flex: none;
  background: #f7f8fb; border: 1px solid #e5e8ee; color: #3d4761;
  display: grid; place-items: center; cursor: pointer; font-size: 12px;
}
.anp-ic:hover { background: #eef0f6; }
.anp-ic.is-on { background: var(--navy-900, #0c1432); border-color: var(--navy-900); color: #fff; }

.anp-follow {
  flex: none; display: flex; align-items: center; gap: 8px;
  background: #fff; border-bottom: 1px solid #e8ebf1; padding: 8px 14px 8px 16px;
}
.anp-dot { width: 6px; height: 6px; border-radius: 50%; background: #16a34a; flex: none; }
.anp-follow-t {
  font-size: 12px; color: var(--ink-500, #5a6488);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.anp-threads { flex: none; background: #fff; border-bottom: 1px solid #e8ebf1; padding: 10px 12px 11px 16px; }
.anp-threads-h {
  display: flex; align-items: center; gap: 8px; margin-bottom: 7px;
  font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.13em; text-transform: uppercase; color: var(--ink-500, #5a6488);
}
.anp-link { border: 0; background: transparent; padding: 0; cursor: pointer; font-weight: 700; font-size: 11px; font-family: inherit; color: #7a5600; }
.anp-thread {
  display: flex; align-items: stretch; border-radius: 10px; overflow: hidden;
  border: 1px solid transparent; margin-bottom: 3px;
}
.anp-thread:hover { background: #f7f8fb; border-color: #eef0f4; }
.anp-thread.is-on { background: #f3ecdb; border-color: #e8dec6; }
.anp-thread-hit {
  flex: 1; min-width: 0; display: flex; align-items: center; gap: 9px;
  padding: 6px 9px; border: 0; background: transparent; cursor: pointer;
  font-weight: 500; font-size: 12px; font-family: inherit; color: var(--ink-900, #0a1130); text-align: left;
}
.anp-thread.is-on .anp-thread-hit { font-weight: 700; }
.anp-thread-dot { width: 6px; height: 6px; border-radius: 50%; background: #c3cadb; flex: none; }
.anp-thread.is-on .anp-thread-dot { background: #7a5600; }
.anp-thread-t { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.anp-thread-n { font-family: var(--font-mono, monospace); font-size: 10.5px; color: var(--ink-500, #5a6488); flex: none; }
.anp-thread-ic {
  width: 24px; flex: none; border: 0; background: transparent; cursor: pointer;
  font-size: 10.5px; color: #97a0b8;
}
.anp-thread-ic:hover { color: var(--ink-900, #0a1130); }

.anp-scroll { flex: 1; overflow-y: auto; min-height: 0; padding: 16px 16px 6px; display: flex; flex-direction: column; gap: 16px; }
.anp-starters { display: flex; flex-direction: column; gap: 8px; }
.anp-lead { margin: 0 0 4px; font-size: 13px; line-height: 1.6; color: var(--ink-500, #5a6488); }
.anp-starter {
  text-align: left; padding: 10px 12px; border-radius: 10px; cursor: pointer;
  border: 1px solid #e5e8ee; background: #fff; font-weight: 500; font-size: 13px; font-family: inherit;
  line-height: 1.45; color: var(--ink-800, #25304a);
}
.anp-starter:hover { border-color: #cbd2e2; background: #f7f8fb; }

.anp-turn { display: flex; flex-direction: column; gap: 8px; }
/* A mono line, not a bubble. */
.anp-you {
  display: flex; align-items: baseline; gap: 7px;
  font-size: 13px; line-height: 1.5; color: var(--ink-800, #25304a); font-weight: 500;
}
.anp-you-tag {
  font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.1em; color: #7a5600; flex: none;
}
.anp-edit { border: 0; background: transparent; cursor: pointer; color: #97a0b8; font-size: 12px; flex: none; padding: 0 2px; }
.anp-edit:hover { color: var(--ink-900); }

.anp-ans { background: #fff; border: 1px solid #e5e8ee; border-radius: 14px 14px 14px 4px; padding: 13px 14px 11px; }
.anp-ans.is-bad { border-color: #f0d5d5; }
.anp-ans.is-warn { border-color: #eadfc2; }

.anp-trace {
  width: 100%; display: flex; align-items: center; gap: 8px; margin-bottom: 11px;
  padding: 6px 9px; background: #f7f8fb; border: 1px solid #eef0f4; border-radius: 10px;
  cursor: pointer; font-family: var(--font-mono, monospace); font-size: 10.5px; text-align: left;
}
.anp-trace b { color: #3d4761; flex: none; font-weight: 700; }
.anp-trace-ck { color: #15803d; flex: none; font-weight: 700; }
.anp-trace-ck.is-bad { color: #b91c1c; }
.anp-trace-d { color: var(--ink-500, #5a6488); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.anp-trace-ch { color: var(--ink-500); flex: none; }
.anp-tracebody {
  margin: -6px 0 11px; padding: 9px 11px;
  border: 1px solid #eef0f4; border-top: none; border-radius: 0 0 8px 8px; background: #fcfcfd;
  font-family: var(--font-mono, monospace); font-size: 10.5px; line-height: 1.5; color: var(--ink-500, #5a6488);
}
.anp-step { display: flex; gap: 8px; padding: 2px 0; }
.anp-step > span { color: #15803d; flex: none; }
.anp-step.is-bad, .anp-step.is-bad > span { color: #b45309; }
.anp-trace-restated { color: var(--ink-800, #25304a); font-weight: 700; padding-bottom: 5px; }
.anp-trace-why { padding-top: 5px; }
.anp-trace-fp { padding-top: 5px; color: #97a0b8; word-break: break-all; }

.anp-ungrounded { margin: 0 0 9px; font-size: 13px; line-height: 1.5; color: #b91c1c; font-weight: 600; }
.anp-unans { margin: 0 0 7px; font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: #b45309; }
.anp-body { font-size: 13.5px; line-height: 1.62; color: var(--ink-800, #25304a); white-space: pre-wrap; }

.anp-claims { display: grid; gap: 10px; margin-top: 12px; }
.anp-claim { padding-left: 11px; border-left: 2px solid #e2e6ee; }
.anp-claim.is-bad { border-left-color: #ef4444; }
.anp-claim-t { font-size: 13px; line-height: 1.5; }
.anp-claim-m {
  display: flex; gap: 8px; flex-wrap: wrap; align-items: baseline; margin-top: 3px;
  font-size: 12px; color: var(--ink-500, #5a6488);
}
.anp-claim-m b { color: #b91c1c; }

/* Next steps as targets, not suggestions inside a paragraph. */
.anp-actions { margin-top: 12px; border-top: 1px solid #f0f2f6; }
.anp-action {
  width: 100%; display: flex; align-items: center; gap: 10px; padding: 9px 0;
  border: 0; border-bottom: 1px solid #f4f5f8; background: transparent;
  font-weight: 600; font-size: 12.5px; font-family: inherit; color: var(--navy-700, #1c2a5e); text-align: left; cursor: pointer;
}
.anp-action:hover { color: var(--navy-900); }
.anp-action:disabled { opacity: 0.5; cursor: default; }
.anp-action i {
  width: 22px; height: 22px; border-radius: 50%; background: #f3ecdb; color: #7a5600;
  display: grid; place-items: center; flex: none; font-style: normal; font-size: 12px; font-weight: 700;
}
.anp-action span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.anp-action em { color: #8891a6; font-style: normal; flex: none; }

.anp-conf { display: flex; align-items: center; gap: 9px; margin-top: 12px; }
.anp-meter {
  display: inline-flex; align-items: center; gap: 6px; flex: none;
  background: #f3ecdb; border-radius: 6px; padding: 3px 7px;
}
.anp-meter i { width: 5px; height: 7px; border-radius: 6px; background: #dfd6bd; display: block; }
.anp-meter i.on { background: var(--navy-900, #0c1432); }
.anp-meter b { font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700; color: var(--navy-900); }
.anp-sources {
  font-family: var(--font-mono, monospace); font-size: 10.5px; color: var(--ink-500, #5a6488);
  flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.anp-tools { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; margin-top: 10px; padding-top: 10px; border-top: 1px solid #f4f5f8; }
.anp-tool {
  display: inline-flex; align-items: center; gap: 5px; padding: 4px 9px;
  border: 1px solid #e5e8ee; border-radius: 10px; background: #fff;
  font-weight: 600; font-size: 11.5px; font-family: inherit; color: #3d4761; cursor: pointer; white-space: nowrap;
}
.anp-tool:hover { border-color: #cbd2e2; }
.anp-tool:disabled { opacity: 0.45; cursor: default; }
.anp-tool.is-on, .anp-tool.is-solid { background: var(--navy-900, #0c1432); border-color: var(--navy-900); color: #fff; }

.anp-working { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--ink-500, #5a6488); padding: 2px 0 8px; }
.anp-stop {
  display: inline-flex; align-items: center; gap: 5px; flex: none;
  border: 1px solid #f0d5d5; border-radius: 10px; background: #fff; color: #b91c1c;
  font-weight: 700; font-size: 11.5px; font-family: inherit; padding: 4px 9px; cursor: pointer;
}
.anp-dots { display: flex; gap: 3px; flex: none; }
.anp-dots i { width: 5px; height: 5px; border-radius: 50%; background: #7a5600; display: block; animation: anpwork 1.1s infinite; }
.anp-dots i:nth-child(2) { animation-delay: 0.18s; }
.anp-dots i:nth-child(3) { animation-delay: 0.36s; }
@keyframes anpwork { 0%, 100% { opacity: 0.25; transform: translateY(0); } 50% { opacity: 1; transform: translateY(-2px); } }
@media (prefers-reduced-motion: reduce) { .anp-dots i { animation: none; opacity: 0.7; } }

.anp-err { border-left: 3px solid #f59e0b; background: #fffaf0; border-radius: 0 8px 8px 0; padding: 10px 12px; font-size: 13px; line-height: 1.55; }
.anp-err.is-bad { border-left-color: #ef4444; background: #fff5f5; }

.anp-foot { flex: none; background: #fff; border-top: 1px solid #e8ebf1; padding: 10px 12px 12px; }
.anp-report {
  width: 100%; display: flex; align-items: center; gap: 9px; padding: 8px 11px;
  border: 1px solid #e8dec6; border-radius: 10px; background: #fbf7ed;
  font-weight: 700; font-size: 12.5px; font-family: inherit; color: var(--navy-900, #0c1432); cursor: pointer;
}
.anp-report-n { font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700; color: #7a5600; background: #f0e6cf; border-radius: 6px; padding: 2px 6px; }
.anp-reportbody { border: 1px solid #e8dec6; border-top: none; border-radius: 0 0 10px 10px; background: #fdfbf6; padding: 8px 11px 10px; }
.anp-report-empty { margin: 0; font-size: 12px; line-height: 1.5; color: #6b6350; }
.anp-pin { display: flex; align-items: center; gap: 8px; padding: 5px 0; border-bottom: 1px solid #f2ece0; }
.anp-pin-n { font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700; color: #7a5600; flex: none; }
.anp-pin-t { flex: 1; min-width: 0; font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.anp-pin-ic { border: 0; background: transparent; cursor: pointer; color: #8a8069; font-size: 12px; flex: none; }
.anp-pin-ic:disabled { opacity: 0.3; cursor: default; }
.anp-report-out { display: flex; align-items: center; gap: 7px; margin-top: 9px; flex-wrap: wrap; }

/* ── What the set adds up to ─────────────────────────────────────────────────
   On screen as well as in the file. A warning that only exists in the exported
   document arrives after the decision it was meant to inform. */
.anp-synth { margin-top: 10px; padding-top: 9px; border-top: 1px dashed #e8dec6; }
.anp-synth-sum { margin: 0 0 8px; font-size: 13px; line-height: 1.55; color: var(--navy-900, #0c1432); }
.anp-synth-h { font: 700 9.5px var(--font-mono, monospace); letter-spacing: .14em; text-transform: uppercase; color: #7a5600; margin: 10px 0 4px; }
.anp-synth-list { margin: 0 0 8px; padding-left: 16px; }
.anp-synth-list li { font-size: 12px; line-height: 1.5; color: #3a4260; margin-bottom: 3px; }
.anp-synth-list li i { font-style: normal; color: #8a8069; }
.anp-synth-tension { margin: 0 0 8px; font-size: 12px; line-height: 1.5; color: #7a5600; }
/* Colour by how much it matters, because these are not all the same kind of
   thing: a figure that is not in the evidence is a defect, a mixed date range
   is a caution, and a withheld block is a note on method. */
.anp-synth-note { margin: 0 0 6px; font-size: 12px; line-height: 1.5; padding-left: 8px; border-left: 2px solid #e5e8ee; color: #6b6350; }
.anp-synth-note[data-level="error"] { border-left-color: #b91c1c; color: #b91c1c; font-weight: 600; }
.anp-synth-note[data-level="warn"] { border-left-color: #d19a2a; color: #7a5600; }
.anp-report-note { font-size: 10.5px; color: #6b6350; }

.anp-drift { margin: 9px 0 0; font-size: 12px; line-height: 1.5; color: #7a5600; }

.anp-menu { border: 1px solid #e5e8ee; border-radius: 10px; background: #fff; box-shadow: 0 8px 20px -12px rgba(12, 20, 50, 0.3); margin-top: 10px; overflow: hidden; }
.anp-menu-h {
  font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-500, #5a6488);
  padding: 8px 12px; background: #f7f8fb; border-bottom: 1px solid #eef0f4;
}
.anp-menu-it {
  width: 100%; display: flex; flex-direction: column; gap: 2px; align-items: flex-start;
  padding: 9px 12px; border: 0; border-bottom: 1px solid #f4f5f8; background: transparent;
  cursor: pointer; text-align: left; font: inherit;
}
.anp-menu-it:hover { background: #f7f8fb; }
.anp-menu-it.is-on { background: #fbf7ed; }
.anp-menu-it b { font-size: 13px; }
.anp-menu-it span { font-size: 12px; line-height: 1.4; color: var(--ink-500, #5a6488); }

.anp-composer { border: 1px solid #cfd5e0; border-radius: 14px; background: #fff; margin-top: 10px; }
.anp-scope { display: flex; align-items: center; gap: 6px; padding: 8px 10px; border-bottom: 1px solid #f0f2f6; flex-wrap: wrap; }
.anp-scope-l {
  font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-500, #5a6488); flex: none;
}
.anp-chip {
  display: inline-flex; align-items: center; gap: 5px; padding: 3px 8px; border-radius: 6px;
  background: #f3ecdb; border: 1px solid #e8dec6; color: var(--navy-900, #0c1432);
  font-weight: 600; font-size: 11px; font-family: inherit; white-space: nowrap;
}
.anp-chip button { border: 0; background: transparent; padding: 0; cursor: pointer; color: #8891a6; font-size: 10.5px; }
.anp-chip button:hover { color: var(--ink-900); }
.anp-chip.is-off { background: #fff; border-style: dashed; border-color: #d9dfea; color: var(--ink-500, #5a6488); cursor: pointer; }
.anp-chip.is-all { background: #f4f5f8; border-color: #e5e8ee; color: var(--ink-500, #5a6488); font-weight: 500; }
.anp-composer textarea {
  width: 100%; box-sizing: border-box; border: none; outline: none; resize: vertical;
  font-family: inherit; font-size: 13.5px; line-height: 1.55; color: var(--ink-900, #0a1130);
  padding: 11px 13px 6px; background: transparent; min-height: 52px;
}
.anp-composer-bar { display: flex; align-items: center; gap: 5px; padding: 0 9px 9px; }
.anp-cbtn {
  width: 29px; height: 29px; border-radius: 10px; border: 1px solid #e5e8ee; background: #fff;
  color: #3d4761; display: grid; place-items: center; cursor: pointer; font-weight: 700; font-size: 12px; font-family: inherit; flex: none;
}
.anp-cbtn.is-wide { width: auto; padding: 0 10px; font-size: 12px; }
.anp-cbtn:hover { border-color: #cbd2e2; }
.anp-cbtn.is-on { background: var(--navy-900, #0c1432); border-color: var(--navy-900); color: #fff; }
.anp-count, .anp-send-hint { font-family: var(--font-mono, monospace); font-size: 10.5px; color: var(--ink-500, #5a6488); flex: none; }
.anp-send {
  width: 34px; height: 34px; border-radius: 10px; border: 0; flex: none; cursor: pointer;
  background: var(--navy-900, #0c1432); color: #fff; font-size: 13px;
}
.anp-send:disabled { background: #dfe3ec; color: #97a0b8; cursor: default; }
.anp-oath { margin: 9px 0 0; font-size: 10.5px; line-height: 1.55; color: var(--ink-500, #5a6488); }
.anp-eyebrow {
  font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.18em; text-transform: uppercase; color: #7a5600; margin-bottom: 5px;
}
.anp-lead-line {
  font-family: var(--font-display, Sora, sans-serif); font-weight: 700;
  font-size: 15px; line-height: 1.4; letter-spacing: -0.01em;
  margin: 0; color: var(--ink-900, #0a1130); text-wrap: pretty;
}
.anp-lead-line + .anp-body { margin-top: 8px; }

/* ── The answer, as data ─────────────────────────────────────────────────────
   Tiles, a table and a chart inside a 420px pane. Every figure in all three
   went through the same grounding check as the prose; a block with any figure
   that was not in the evidence never reaches the browser. */
.anp-tiles { display: flex; gap: 8px; margin-top: 12px; }
.anp-tile {
  flex: 1; min-width: 0; position: relative; overflow: hidden;
  background: #f7f8fb; border-radius: 10px; padding: 9px 10px;
}
.anp-tile i { position: absolute; left: 0; top: 0; bottom: 0; width: 3px; }
.anp-tile b {
  font-family: var(--font-display, Sora, sans-serif); font-weight: 800;
  font-size: 19px; line-height: 1; letter-spacing: -0.02em; color: var(--ink-900, #0a1130);
}
.anp-tile em { font-style: normal; font-size: 10.5px; font-weight: 700; margin-left: 5px; }
.anp-tile span {
  display: block; margin-top: 5px; font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.06em; text-transform: uppercase;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.anp-tbl-wrap { margin-top: 12px; border: 1px solid #e2e6ee; border-radius: 10px; overflow: hidden; background: #fcfcfd; }
.anp-tbl-t {
  font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 700;
  letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-500, #5a6488);
  padding: 8px 10px 0;
}
.anp-tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.anp-tbl th {
  text-align: left; font-family: var(--font-mono, monospace); font-weight: 600; font-size: 10.5px;
  letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-500, #5a6488);
  padding: 8px 10px; background: #f7f8fb; border-bottom: 1px solid #eef0f4;
}
.anp-tbl td { padding: 7px 10px; border-bottom: 1px solid #f4f5f8; }
.anp-tbl th.anp-num, .anp-tbl td.anp-num { text-align: right; font-variant-numeric: tabular-nums; }
/* Analytics is nothing but numbers, so every figure in it gets tabular
   digits whether or not its cell was marked — a chart label that reflows
   as the value ticks is the same bug in a smaller box. */
.anp-tbl-bar em, .anp-chart, .anp-kpi-n { font-variant-numeric: tabular-nums; }
.anp-tbl tr:last-child td { border-bottom: 0; }
.anp-tbl-k { font-weight: 600; color: var(--ink-900, #0a1130); }
.anp-tbl-bar { display: flex; align-items: center; gap: 7px; }
.anp-tbl-bar i { flex: 1; min-width: 30px; height: 5px; border-radius: 999px; background: #eef0f4; overflow: hidden; }
.anp-tbl-bar i b { display: block; height: 100%; border-radius: 999px; background: var(--navy-700, #1c2a5e); }
.anp-tbl-bar em { font-style: normal; font-family: var(--font-mono, monospace); color: var(--ink-800, #25304a); }

.anp-chart { margin-top: 12px; border: 1px solid #e2e6ee; border-radius: 10px; padding: 10px 12px 8px; background: #fcfcfd; }
.anp-chart-h {
  display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 7px;
  font-family: var(--font-mono, monospace); font-size: 10.5px; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--ink-500, #5a6488);
}
.anp-chart-h span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.anp-chart-h b { font-size: 12px; flex: none; }

/* Cream rule, not a red box: "this would be wrong if…" is a condition on the
   answer, not a fault in it. */
/* ── ONE annotation shape ───────────────────────────────────────────────────
   An answer stacked four different block treatments in a row: a bordered
   chart, a bordered table, a beige left rule, an orange mono line with no
   treatment at all, and a grey left rule that looked like the beige one and
   meant something else. Five shapes for two ideas.

   Two shapes now, and they are legible on sight:
     a BORDERED CARD is data — a chart, a table, something measured;
     a LEFT RULE is commentary about that data, and the rule's COLOUR is the
     only thing that varies, because severity is the only thing that differs.
   Neutral for a claim, amber for a caveat, red for a figure that was refused.
   Same padding, same size, same rhythm, so a reader learns it once. */
.anp-caveat {
  margin-top: 12px; padding: 8px 0 8px 11px; border-left: 2px solid #d9a441;
  font-size: 12px; line-height: 1.55; color: #5a5443;
}
/* A figure the answer cited that was NOT in the evidence. This is the panel
   catching itself, so it is the loudest annotation, not the quietest — it was
   an orange mono line floating with no shape at all. */
.anp-dropped {
  margin-top: 12px; padding: 8px 0 8px 11px; border-left: 2px solid #ef4444;
  font-size: 12px; line-height: 1.55; color: #9f1239;
  font-family: var(--font-mono, monospace);
}

/* ── Reading the register ────────────────────────────────────────────────────
   The columns state their own units. "Present" and "Rate" against an unstated
   span was the main reason this table was hard to read: 62% of the term and 62%
   of last week look identical and are different findings. */
.att-table th { vertical-align: top; }
.att-th-sub { display: block; font-family: var(--font-mono, monospace); font-size: 10.5px; font-weight: 400; letter-spacing: 0; text-transform: none; color: var(--ink-500); margin-top: 2px; }
/* A row that needs attention is visible while scanning, not only once read. */
.att-table tbody tr[data-risk="1"] td:first-child { box-shadow: inset 3px 0 0 var(--coral, #d0663c); }
.att-chip.is-empty { opacity: .45; cursor: not-allowed; }
.att-chip.is-empty:hover { border-color: var(--line, #e6e2d6); }

/* ── The shape of the absence ─────────────────────────────────────────────────
   A rate cannot tell a child who comes three days a week from one who came
   every day and then stopped: both land on 60% and need opposite responses. */
.att-pat { display: inline-flex; gap: 2px; align-items: center; }
.att-pat i { width: 6px; height: 14px; border-radius: 6px; background: #e3e6ee; display: block; }
.att-pat i[data-d="in"]   { background: var(--lime-ink, #6e9c1d); }
.att-pat i[data-d="late"] { background: var(--gold-500, #f5b026); }
.att-pat i[data-d="half"] { background: var(--gold-500, #f5b026); opacity: .5; }
.att-pat i[data-d="out"]  { background: #e3e6ee; }
.att-stopped { font-size: 10.5px; color: var(--coral, #d0663c); font-weight: 600; margin-top: 3px; }

/* =====================================================================
   NGG member dashboard — portal layout system.
   Brings the Afrovanguard member portal's chrome (a sticky sidebar rail,
   a top-bar strip, a KPI row and a card grid) to the NGG dashboard, but
   rendered entirely in NGG's own navy/gold/cream palette and typefaces —
   no Public Sans, no portal tokens. Lives inside the global TopNav/Footer,
   so the rail is sticky rather than a full-height fixed shell.
   ===================================================================== */
.ngg-dash { background: var(--cream-50); }
.ngg-dash-wrap { display: flex; align-items: flex-start; gap: 28px; }

/* ---- sidebar rail ---- */
.ngg-side { width: 244px; flex: none; position: sticky; top: 84px; align-self: flex-start; }
.ngg-side-toggle { display: none; }
.ngg-side-inner {
  background: #fff; border: 1px solid rgba(12,20,50,0.07); border-radius: 14px;
  padding: 14px 12px; display: flex; flex-direction: column; gap: 14px;
  box-shadow: 0 1px 2px rgba(12,20,50,0.04);
}
.ngg-side-brand {
  display: flex; align-items: center; gap: 11px; width: 100%; text-align: left;
  padding: 4px 6px 13px; border: 0; background: none; cursor: pointer;
  border-bottom: 1px solid rgba(12,20,50,0.06);
}
.ngg-side-avatar-img { width: 40px; height: 40px; border-radius: 50%; object-fit: cover; border: 2px solid var(--gold-500); flex: none; }
.ngg-side-brand-text { line-height: 1.2; min-width: 0; }
.ngg-side-brand-text b { display: block; font-family: var(--font-display); font-size: 15px; color: var(--ink-900); letter-spacing: -0.01em; }
.ngg-side-brand-text .mono { display: block; font-size: 10.5px; color: var(--ink-500); letter-spacing: 0.12em; }
.ngg-nav { display: flex; flex-direction: column; gap: 14px; }
.ngg-nav-group { display: flex; flex-direction: column; gap: 1px; }
.ngg-nav-title { font-family: var(--font-mono); font-size: 10.5px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--ink-400); padding: 0 10px 6px; font-weight: 600; }
.ngg-nav-link {
  display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px;
  font-size: 13.5px; font-weight: 600; color: var(--ink-700); text-decoration: none; cursor: pointer;
  transition: background .14s ease, color .14s ease;
}
.ngg-nav-link:hover { background: var(--cream-100); color: var(--ink-900); }
.ngg-nav-link.is-active { background: rgba(245,176,38,0.14); color: var(--ink-900); }
.ngg-nav-dot { width: 6px; height: 6px; border-radius: 6px; background: rgba(12,20,50,0.18); flex: none; }
.ngg-nav-link.is-active .ngg-nav-dot { background: var(--gold-500); }
.ngg-nav-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ngg-nav-badge { font-family: var(--font-mono); font-size: 10.5px; font-weight: 700; color: var(--ink-500); background: var(--cream-100); padding: 1px 7px; border-radius: 999px; }
.ngg-nav-link.is-active .ngg-nav-badge { color: var(--gold-700); background: rgba(245,176,38,0.20); }
.ngg-side-user { display: flex; gap: 8px; padding-top: 12px; border-top: 1px solid rgba(12,20,50,0.06); }
.ngg-side-user .btn { flex: 1; justify-content: center; }

/* ---- main column ---- */
.ngg-main { flex: 1; min-width: 0; }
.ngg-top { display: flex; align-items: center; gap: 12px; padding: 0 2px 18px; }
.ngg-crumb { display: flex; align-items: center; gap: 9px; font-size: 13px; color: var(--ink-500); }
.ngg-crumb-sep { color: rgba(12,20,50,0.25); }
.ngg-crumb-here { color: var(--ink-900); font-weight: 700; }
.ngg-top-actions { margin-left: auto; display: flex; gap: 8px; }

.ngg-head { margin-bottom: 20px; }
.ngg-head-eyebrow { font-size: 10.5px; letter-spacing: 0.2em; color: var(--ink-400); margin-bottom: 6px; }
.ngg-head-name { font-family: var(--font-display); font-size: clamp(30px, 5vw, 44px); font-weight: 700; letter-spacing: -0.02em; line-height: 1; margin: 0 0 8px; color: var(--ink-900); }
.ngg-head-sub { color: var(--ink-500); font-size: 15px; max-width: 62ch; margin: 0; }

/* ---- KPI row ---- */
.ngg-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 24px; }
.ngg-kpi { background: #fff; border: 1px solid rgba(12,20,50,0.06); border-radius: 14px; padding: 16px; box-shadow: 0 1px 2px rgba(12,20,50,0.04); }
.ngg-kpi-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; min-height: 22px; }
.ngg-kpi-l { font-family: var(--font-mono); font-size: 10.5px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ink-500); font-weight: 600; }
.ngg-kpi-n { font-family: var(--font-display); font-size: 30px; font-weight: 700; letter-spacing: -0.02em; line-height: 1.1; margin-top: 12px; color: var(--ink-900); }
.ngg-kpi-n.is-clear { color: #1c7a44; font-size: 22px; }
.ngg-kpi-u { font-size: 15px; color: var(--ink-500); font-weight: 500; margin-left: 2px; }
.ngg-kpi-s { font-size: 12px; color: var(--ink-400); margin-top: 6px; }

/* ---- the existing card grid, now inside the shell ---- */
.ngg-main .dash-grid { gap: 20px; }

.ngg-anchor { display: block; scroll-margin-top: 96px; }
.ngg-anchor > .dash-card { margin: 0; }

/* ---- responsive: rail collapses into a Sections menu ---- */
@media (max-width: 980px) {
  .ngg-dash-wrap { display: block; }
  .ngg-side { position: static; width: auto; margin-bottom: 16px; }
  .ngg-side-toggle { display: inline-flex; }
  .ngg-side-inner { display: none; margin-top: 12px; }
  .ngg-side.is-open .ngg-side-inner { display: flex; }
  .ngg-top-actions { display: none; }
}
@media (max-width: 720px) {
  .ngg-kpis { grid-template-columns: 1fr 1fr; }
}

/* =====================================================================
   Admin health banner — surfaces storage faults (a DEGRADED local photo
   store, or a Cloudinary that is refusing / exhausted / unreachable) that
   otherwise only show up as a blank photo frame. Full-width under the
   topbar; dismissible until the situation itself changes.
   ===================================================================== */
.admin-health-banner {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 13px clamp(16px, 3vw, 30px);
  background: var(--navy-900, #0c1432);
  color: #fff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: inset 4px 0 0 var(--gold-500, #f5b026);
}
.admin-health-banner .ahb-ico {
  flex: none; font-size: 19px; line-height: 1.4; color: var(--gold-400, #ffc34d);
}
.admin-health-banner .ahb-text { flex: 1; min-width: 0; }
.admin-health-banner .ahb-title {
  display: block; font-family: var(--font-display, inherit); font-size: 15px;
  font-weight: 700; letter-spacing: -0.01em; margin-bottom: 4px;
}
.admin-health-banner .ahb-list { margin: 0; padding-left: 18px; }
.admin-health-banner .ahb-list li { font-size: 13px; line-height: 1.5; color: rgba(255, 255, 255, 0.82); margin: 3px 0; }
.admin-health-banner .ahb-list b { color: #fff; }
.admin-health-banner .ahb-action { color: var(--gold-300, #ffd680); }
.admin-health-banner .ahb-actions { display: flex; gap: 8px; flex: none; align-items: center; }
@media (max-width: 720px) {
  .admin-health-banner { flex-wrap: wrap; }
  .admin-health-banner .ahb-actions { width: 100%; }
}

/* =====================================================================
   NGG ID Designer — Canva-style refresh.
   A presentation/UX layer over the existing designer DOM (page-designer.jsx):
   a grouped top toolbar, a real workspace backdrop for the canvas, cleaner
   rails, and — the point of this pass — a roster panel built to stay scannable
   while a coordinator processes hundreds of IDs at once. Pure additive CSS on
   the existing classes; the Fabric engine, refs, state and handlers are
   untouched. Keeps NGG's navy/gold studio identity rather than importing
   Canva's greys. Source-order-later, so these win over the base .dsn-* rules.
   ===================================================================== */
:root { --dsn-panel:rgba(255,255,255,0.055); --dsn-line:rgba(255,255,255,0.14);
        --dsn-line-2:rgba(255,255,255,0.22); --dsn-gold:#f5b026; --dsn-ink:#eef2fb;
        --dsn-muted:rgba(230,238,255,0.6); --dsn-ok:#6fdc9d; --dsn-warn:#ffce54; --dsn-bad:#ff8f8f; }

/* ---- top toolbar: one grounded strip, sticky, with the file/export row ---- */
.dsn-bar {
  position: sticky; top: 0; z-index: 20; margin: -4px -4px 16px; padding: 12px 16px;
  background: linear-gradient(180deg, rgba(18,26,48,0.96), rgba(18,26,48,0.86));
  backdrop-filter: blur(8px); border: 1px solid var(--dsn-line);
  border-radius: 14px; box-shadow: 0 10px 30px -18px rgba(0,0,0,0.7);
}
.dsn-bar .btn-primary { box-shadow: 0 1px 0 rgba(0,0,0,0.15); font-weight: 700; }

/* ---- the bar's four zones ------------------------------------------------
   DESIGN | PROOF | SAVE | OUTPUT. A hairline between them and a caption above
   each, so the row reads as four things rather than nine. The caption is the
   cheap part and the one that does the work: a group you can name is a group
   you can aim at, and the alternative was reading every control to find one.

   The divider is a left border rather than a separate element — an empty
   element between groups is one more thing for a screen reader to step over,
   and these are already role="group" with labels. */
.dsn-zone {
  /* nowrap: a zone breaks as a UNIT. Wrapping inside one put SIDE on a second
     line under NAME while the bar still had room, which is the wrong seam —
     the whole point of the zones is that they are the units. The BAR wraps
     between them when the row runs out. */
  display: flex; flex-wrap: nowrap; align-items: flex-end; gap: 8px;
  padding-left: 14px; margin-left: 2px;
  border-left: 1px solid var(--dsn-line);
  position: relative;
}
/* The first zone opens the row, so it carries no divider. */
.dsn-zone:first-of-type { border-left: 0; padding-left: 0; margin-left: 0; }
/* OUTPUT is LAST, not pushed. `margin-left: auto` absorbed the row's free
   space and tipped the zone onto a second line at 1440 — buying a visual
   separation the caption and the divider already provide, at the cost of a
   whole extra row and a gap beside Publish. Order is enough. */
.dsn-zone-end { margin-left: 0; }
.dsn-zone-cap {
  align-self: center;
  font: 700 9.5px var(--font-mono, monospace); letter-spacing: .18em;
  /* 0.42 alpha measured 3.67:1 on the bar — under the 4.5:1 this codebase
     requires of caption text, and caught by designer.test.js rather than by
     me. A caption nobody can read groups nothing. */
  text-transform: uppercase; color: rgba(230, 238, 255, 0.62);
  white-space: nowrap;
}
/* The name field is the document's identity — give it room, but let it give
   that room back before the row wraps. */
/* The document's name. It is the one field here holding free text, and at a
   fixed width it clipped its own value ("New Summer School car") while three
   selects beside it sat half empty — so it grows into the bar's spare room
   and gives that room back before the row wraps. */
/* Basis, not growth. `flex: 1 1` let it eat the bar's spare room and pushed
   SIDE onto a second line and OUTPUT onto a third — a one-row bar became
   three, which costs more than the clipping it fixed. 240px holds a real
   design name; it shrinks before the row wraps and never grows past it. */
/* 180px, measured: at 200 the four zones came to about nine pixels more than
   the bar's inner width at 1440 and OUTPUT dropped to a second row. The field
   still shows a real design name and shrinks before the row wraps. */
.dsn-bar-name { flex: 0 1 180px; min-width: 0; }
.dsn-bar-name input { width: 100%; min-width: 0; }
.dsn-zone .dsn-prop { margin-bottom: 0; }

/* Narrow: the dividers and the auto-margin stop helping once the zones wrap
   onto their own lines — a vertical hairline against the line above reads as
   a stray mark, and pushing OUTPUT right leaves a gap rather than an edge. */
@media (max-width: 900px) {
  .dsn-zone { border-left: 0; padding-left: 0; margin-left: 0; }
  .dsn-zone-end { margin-left: 0; }
}

/* ---- tool row: a floating Canva-style pill of icon buttons ---- */
.dsn-tools { border-radius: 10px; padding: 7px 10px; }
.dsn-tool-grp { border-right: 1px solid var(--dsn-line); }
.dsn-tool-grp:last-of-type { border-right: 0; }
.dsn-tool {
  width: 34px; height: 32px; display: inline-flex; align-items: center; justify-content: center;
  border-radius: 10px; border: 1px solid transparent; background: transparent; color: var(--dsn-ink);
  font-size: 15px; cursor: pointer; transition: background .12s, border-color .12s, transform .06s;
}
.dsn-tool:hover:not(:disabled) { background: rgba(255,255,255,0.1); border-color: var(--dsn-line-2); }
.dsn-tool:active:not(:disabled) { transform: translateY(1px); }
.dsn-tool:disabled { opacity: 0.32; }
.dsn-tool.is-on { background: rgba(245,176,38,0.18); border-color: var(--dsn-gold); color: #ffe1a3; }

/* ---- editor workspace: canvas floats on a real backdrop, not a flat panel ---- */
.dsn-grid { grid-template-columns: 232px minmax(0,1fr) 300px; gap: 16px; }

/* ---- PRINT MODE: the canvas keeps its place and becomes the proof ----------
   Design mode leaves .dsn-work alone, so the workspace is the normal
   layers | canvas | properties grid. Print mode turns the wrapper into two
   columns — canvas first, records beside it — and steps the editing rails
   aside, because nothing here edits the design.

   Why the canvas gets the smaller column: a card is 54mm wide and the record
   list is a six-column table. Giving the table the free space is what lets it
   keep its columns readable without a horizontal scroll at 1440.

   align-items: start so a long roster does not stretch the canvas panel, and
   the canvas panel is sticky so scrolling the list keeps the proof in sight —
   which is the whole point, and what a scrollIntoView was standing in for. */
.dsn-work.is-printing {
  display: grid; grid-template-columns: minmax(0, 500px) minmax(0, 1fr);
  gap: 16px; align-items: start;
}
.dsn-work.is-printing .dsn-grid { order: 1; grid-template-columns: minmax(0, 1fr); }
.dsn-work.is-printing .dsn-merge { order: 2; margin: 0; }
/* The editing rails, not the canvas. Both use .dsn-rail; the stage does not. */
.dsn-work.is-printing .dsn-rail { display: none; }
.dsn-work.is-printing .dsn-grid > .dsn-stage { position: sticky; top: 12px; }
/* One column below the workspace breakpoint, canvas first — the same place
   .dsn-grid already collapses, so the two never disagree. */
@media (max-width: 1080px) {
  .dsn-work.is-printing { grid-template-columns: minmax(0, 1fr); }
  .dsn-work.is-printing .dsn-grid > .dsn-stage { position: static; }
}
.dsn-rail {
  background: var(--dsn-panel); border: 1px solid var(--dsn-line); border-radius: 14px;
  max-height: min(72vh, 760px);
}
.dsn-rail-head {
  position: sticky; top: 0; z-index: 1; margin: -12px -12px 8px; padding: 12px 12px 8px;
  background: linear-gradient(180deg, rgba(20,28,50,0.98), rgba(20,28,50,0.7));
  border-bottom: 1px solid var(--dsn-line);
}
.dsn-stage {
  background:
    radial-gradient(1200px 500px at 50% -10%, rgba(245,176,38,0.06), transparent 60%),
    repeating-linear-gradient(45deg, rgba(255,255,255,0.02) 0 10px, transparent 10px 20px),
    #10182b;
  border: 1px solid var(--dsn-line); border-radius: 14px; padding: 28px 18px;
  min-height: 480px; justify-content: center;
}
.dsn-canvas-host { box-shadow: 0 24px 60px -20px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.05); }
.dsn-stage-note {
  padding: 4px 12px; border-radius: 999px; background: rgba(0,0,0,0.3);
  border: 1px solid var(--dsn-line); backdrop-filter: blur(4px);
}

/* ---- BATCH: the roster, built to scan at scale ------------------------------
   Filters read as a toolbar; the picks bar and column header stick while the
   list scrolls; rows align into columns and carry a coloured status so a
   coordinator can sweep hundreds and spot the ones that need a photo. */
.dsn-merge {
  border: 1px solid var(--dsn-line-2); border-radius: 14px; padding: 16px 18px 14px;
  background: linear-gradient(180deg, rgba(245,176,38,0.05), rgba(255,255,255,0.03));
  box-shadow: 0 16px 40px -26px rgba(0,0,0,0.8);
  /* Named so the run bars inside can ask THIS panel how wide it is. See the
     @container rule on .dsn-merge-picks. */
  container: dsnrun / inline-size;
}
.dsn-merge-head b { font-size: 15px; letter-spacing: -0.01em; }
.dsn-merge-filters {
  background: rgba(0,0,0,0.18); border: 1px solid var(--dsn-line); border-radius: 10px;
  padding: 12px; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
}
/* Sticky, and OPAQUE. The translucency was the bug, not the stickiness: at
   0.85 alpha the rows underneath showed through the toolbar. */
.dsn-merge-picks {
  position: sticky; top: 0; z-index: 2; padding: 8px 2px; margin: 12px 0 0;
  background: #101a2b;
  border-bottom: 1px solid var(--dsn-line);
}
/* Two rows before one row starts wrapping into a column.
   As one flex line at every width, the chips broke onto two lines below about
   1000px and "1,200 in the run — 600 is the most one run can render" collapsed
   into a four-line column — the single most consequential number on the panel,
   set as a paragraph one word wide. It does the same thing at 200% zoom on a
   full-width window, which is where WCAG 1.4.4 cares.

   Grid rather than more flex-wrap: wrapping decides where things break by
   running out of room, and what breaks first is whatever happens to be last.

   A CONTAINER query, not a viewport one. This was `@media (max-width: 1040px)`,
   which is a stand-in for "the panel is narrow" and stops being true the moment
   the panel stops being the width of the window — print mode puts it in a
   column beside the canvas, so at 1440 the window said roomy and the panel had
   890px, and the chips squeezed text inside the buttons instead of reflowing.
   Asking the panel about its own width is the actual question. */
@container dsnrun (max-width: 1000px) {
  .dsn-merge-picks {
    display: grid; gap: 8px 6px; align-items: center;
    grid-template-columns: auto auto auto 1fr;
    grid-template-areas: "tick all clear run" "chips chips chips view";
  }
  .dsn-merge-all { grid-area: tick; }
  .dsn-merge-picks > .btn:nth-of-type(1) { grid-area: all; }
  .dsn-merge-picks > .btn:nth-of-type(2) { grid-area: clear; }
  .dsn-merge-picks > .dsn-chips:not(.dsn-view) { grid-area: chips; }
  .dsn-merge-picks > .dsn-merge-note { grid-area: run; text-align: right; }
  .dsn-merge-picks > .dsn-view { grid-area: view; justify-self: end; }
}
.dsn-merge-picks .dsn-merge-note { text-align: right; }
/* Taller viewport so more of a big roster is visible at once. */
.dsn-merge-list { max-height: min(56vh, 560px); }
/* `.dsn-merge-row` was the card in the old wrapping grid. The picker is a
   table now, so what is left here is the row STATE and the checkbox, applied
   to <tr> and <td> instead. */
/* 20px, not 16. Sixteen cleared WCAG 2.5.8 only through the spacing exception
   — legal because the rows happen to be 34px apart, which is an argument that
   stops being true the moment somebody tightens a row. Twenty is closer to the
   24px floor on its own merits and still nowhere near the 44px a thumb wants,
   which is fine: this is a desktop tool. */
.dsn-tbl tbody input[type="checkbox"],
.dsn-merge-all input[type="checkbox"] { width: 20px; height: 20px; accent-color: var(--dsn-gold); }
.dsn-tbl .dsn-td-who { color: var(--dsn-ink); font-weight: 600; font-size: 13px; }
.dsn-tbl thead th { background: #141c31; }
/* Two badges on one row (no photo AND no card) sit side by side rather than
   stacking the cell taller than every other row in the table. */
.dsn-tbl td .dsn-merge-flag + .dsn-merge-flag { margin-left: 5px; }
.dsn-merge-flag { border-radius: 999px; padding: 3px 9px; font-size: 10.5px; }
.dsn-merge-flag--ok    { color: var(--dsn-ok);   border-color: rgba(111,220,157,0.5);  background: rgba(111,220,157,0.12); }
.dsn-merge-flag--photo { color: var(--dsn-warn); border-color: rgba(255,206,84,0.5);   background: rgba(255,206,84,0.12); }
.dsn-merge-flag--card  { color: var(--dsn-bad);  border-color: rgba(255,143,143,0.5);  background: rgba(255,143,143,0.14); }
/* OPAQUE. This was a gradient topping out at 0.8 alpha, and a sticky bar with
   0.8 alpha has the rows scrolling behind it showing THROUGH — which reads as
   a rendering fault, not as a bar. Not an edge case either: the panel is
   taller than a 1000px viewport with any real roster, so the last two rows sat
   behind it every time. A gradient buys nothing over content it is meant to
   cover. */
.dsn-merge-run {
  position: sticky; bottom: 0; margin: 12px -18px -14px; padding: 12px 18px;
  background: #101a2b;
  border-top: 1px solid var(--dsn-line-2); border-radius: 0 0 16px 16px;
}

/* ── Programme journal: attachments + backdating ──────────────────────────
   The lead photo carries the card in a feed; the rest are a strip, so a
   twelve-photo entry can't push the prose off the screen. */
.cm-pj-shots { display: grid; gap: 6px; margin: 10px 0 12px;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 96px), 1fr)); align-items: start; }
.cm-pj-shots.is-compact { grid-template-columns: 1fr; }
.cm-pj-shot { margin: 0; min-width: 0; }
.cm-pj-shot img, .cm-pj-shot video { display: block; width: 100%; height: 96px; object-fit: cover;
  border-radius: 10px; background: #eee; }
/* The lead spans the row so it reads as the entry's picture, not one of five. */
.cm-pj-shot.is-lead { grid-column: 1 / -1; }
.cm-pj-shot.is-lead img, .cm-pj-shot.is-lead video { height: auto; max-height: 340px; object-fit: cover; }
.cm-pj-shot figcaption { font-size: 12px; color: var(--ink-500, #5b6478); margin-top: 4px; line-height: 1.35; }
.cm-pj-more { align-self: center; font-size: 12px; font-weight: 700; color: var(--ink-500, #5b6478); }
.cm-pj-late { color: var(--ink-500, #5b6478); }

/* Editor: one block per attachment, with its caption and alt text beside it,
   because alt text asked for later is alt text never written. */
.cm-pj-media { display: grid; gap: 10px; margin: 8px 0 10px; }
.cm-pj-mitem { position: relative; display: grid; gap: 6px;
  grid-template-columns: 96px minmax(0, 1fr); align-items: start;
  border: 1px solid rgba(0,0,0,.1); border-radius: 10px; padding: 8px 34px 8px 8px; background: #fff; }
.cm-pj-mitem img, .cm-pj-mitem video { grid-row: 1 / span 2; width: 96px; height: 96px;
  object-fit: cover; border-radius: 10px; background: #eee; }
.cm-pj-mx { position: absolute; top: 6px; right: 6px; width: 26px; height: 26px; min-height: 26px;
  border: 1px solid rgba(0,0,0,.12); border-radius: 50%; background: #fff; cursor: pointer;
  font-size: 13px; line-height: 1; color: var(--ink-700, #333); display: grid; place-items: center; }
.cm-pj-mx:hover { border-color: var(--coral, #e4032b); color: var(--coral, #e4032b); }
@media (max-width: 520px) {
  .cm-pj-mitem { grid-template-columns: 1fr; }
  .cm-pj-mitem img, .cm-pj-mitem video { grid-row: auto; width: 100%; height: 140px; }
}

/* Community: the screening-mode control. Three named positions rather than a
   switch, so the middle option is discoverable rather than hidden behind
   "advanced". */
.admin-modmode { margin: 0 0 16px; }
.admin-modmode-row { display: grid; gap: 8px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr)); }
.admin-modmode-opt { display: grid; gap: 3px; text-align: left; padding: 12px 14px; min-height: 44px;
  border: 1px solid rgba(12,20,50,.14); border-radius: 10px; background: #fff; font: inherit; cursor: pointer; }
.admin-modmode-opt:hover:not(:disabled) { border-color: var(--gold-500, #f5b026); }
.admin-modmode-opt.is-on { border-color: var(--navy-900, #16223e); box-shadow: inset 0 0 0 1px var(--navy-900, #16223e); }
.admin-modmode-opt b { font-size: 13.5px; color: var(--ink-900, #16223e); }
.admin-modmode-opt span { font-size: 13px; color: var(--ink-500, #5b6478); line-height: 1.4; }

/* ── Markdown blocks ──────────────────────────────────────────────────────
   Headings start at h4 because these render inside a feed card that already
   sits under the page's own headings. */
.md > *:first-child { margin-top: 0; }
.md > *:last-child { margin-bottom: 0; }
.md-p { margin: 0 0 8px; line-height: 1.5; }
.md-h { margin: 12px 0 6px; line-height: 1.3; font-weight: 800; color: var(--ink-900, #16223e); }
.md-h1 { font-size: 1.15em; } .md-h2 { font-size: 1.06em; } .md-h3 { font-size: 1em; }
.md-list { margin: 0 0 8px; padding-left: 22px; }
.md-list li { margin: 2px 0; line-height: 1.5; }
.md-quote { margin: 8px 0; padding: 2px 0 2px 12px; border-left: 3px solid rgba(12,20,50,.18); color: var(--ink-700, #3b4459); }
.md-quote p { margin: 0 0 4px; }
.md-pre { margin: 8px 0; padding: 10px 12px; border-radius: 10px; overflow-x: auto;
  background: #16223e; color: #eef2fb; font-size: 13px; line-height: 1.5; }
.md-pre code { font-family: var(--font-mono, ui-monospace, monospace); white-space: pre; }
.md-hr { border: 0; border-top: 1px solid rgba(12,20,50,.14); margin: 12px 0; }
.md a { color: var(--link, #1b4fd8); text-decoration: underline; overflow-wrap: anywhere; }

/* Composer preview */
.cm-fmt-prev.is-on { background: var(--navy-900, #16223e); color: #fff; }
.cm-preview { margin: 8px 0; padding: 10px 12px; border: 1px dashed rgba(12,20,50,.22); border-radius: 10px; background: rgba(12,20,50,.02); }
.cm-preview-lab { font: 700 10px var(--font-mono, monospace); letter-spacing: .14em; text-transform: uppercase;
  color: var(--ink-500, #5b6478); margin-bottom: 6px; }
.cm-preview-empty { margin: 0; font-size: 13px; color: var(--ink-500, #5b6478); }

/* ── Video player ── */
.vp { position: relative; margin: 0; background: #000; border-radius: 10px; overflow: hidden; }
.vp:focus-visible { outline: 3px solid #1b6ef3; outline-offset: 2px; }
.vp video { display: block; width: 100%; max-height: 70vh; background: #000; }
.vp-big { position: absolute; inset: 0; margin: auto; width: 66px; height: 66px; border-radius: 50%;
  border: 0; background: rgba(0,0,0,.55); color: #fff; font-size: 22px; cursor: pointer; }
.vp-bar { display: flex; align-items: center; gap: 8px; padding: 8px 10px; background: #10131c; color: #eef2fb; flex-wrap: wrap; }
.vp-btn { min-width: 36px; min-height: 36px; border: 0; border-radius: 10px; background: transparent;
  color: #eef2fb; font: inherit; font-size: 13.5px; cursor: pointer; }
.vp-btn:hover { background: rgba(255,255,255,.12); }
.vp-seek { flex: 1 1 120px; min-width: 90px; accent-color: var(--gold-500, #f5b026); }
.vp-vol { width: 74px; accent-color: var(--gold-500, #f5b026); }
.vp-time { font-size: 12px; font-variant-numeric: tabular-nums; opacity: .85; }
.vp-rate { position: relative; }
.vp-rate-menu { position: absolute; bottom: 100%; right: 0; background: #10131c; border: 1px solid rgba(255,255,255,.16);
  border-radius: 10px; padding: 4px; display: grid; gap: 2px; z-index: 5; }
.vp-rate-menu button { min-width: 62px; min-height: 34px; border: 0; background: transparent; color: #eef2fb;
  font: inherit; font-size: 13px; border-radius: 6px; cursor: pointer; }
.vp-rate-menu button[aria-checked="true"] { background: var(--gold-500, #f5b026); color: #10131c; font-weight: 700; }
.vp-cap { padding: 6px 10px; font-size: 13px; color: #cfd6e6; background: #10131c; }
@media (max-width: 420px) { .vp-vol { display: none; } }

/* ── Document viewer ──────────────────────────────────────────────────────
   Closed by default (a card), opening into a page-image reader. Sizes follow
   the community's touch rules: every control is at least 44px, the open-card
   row is 62px, and nothing here relies on hover to be discoverable. */
.pdfv { border: 0; background: none; }

/* Closed: the document offered, not yet fetched. Borderless — it sits INSIDE
   a message card, and a bordered box in a bordered box is the frame-in-frame
   the rest of this sheet spent its time removing. */
.pdfv-closed { border: 0; border-radius: 0; background: none; }
.pdfv-open { display: flex; align-items: center; gap: 12px; width: 100%; min-height: 62px;
  padding: 11px 14px; border: 0; border-radius: var(--c-r-btn, 14px);
  background: var(--c-surface, #fbf7ed); text-align: left; cursor: pointer; }
.pdfv-open:hover { background: var(--c-neutral-chip, #f2eee0); }
.pdfv-open:focus-visible { outline: 2px solid var(--blue-600, #1f4bc4); outline-offset: 2px; }
.pdfv-open-ic { flex: 0 0 auto; font-size: 22px; line-height: 1; }
.pdfv-open-body { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.pdfv-open-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: 15px; font-weight: 700; color: var(--ink-900, #0a1130); }
.pdfv-open-meta { font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 12px;
  letter-spacing: .04em; color: var(--ink-500, #5f6785); }
.pdfv-open-cta { flex: 0 0 auto; display: inline-flex; align-items: center; min-height: 36px;
  padding: 0 14px; border-radius: var(--c-r-pill, 999px); background: var(--c-ink-deep, #0c1432);
  color: #fff; font-size: 13px; font-weight: 700; }

/* ── Open: the full-screen reader ────────────────────────────────────────
   Above everything including the tab bar. A document is read, not glanced at,
   and a page rendered into a short well between two other people's messages
   is neither. */
.pdfv-full { position: fixed; inset: 0; z-index: 60; display: flex; flex-direction: column;
  background: var(--c-ink-deep, #0c1432); color: #fff; }
.pdfv-full:focus { outline: none; }

.pdfv-bar { flex: none; display: flex; align-items: center; gap: 4px;
  padding: max(6px, env(safe-area-inset-top)) 6px 6px;
  border-bottom: 1px solid rgba(255,255,255,.09); }
.pdfv-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: var(--c-font-display, Sora, sans-serif); font-size: 15px; font-weight: 700;
  color: #fff; padding: 0 4px; }
.pdfv-x, .pdfv-act { width: var(--c-tap, 44px); height: var(--c-tap, 44px); flex: none;
  display: grid; place-items: center; border: 0; border-radius: var(--c-r-sm, 12px);
  background: none; color: rgba(255,255,255,.86); cursor: pointer; }
.pdfv-x:hover, .pdfv-act:hover { background: rgba(255,255,255,.1); color: #fff; }
.pdfv-x:focus-visible, .pdfv-act:focus-visible { outline: 2px solid var(--c-accent, #f5b026); outline-offset: -3px; }

/* The page. Scrolls both ways, because a zoomed page is wider than the phone
   holding it and clipping it would hide the text. */
.pdfv-page { flex: 1; min-height: 0; overflow: auto; -webkit-overflow-scrolling: touch;
  display: flex; justify-content: center; align-items: flex-start;
  padding: 14px 10px; background: #11182f; }
.pdfv-canvas { display: block; max-width: none; border-radius: 6px; background: #fff;
  box-shadow: 0 10px 30px -12px rgba(0,0,0,.6); }
.pdfv-pageerr { padding: 40px 20px; text-align: center; font-size: 13.5px; color: rgba(255,255,255,.7); }

.pdfv-foot { flex: none; display: flex; align-items: center; justify-content: space-between;
  gap: 14px; padding: 8px 12px calc(8px + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(255,255,255,.09); }
.pdfv-zoom, .pdfv-pager { display: inline-flex; align-items: center; gap: 6px; }
.pdfv-round { width: var(--c-tap, 44px); height: var(--c-tap, 44px); display: inline-flex;
  align-items: center; justify-content: center; border: 0; border-radius: var(--c-r-pill, 999px);
  background: rgba(255,255,255,.09); color: #fff; font-size: 19px; line-height: 1; cursor: pointer; }
.pdfv-round:disabled { opacity: .3; cursor: default; }
.pdfv-round:focus-visible { outline: 2px solid var(--c-accent, #f5b026); outline-offset: 2px; }
.pdfv-zoomv, .pdfv-count { min-width: 48px; text-align: center;
  font-family: var(--c-font-mono, monospace); font-size: 12px; font-weight: 600;
  color: rgba(255,255,255,.8); font-variant-numeric: tabular-nums; }

/* Waiting for half a megabyte of library on a slow connection. A page-shaped
   skeleton says what is coming; a spinner says only that something is busy. */
.pdfv-skel { width: 100%; max-width: 420px; min-height: 240px; padding: 22px 20px;
  background: #fff; border-radius: 6px; display: flex; flex-direction: column; gap: 13px; }
.pdfv-skel-line { height: 11px; border-radius: 6px;
  background: linear-gradient(90deg, #eceadf 25%, #f7f5ee 50%, #eceadf 75%);
  background-size: 200% 100%; animation: pdfvShimmer 1.4s linear infinite; }
@keyframes pdfvShimmer { from { background-position: 200% 0; } to { background-position: -200% 0; } }
@media (prefers-reduced-motion: reduce) { .pdfv-skel-line { animation: none; } }

.pdfv-fallback { margin: auto; padding: 30px 20px; text-align: center; max-width: 34ch; }
.pdfv-fallback p { margin: 0 0 14px; color: rgba(255,255,255,.78); font-size: 13.5px; line-height: 1.55; }

@media (min-width: 1024px) {
  /* A document on a desktop is still the whole task, but a full-bleed page is
     not how anyone reads one. */
  .pdfv-page { padding: 24px; }
  .pdfv-bar, .pdfv-foot { padding-inline: 16px; }
}

/* ── YouTube embed (click to load) ────────────────────────────────────────
   Reserves the 16:9 box up front so the feed does not jump when the poster
   arrives or when the iframe replaces it. */
.yt { position: relative; display: block; width: 100%; aspect-ratio: 16 / 9;
  border: 0; padding: 0; border-radius: 10px; overflow: hidden; background: #000; }
.yt iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.yt-cover { cursor: pointer; }
.yt-cover img { width: 100%; height: 100%; object-fit: cover; display: block; }
.yt-play { position: absolute; inset: 0; margin: auto; width: 62px; height: 44px; border-radius: 10px;
  background: rgba(0,0,0,.72); color: #fff; font-size: 19px; display: grid; place-items: center; }
.yt-cover:hover .yt-play { background: #e4032b; }
.yt-badge { position: absolute; bottom: 8px; right: 10px; font: 700 10px var(--font-mono, monospace);
  letter-spacing: .1em; text-transform: uppercase; color: #fff; background: rgba(0,0,0,.6);
  padding: 3px 7px; border-radius: 6px; }
.yt-cover:focus-visible { outline: 3px solid #1b6ef3; outline-offset: 2px; }

/* ── Dashboard: the training-fee schedule ─────────────────────────────────
   A member asking "what am I paying?" wants the sessions, not a total. */
.dash-sched { margin-top: 12px; border-top: 1px solid rgba(12,20,50,.1); padding-top: 10px; }
.dash-sched-head { font-size: 13.5px; color: var(--ink-700, #3b4459); margin-bottom: 8px; }
.dash-sched-head b { font-size: 15px; color: var(--ink-900, #16223e); }
.dash-sched-head span { color: var(--ink-500, #5b6478); }
.dash-sched-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
.dash-sched-row { display: grid; gap: 4px 10px; align-items: baseline;
  grid-template-columns: minmax(0, 1fr) auto auto; padding: 6px 0;
  border-bottom: 1px solid rgba(12,20,50,.06); font-size: 13px; }
.dash-sched-name { font-weight: 600; color: var(--ink-900, #16223e); min-width: 0; }
.dash-sched-when { font-size: 12px; color: var(--ink-500, #5b6478); }
.dash-sched-amt { font-variant-numeric: tabular-nums; font-weight: 700; }
.dash-sched-tag { grid-column: 1 / -1; font-size: 12px; letter-spacing: .04em; text-transform: uppercase;
  color: var(--ink-500, #5b6478); }
.dash-sched-row.is-charged .dash-sched-tag { color: #2f7a3f; }
.dash-sched-row.is-upcoming { opacity: .62; }
.dash-sched-foot { margin: 10px 0 0; font-size: 13px; color: var(--ink-500, #5b6478); line-height: 1.45; }
.dash-account-halt { margin-top: 10px; padding: 9px 12px; border-radius: 10px; font-size: 13px; line-height: 1.45;
  background: #fdeaee; border: 1px solid #e4032b; color: #8c0119; }
.dash-account-halt.is-paused { background: #fff6e2; border-color: #d99400; color: #6b4600; }

/* ── Dashboard: cost of the place (NOT a bill) ────────────────────────────
   Deliberately quiet — a neutral panel, not the red of something owed. A
   figure this size next to money a family does owe has to look like a
   different KIND of thing, or it reads as part of the same total. */
.dash-cost { margin-top: 12px; padding: 10px 12px; border-radius: 10px;
  background: rgba(12,20,50,.035); border: 1px solid rgba(12,20,50,.09); }
.dash-cost-head { font-size: 13.5px; color: var(--ink-700, #3b4459); }
.dash-cost-head b { font-size: 15px; color: var(--ink-900, #16223e); font-variant-numeric: tabular-nums; }
.dash-cost-note { margin-top: 3px; font-size: 13px; color: #2f7a3f; font-weight: 600; }
.dash-cost-earned { margin-top: 6px; font-size: 13px; color: var(--ink-500, #5b6478); line-height: 1.45; }

/* ── Tournaments console ──────────────────────────────────────────────────
   The advance control is one button, and the reason it is refused is stated
   beside it rather than fired as an error after a click. */

.trn-advance { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; justify-content: space-between;
  padding: 12px 14px; border-radius: 10px; margin-bottom: 14px;
  background: rgba(12,20,50,.035); border: 1px solid rgba(12,20,50,.1); }

/* A drawn knockout game blocks the round until somebody decides, so it is
   surfaced rather than left for staff to find. */
.trn-draws { padding: 12px 14px; border-radius: 10px; margin-bottom: 14px;
  background: #fff6e2; border: 1px solid #d99400; }
.trn-draw-row { display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 6px 0; border-top: 1px solid rgba(0,0,0,.08); font-size: 13.5px; }

.trn-centres { display: grid; gap: 12px; grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr)); }
.trn-centre { border: 1px solid rgba(12,20,50,.12); border-radius: 10px; padding: 10px 12px; background: #fff; }
.trn-centre-h { font-weight: 800; font-size: 13.5px; margin-bottom: 6px; color: var(--ink-900, #16223e); }
.trn-player { display: flex; align-items: center; gap: 8px; padding: 5px 0; font-size: 13.5px;
  border-top: 1px solid rgba(12,20,50,.06); }
.trn-player.is-out { opacity: .55; text-decoration: line-through; }
.trn-x { margin-left: auto; width: 26px; height: 26px; min-height: 26px; border-radius: 50%; cursor: pointer;
  border: 1px solid rgba(0,0,0,.12); background: #fff; font-size: 12px; line-height: 1; color: var(--ink-700, #333); }
.trn-x:hover { border-color: var(--coral, #e4032b); color: var(--coral, #e4032b); }

.trn-pool { display: grid; gap: 6px; margin-top: 8px;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 200px), 1fr)); max-height: 260px; overflow-y: auto; }
.trn-pool-item { display: grid; gap: 1px; text-align: left; padding: 8px 10px; min-height: 44px; cursor: pointer;
  border: 1px solid rgba(12,20,50,.12); border-radius: 10px; background: #fff; font: inherit; }
.trn-pool-item:hover:not(:disabled) { border-color: var(--gold-500, #f5b026); }
.trn-pool-item b { font-size: 13.5px; color: var(--ink-900, #16223e); }

.trn-round { margin-bottom: 14px; }
.trn-round-h { font-size: 10.5px; font-weight: 800; letter-spacing: .12em; color: var(--ink-500, #5b6478); margin-bottom: 4px; }
.trn-game { display: grid; gap: 2px 8px; grid-template-columns: minmax(0,1fr) auto minmax(0,1fr);
  align-items: baseline; padding: 7px 0; border-bottom: 1px solid rgba(12,20,50,.07); font-size: 13.5px; }
.trn-side { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.trn-side.is-win { font-weight: 800; color: var(--ink-900, #16223e); }
.trn-side.is-lose { opacity: .55; }
.trn-v { color: var(--ink-500, #5b6478); font-size: 12px; }
.trn-game-meta { grid-column: 1 / -1; }

/* ── Admin helpers that were being used without existing ──────────────────
   `.admin-error` is referenced in two long-standing places and `.admin-err`,
   `.admin-field-label` and `.admin-skel` in the newer sections — none of them
   had a rule, so an admin error message rendered as plain unstyled text in the
   middle of a page. Defined once here, both spellings, because renaming live
   markup is a bigger change than honouring it. */
.admin-err, .admin-error { background: #fdeaee; border: 1px solid #e4032b; color: #8c0119;
  padding: 10px 14px; border-radius: 10px; margin: 0 0 14px; font-size: 13.5px; }
.admin-field-label { font-size: 12px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase;
  color: var(--ink-500, #5b6478); margin-bottom: 6px; }
/* A loading placeholder, not a spinner: the console lists tables, and a block
   the shape of the table it is about to become moves less than a spinner does. */
.admin-skel { height: 132px; border-radius: 10px; margin: 6px 0 14px;
  background: linear-gradient(100deg, rgba(12,20,50,.05) 30%, rgba(12,20,50,.10) 50%, rgba(12,20,50,.05) 70%);
  background-size: 300% 100%; animation: adminSkel 1.3s ease-in-out infinite; }
@keyframes adminSkel { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
@media (prefers-reduced-motion: reduce) { .admin-skel { animation: none; } }


/* The tournament components are shared with the members' app, which sizes them
   for a phone. Inside the console they get a reading width and the app's own
   gutter, so a table meant for 390px does not stretch across a 1440px desk. */
.trn-admin-wrap { --c-gutter: 0px; max-width: 720px; }
.trn-admin-wrap .cmm-screen { height: auto; min-height: 0; }
.trn-admin-wrap .cmm-stream { overflow: visible; padding: 0; }
.trn-admin-wrap .cmm-ch-head { padding-left: 0; padding-right: 0; }

/* The console centres text inside .admin-card by default, which reads as a
   banner rather than as a thing you act on. This card is a lead-in to the
   wizard, so it is set left like the prose above it. */
.trn-host-card { text-align: left; }
.trn-host-card .admin-hint { max-width: 62ch; margin-left: 0; }

/* Reading panels inside a drawer. `.admin-card` is the console's clickable
   tile — centred text, a pointer cursor, a hover lift — and the print
   drawer's preflight and failure list are none of those things: they are
   prose you read before pressing the button. Same surface, plain behaviour. */
.admin-note-card { text-align: left; cursor: default; }
.admin-note-card:hover { transform: none; }

/* An action that belongs inside a sentence — "…have no photograph. Show these
   12." A button, because it acts rather than navigates, styled as the link it
   reads as. WCAG 2.5.8's inline exception covers a target sized by the
   line-height of the text around it, but the rows it sits in are spaced to
   clear 24px anyway; leaning on an exception is not the same as being
   comfortable to hit. */
.admin-inline-link {
  display: inline; padding: 0; border: 0; background: none; cursor: pointer;
  font: inherit; color: var(--navy-700, #1c2a5e); text-decoration: underline;
  text-underline-offset: 2px;
}
.admin-inline-link:hover { text-decoration-thickness: 2px; }
.admin-inline-link:focus-visible { outline: 2px solid var(--navy-700, #1c2a5e); outline-offset: 2px; border-radius: 6px; }

/* ═══════════════════════════════════════════════════════════════════════════
   DESIGN STUDIO — THE SYSTEM
   ═══════════════════════════════════════════════════════════════════════════

   Direction, in one sentence, so every choice below can be checked against it:
   A DARK PRESS ROOM — ink-blue surfaces, ONE amber accent earned only by the
   live action, geometric sans for structure over monospace for every number
   and label. An instrument, not an app.

   The studio had tokens for colour and nothing else, so it grew SEVEN corner
   radii and FIVE control heights on one screen, borders around every surface,
   and type at whatever size each line was written. That is what "rough" is:
   not one bad decision, a hundred un-made ones. Closed scales below; nothing
   in the studio may use a value that is not on them.

   The card being designed is the only bright object on the screen. Everything
   else is instrument housing and recedes on purpose — which is also why the
   accent is rationed to exactly one live control at a time.
   ═══════════════════════════════════════════════════════════════════════════ */
:root {
  /* Surfaces — three levels, by elevation, NOT by outline. The old studio drew
     a 1px border around everything; depth now comes from the surface stepping
     lighter, and lines are kept for true divisions. */
  --dsn-bg:        #0d1424;
  --dsn-s1:        #141c30;   /* panels, bar, rails                */
  --dsn-s2:        #1b2440;   /* controls, raised rows             */
  --dsn-s3:        #232e4f;   /* hover / active control            */
  --dsn-sink:      #0a1020;   /* inset wells: canvas ground, lists */

  /* Ink — four steps, and they are the only text colours. */
  --dsn-ink:       #eaf0ff;
  --dsn-ink-2:     #b8c4de;   /* secondary body                    */
  --dsn-ink-3:     #8d9ab8;   /* labels, captions — 4.5:1 on s1    */
  --dsn-ink-4:     #66738f;   /* disabled only, never for reading  */

  --dsn-line:      rgba(255,255,255,0.09);
  --dsn-line-2:    rgba(255,255,255,0.17);

  --dsn-gold:      #f5b026;
  --dsn-gold-ink:  #2a1d00;   /* text ON gold                      */
  --dsn-gold-dim:  rgba(245,176,38,0.14);

  --dsn-ok:  #6fdc9d;  --dsn-warn: #ffce54;  --dsn-bad: #ff8f8f;

  /* Radius language — three, and a pill. Not seven. */
  --dsn-r-surface: 16px;
  --dsn-r-control: 10px;
  --dsn-r-inner:   8px;
  --dsn-r-pill:    999px;

  /* Space — a closed scale. Layout uses gap, never per-element margins. */
  --dsn-sp-1: 4px;  --dsn-sp-2: 8px;  --dsn-sp-3: 12px;
  --dsn-sp-4: 16px; --dsn-sp-5: 24px; --dsn-sp-6: 32px;

  /* ONE control height for the chrome. Everything that can be clicked in the
     bar, the tool row and the rails is exactly this tall, which is the single
     biggest reason the old bar read as unfinished — a 40px input beside a
     30px button beside a 34px tool. 36px is the expert-tool density; coarse
     pointers get 44 below. */
  --dsn-ctl: 36px;

  /* Type — a closed scale with roles. */
  --dsn-t-display: 24px;   /* the design's name, once per screen */
  --dsn-t-head:    15px;   /* panel headings                     */
  --dsn-t-body:    13.5px; /* prose, hints                       */
  --dsn-t-ctl:     13px;   /* control text                       */
  --dsn-t-small:   12px;   /* dense secondary rows               */
  --dsn-t-meta:    10px;   /* mono eyebrows and captions         */
}
@media (pointer: coarse) { :root { --dsn-ctl: 44px; } }

/* ── Ground ─────────────────────────────────────────────────────────────── */
.dsn-wrap, .dsn-page { background: var(--dsn-bg); }

/* ── Every control in the studio chrome is the same object ──────────────── */
.dsn-bar .admin-input,
.dsn-bar .admin-select,
.dsn-bar select,
.dsn-bar input,
.dsn-zone select,
.dsn-zone input,
.dsn-merge-filters select,
.dsn-merge-filters input,
.dsn-merge-run select,
.dsn-merge-size select {
  height: var(--dsn-ctl);
  box-sizing: border-box;
  padding: 0 var(--dsn-sp-3);
  border-radius: var(--dsn-r-control);
  border: 1px solid var(--dsn-line);
  background: var(--dsn-s2);
  color: var(--dsn-ink);
  font: 500 var(--dsn-t-ctl)/1 var(--font-sans, system-ui, sans-serif);
  font-variant-numeric: tabular-nums;
  transition: border-color .12s ease, background .12s ease;
}
.dsn-bar input:hover, .dsn-zone input:hover,
.dsn-bar select:hover, .dsn-zone select:hover,
.dsn-merge-filters select:hover, .dsn-merge-filters input:hover {
  background: var(--dsn-s3); border-color: var(--dsn-line-2);
}

/* Native select chrome is the loudest "unfinished" tell on a dark UI: the OS
   draws its own light-mode arrow in its own light-mode box. One caret, drawn
   as a background image, and the field keeps the studio's surface. */
.dsn-bar select, .dsn-zone select,
.dsn-merge-filters select, .dsn-merge-run select, .dsn-merge-size select {
  appearance: none; -webkit-appearance: none;
  padding-right: 30px;
  background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'%3E%3Cpath d='M1 1l4 4 4-4' fill='none' stroke='%238d9ab8' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 11px center;
}
/* The options list is drawn by the OS; give it a surface it can actually use. */
.dsn-bar select option, .dsn-zone select option, .dsn-merge-filters select option {
  background: var(--dsn-s1); color: var(--dsn-ink);
}

/* One focus ring, everywhere, in the accent. Visible is the requirement; this
   is also the only other place the gold is spent. */
.dsn-bar :is(input, select, button):focus-visible,
.dsn-zone :is(input, select, button):focus-visible,
.dsn-merge :is(input, select, button):focus-visible,
.dsn-tool:focus-visible, .dsn-layer-hit:focus-visible {
  outline: 2px solid var(--dsn-gold);
  outline-offset: 2px;
  border-radius: var(--dsn-r-control);
}

/* ── Buttons: one shape, three weights ──────────────────────────────────── */
.dsn-bar .btn, .dsn-zone .btn, .dsn-merge .btn, .dsn-exports .btn {
  height: var(--dsn-ctl);
  min-height: var(--dsn-ctl);
  padding: 0 var(--dsn-sp-4);
  border-radius: var(--dsn-r-control);
  font: 600 var(--dsn-t-ctl)/1 var(--font-sans, system-ui, sans-serif);
  display: inline-flex; align-items: center; justify-content: center;
  white-space: nowrap;
  transition: background .12s ease, border-color .12s ease;
}
.dsn-bar .btn-ghost, .dsn-zone .btn-ghost, .dsn-merge .btn-ghost, .dsn-exports .btn-ghost {
  background: var(--dsn-s2); border: 1px solid var(--dsn-line); color: var(--dsn-ink);
}
.dsn-bar .btn-ghost:hover:not(:disabled), .dsn-zone .btn-ghost:hover:not(:disabled),
.dsn-merge .btn-ghost:hover:not(:disabled), .dsn-exports .btn-ghost:hover:not(:disabled) {
  background: var(--dsn-s3); border-color: var(--dsn-line-2);
}
.dsn-bar .btn-primary, .dsn-zone .btn-primary, .dsn-merge .btn-primary, .dsn-exports .btn-primary {
  background: var(--dsn-gold); border: 1px solid var(--dsn-gold);
  color: var(--dsn-gold-ink); font-weight: 700;
  box-shadow: 0 1px 0 rgba(0,0,0,0.18);
}
.dsn-bar .btn:disabled, .dsn-zone .btn:disabled, .dsn-merge .btn:disabled { opacity: .38; }

/* ── The bar ────────────────────────────────────────────────────────────── */
.dsn-bar {
  background: var(--dsn-s1);
  border: 1px solid var(--dsn-line);
  border-radius: var(--dsn-r-surface);
  padding: var(--dsn-sp-3) var(--dsn-sp-4);
  gap: var(--dsn-sp-3);
  margin: 0 0 var(--dsn-sp-4);
  box-shadow: 0 1px 0 rgba(255,255,255,0.04) inset;
  backdrop-filter: none;
}
.dsn-zone { gap: var(--dsn-sp-2); padding-left: var(--dsn-sp-4); margin-left: 0; }
.dsn-zone-cap {
  font: 700 var(--dsn-t-meta)/1 var(--font-mono, ui-monospace, monospace);
  letter-spacing: .16em; text-transform: uppercase;
  color: var(--dsn-ink-3);
}
/* The field captions inside a zone: same voice as the zone caption, one step
   quieter, stacked over their control rather than beside it. */
.dsn-zone .dsn-prop > span {
  font: 600 var(--dsn-t-meta)/1 var(--font-mono, ui-monospace, monospace);
  letter-spacing: .14em; text-transform: uppercase;
  color: var(--dsn-ink-3);
  margin-bottom: var(--dsn-sp-1);
}

/* ── The tool row: an instrument strip, not a row of loose glyphs ───────── */
.dsn-tools {
  background: var(--dsn-s1);
  border: 1px solid var(--dsn-line);
  border-radius: var(--dsn-r-control);
  padding: var(--dsn-sp-2);
  gap: var(--dsn-sp-1);
}
.dsn-tool {
  width: var(--dsn-ctl); height: var(--dsn-ctl);
  border-radius: var(--dsn-r-inner);
  color: var(--dsn-ink-2);
}
.dsn-tool:hover:not(:disabled) { background: var(--dsn-s3); color: var(--dsn-ink); border-color: transparent; }
.dsn-tool.is-on { background: var(--dsn-gold-dim); color: #ffd98a; border-color: transparent; }
.dsn-tool-grp { border-right: 1px solid var(--dsn-line); padding-right: var(--dsn-sp-2); margin-right: var(--dsn-sp-1); }
.dsn-size-note {
  font: 500 var(--dsn-t-meta)/1 var(--font-mono, ui-monospace, monospace);
  letter-spacing: .1em; color: var(--dsn-ink-3); font-variant-numeric: tabular-nums;
}

/* ── Stage: the canvas sits in a WELL, so the card is the lit object ────── */
.dsn-stage {
  background: var(--dsn-sink);
  border: 1px solid var(--dsn-line);
  border-radius: var(--dsn-r-surface);
  padding: var(--dsn-sp-5) var(--dsn-sp-4);
  gap: var(--dsn-sp-3);
}
.dsn-canvas-host { border-radius: var(--dsn-r-inner); box-shadow: 0 24px 60px -24px rgba(0,0,0,0.85); }
.dsn-stage-note { font: 500 var(--dsn-t-meta)/1.5 var(--font-mono, ui-monospace, monospace); color: var(--dsn-ink-3); letter-spacing: .08em; }

/* ── Rails ──────────────────────────────────────────────────────────────── */
.dsn-rail {
  background: var(--dsn-s1);
  border: 1px solid var(--dsn-line);
  border-radius: var(--dsn-r-surface);
  padding: var(--dsn-sp-3);
}
.dsn-rail-head {
  font: 700 var(--dsn-t-meta)/1 var(--font-mono, ui-monospace, monospace);
  letter-spacing: .16em; text-transform: uppercase; color: var(--dsn-ink-3);
  background: var(--dsn-s1);
  border-bottom: 1px solid var(--dsn-line);
  margin: calc(var(--dsn-sp-3) * -1) calc(var(--dsn-sp-3) * -1) var(--dsn-sp-2);
  padding: var(--dsn-sp-3);
}

/* ── The batch panel ────────────────────────────────────────────────────── */
.dsn-merge {
  background: var(--dsn-s1);
  border: 1px solid var(--dsn-line);
  border-radius: var(--dsn-r-surface);
  padding: var(--dsn-sp-4);
  box-shadow: none;
}
.dsn-merge-head b { font: 700 var(--dsn-t-head)/1.3 var(--font-sans, system-ui, sans-serif); letter-spacing: -0.01em; }
.dsn-merge-filters {
  background: var(--dsn-sink);
  border: 1px solid var(--dsn-line);
  border-radius: var(--dsn-r-control);
  padding: var(--dsn-sp-3);
  gap: var(--dsn-sp-3);
}
.dsn-merge-filters .dsn-prop > span,
.dsn-merge-run .dsn-prop > span,
.dsn-merge-size > span {
  font: 600 var(--dsn-t-meta)/1 var(--font-mono, ui-monospace, monospace);
  letter-spacing: .14em; text-transform: uppercase; color: var(--dsn-ink-3);
}
.dsn-merge-note { font: 500 var(--dsn-t-meta)/1.4 var(--font-mono, ui-monospace, monospace); color: var(--dsn-ink-3); letter-spacing: .06em; font-variant-numeric: tabular-nums; }
.dsn-merge-picks { background: var(--dsn-s1); border-bottom: 1px solid var(--dsn-line); padding: var(--dsn-sp-2) 0; }
.dsn-merge-list { border-radius: var(--dsn-r-control); background: var(--dsn-sink); border: 1px solid var(--dsn-line); }
.dsn-tbl { font-size: var(--dsn-t-ctl); font-variant-numeric: tabular-nums; }
.dsn-tbl thead th { background: var(--dsn-s1); }
.dsn-tbl tbody tr:hover { background: rgba(255,255,255,0.035); }
.dsn-merge-flag {
  border-radius: var(--dsn-r-pill);
  font: 600 var(--dsn-t-meta)/1 var(--font-mono, ui-monospace, monospace);
  letter-spacing: .1em; padding: 5px 9px;
}
.dsn-chip { border-radius: var(--dsn-r-pill); height: 30px; padding: 0 var(--dsn-sp-3); font-size: var(--dsn-t-ctl); }

/* ── Motion, and the promise to switch it off ───────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .dsn-bar *:not(#_):not(#_), .dsn-tools *:not(#_):not(#_), .dsn-merge *:not(#_):not(#_) { transition: none; animation: none; }
}

/* The document picker, now a control rather than a banner. It holds the
   longest strings in the bar (a design name plus "· v3"), so it gets the most
   room of the three Design fields and truncates rather than stretching. */
.dsn-bar-open { flex: 0 1 210px; min-width: 0; }
.dsn-bar-open select { width: 100%; min-width: 0; text-overflow: ellipsis; }

/* The page's one eyebrow. Sentence case, secondary ink: it names the room,
   it does not advertise it. */
.dsn-eyebrow {
  font: 600 var(--dsn-t-meta)/1 var(--font-mono, ui-monospace, monospace);
  letter-spacing: .22em; text-transform: uppercase;
  color: var(--dsn-ink-3);
}
/* An OPEN toggle is a state, not the live action. The solid accent stays with
   Publish — one gold button on screen at a time — and a held-down control
   reads the way the tool row's held-down controls already read. */
.dsn-bar .btn-ghost.is-on, .dsn-zone .btn-ghost.is-on, .dsn-exports .btn-ghost.is-on {
  background: var(--dsn-gold-dim);
  border-color: rgba(245,176,38,0.55);
  color: #ffd98a;
}
/* OUTPUT to the row's end. It wraps to a second line at this density whatever
   is done — four buttons will not fit beside everything else — so the choice
   is whether the second line looks decided or accidental. Right-aligned, the
   bar reads document-left / output-right; left-aligned it read as a stray. */
.dsn-zone-end { margin-left: auto; }

/* ── The bar, tightened ─────────────────────────────────────────────────── */
.dsn-bar { padding: var(--dsn-sp-2) var(--dsn-sp-4); row-gap: var(--dsn-sp-2); }
/* A zone's caption and its fields share a baseline; the caption no longer
   needs the field's full height beneath it. */
.dsn-zone { align-items: flex-end; }

/* ── Export formats: one object, not three buttons ──────────────────────────
   PNG / PDF / SVG are three routes to the same act, so they read as one
   segmented control — shared outline, hairline dividers, no gaps — and Batch,
   which is a different act entirely, keeps its own shape beside them. Three
   equally-weighted standalone buttons said "three decisions" for what is
   really one decision with three answers. */
.dsn-exports { gap: var(--dsn-sp-2); align-items: center; }
.dsn-exports .btn:nth-child(-n+3) { border-radius: 0; margin: 0; border-left-width: 0; }
.dsn-exports .btn:nth-child(1) {
  border-top-left-radius: var(--dsn-r-control);
  border-bottom-left-radius: var(--dsn-r-control);
  border-left-width: 1px;
}
.dsn-exports .btn:nth-child(3) {
  border-top-right-radius: var(--dsn-r-control);
  border-bottom-right-radius: var(--dsn-r-control);
  margin-right: var(--dsn-sp-2);
}
/* The segment that is hovered lifts above its neighbours' shared edge. */
.dsn-exports .btn:nth-child(-n+3):hover:not(:disabled) { position: relative; z-index: 1; }

/* A wrapping row of controls, on the studios' spacing scale. It outlived the
   old Card Studio it was written for: the review desk's sticky bar uses it. */
.cs-row { display: flex; flex-wrap: wrap; align-items: center; gap: var(--dsn-sp-3); }

/* The Analyst's unconfigured state. Not an error colour: nothing has gone
   wrong, a thing has not been switched on — and the figures behind the pane
   are fine, which is what the operator needs to hear before anything else. */
.anp-note {
  margin: 10px 12px 0;
  padding: 10px 12px;
  border: 1px solid var(--dsn-line-2);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.05);
  font-size: 12.5px; line-height: 1.55; color: rgba(230, 238, 255, 0.82);
}
.anp-note code {
  font-family: var(--font-mono, ui-monospace, monospace); font-size: 11.5px;
  background: rgba(0, 0, 0, 0.28); padding: 1px 5px; border-radius: 4px;
}

/* ── A member's division (NGGC 2040 brief §5) ───────────────────────────────
   Identity, not a setting — the brief lists Division beside a member's name
   and mentor as one of the six things they should be able to say about
   themselves. Chrome here rather than inline, per CLAUDE.md §11; the only
   thing the component sets is the accent bar, whose colour is the division's
   own and which a stylesheet cannot know. */
.dash-division-bar { height: 4px; border-radius: 2px; margin-bottom: 12px; }
.dash-division-code { font-size: 11px; letter-spacing: .14em; color: var(--ink-400); }
.dash-division-name { font-family: var(--font-display); font-size: 21px; line-height: 1.15;
  letter-spacing: -0.01em; color: var(--ink-900); margin-top: 2px; }
.dash-division-mandate { font-size: 14.5px; line-height: 1.55; color: var(--ink-700);
  margin: 8px 0 12px; max-width: 58ch; }
.dash-division-audience { font-size: 13.5px; line-height: 1.55; color: var(--ink-700); margin: 6px 0 0; }
.dash-division-courses { list-style: none; margin: 0; padding: 0; display: flex;
  flex-wrap: wrap; gap: 6px; }
.dash-division-courses li { font-size: 12.5px; line-height: 1.3; padding: 4px 10px;
  border-radius: 999px; background: var(--cream-100); color: var(--ink-700); }
/* The one course in all four lists. Inverted so it reads as the exception it
   is, without needing a caption to explain the highlight. */
.dash-division-courses li.is-chess { background: var(--navy-900); color: #fff; font-weight: 600; }
.dash-division-note { font-size: 12.5px; line-height: 1.5; color: var(--ink-500);
  margin: 12px 0 0; max-width: 58ch; }
.dash-division-empty { font-size: 14px; line-height: 1.55; color: var(--ink-500);
  margin: 0; max-width: 58ch; }

/* ── The mentor's weekly review (NGGC 2040 brief §18) ───────────────────────
   Twelve questions for one child for one week, and the list of children
   nobody has answered them for. Same dark portal surfaces as the rest of the
   Mentor Portal; chrome here rather than inline, per CLAUDE.md §11. */
.mrv-q { display: flex; flex-direction: column; gap: 6px; }
.mrv-q + .mrv-q { margin-top: 12px; }
.mrv-q-lbl { font-size: 13.5px; line-height: 1.45; color: rgba(230,238,255,.82); display: flex; gap: 8px; }
.mrv-q-n { font: 700 11px var(--font-mono, monospace); color: rgba(230,238,255,.45);
  min-width: 18px; padding-top: 2px; font-variant-numeric: tabular-nums; }
.mrv-q textarea { padding: 10px 12px; border-radius: 11px; font-size: 16px; min-height: 44px;
  background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.2); color: #eef2fb;
  font-family: inherit; box-sizing: border-box; width: 100%; resize: vertical; }
/* A question already answered reads as done without needing a tick: the rail
   is the only difference, and it is the one thing the eye scans for. */
.mrv-q.is-done .mrv-q-lbl { color: rgba(230,238,255,.55); }
.mrv-q.is-done textarea { border-left: 3px solid var(--dsn-gold, #ffce54); }

.mrv-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
  flex-wrap: wrap; margin-bottom: 12px; }
.mrv-count { font: 700 11px var(--font-mono, monospace); letter-spacing: .14em;
  color: rgba(230,238,255,.55); text-transform: uppercase; font-variant-numeric: tabular-nums; }

/* Eight weeks, gaps kept as gaps — an unreviewed week is the information. */
.mrv-weeks { display: flex; gap: 5px; margin: 0 0 14px; padding: 0; list-style: none; flex-wrap: wrap; }
.mrv-week { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center;
  font: 700 11px var(--font-mono, monospace); font-variant-numeric: tabular-nums;
  background: rgba(255,255,255,.06); border: 1px dashed rgba(255,255,255,.18);
  color: rgba(230,238,255,.45); }
.mrv-week.is-done { background: var(--dsn-gold, #ffce54); border-style: solid;
  border-color: transparent; color: #2b2100; }
.mrv-week.is-concern { box-shadow: inset 0 0 0 2px rgba(255,120,90,.9); }

/* The due strip on the roster: the §18 question, answered at a glance. */
.mrv-due { background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.14);
  border-radius: 14px; padding: 12px 14px; margin-bottom: 12px; }
.mrv-due.is-clear { border-color: rgba(127,209,166,.45); }
.mrv-due-h { display: flex; align-items: center; justify-content: space-between; gap: 12px;
  flex-wrap: wrap; }
.mrv-due-t { font-size: 14px; font-weight: 700; color: #eef2fb; }
.mrv-due-names { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; padding: 0; list-style: none; }
.mrv-due-names button { font-size: 13px; padding: 7px 12px; min-height: 36px; border-radius: 999px;
  background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.16); color: #eef2fb;
  cursor: pointer; font-family: inherit; }
.mrv-due-names button:hover { background: rgba(255,255,255,.14); }
@media (pointer: coarse) { .mrv-due-names button { min-height: 44px; } }

/* ── Two mentor records, one email ──────────────────────────────────────────
   Everybody in a pair is locked out of the Mentor Portal until the desk
   separates them, and they cannot report it — the thing that is broken is
   their way in. So this is a warning that names people, not a badge count. */
.admin-clash { background: rgba(255,120,90,.08); border: 1px solid rgba(255,120,90,.45);
  border-radius: 14px; padding: 14px 16px; margin-bottom: 16px; }
.admin-clash-h { font-size: 15px; font-weight: 700; color: var(--ink-900); }
.admin-clash-p { font-size: 13.5px; line-height: 1.55; color: var(--ink-700);
  margin: 6px 0 12px; max-width: 70ch; }
.admin-clash-group + .admin-clash-group { margin-top: 12px; padding-top: 12px;
  border-top: 1px solid rgba(255,120,90,.28); }
.admin-clash-email { font-size: 12px; letter-spacing: .04em; color: var(--ink-500); }
.admin-clash-rows { list-style: none; margin: 6px 0 0; padding: 0; display: flex;
  flex-wrap: wrap; gap: 8px; }
.admin-clash-rows button { display: flex; flex-direction: column; gap: 2px; text-align: left;
  padding: 9px 13px; min-height: 44px; border-radius: 11px; cursor: pointer; font-family: inherit;
  background: #fff; border: 1px solid var(--cream-200); color: var(--ink-900); }
.admin-clash-rows button:hover { border-color: rgba(255,120,90,.6); }
.admin-clash-name { font-size: 14px; font-weight: 600; }
.admin-clash-meta { font-size: 11.5px; color: var(--ink-500); }

/* ============================================================
   THE DARK-SHELL RETRY
   The Mentor Portal, the Gate desk and the Review desk each drew
   this button themselves, from the same inline style object copied
   three times. Two sat at 37px; the third had `minHeight: 44` added
   by hand — which is the whole argument of CLAUDE.md §11 in one
   control. An inline style beats the stylesheet, so the fix applied
   to one could not reach the other two, and nothing could tell they
   had drifted. Two more copies, in the Club class and skills panels,
   are the inline variant below.
   ============================================================ */
.shell-retry {
  margin-top: 12px; min-height: 44px; padding: 10px 20px;
  border-radius: 10px; border: 1px solid rgba(255, 255, 255, 0.25);
  background: transparent; color: #fff;
  font: inherit; font-weight: 700; cursor: pointer;
}
.shell-retry:hover { border-color: rgba(255, 255, 255, 0.5); background: rgba(255, 255, 255, 0.06); }
.shell-retry:focus-visible { outline: 2px solid #ffce54; outline-offset: 2px; }

/* The inline variant — a retry inside a sentence, not a block. It stays a
   link visually, and takes its reach from padding instead of a box, so the
   sentence does not grow a button in the middle of it. */
.shell-retry-inline {
  /* #ffce54, the literal the dark shells all declare as their local `gold`
     — NOT --gold-400 (#f5b026), which is the lighter site's gold and would
     change how this reads on navy. */
  background: none; border: none; color: #ffce54;
  text-decoration: underline; cursor: pointer; font: inherit;
  padding: 12px 4px; min-height: 44px;
}
.shell-retry-inline:focus-visible { outline: 2px solid #ffce54; outline-offset: 2px; }

/* ── Control Room · Quote of the week ─────────────────────────────────── */
.wis-sched { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(150px, 1fr); gap: 8px; overflow-x: auto; margin: 16px 0 20px; padding-bottom: 4px; }
.wis-sched-cell { display: grid; gap: 4px; padding: 12px; border-radius: 12px; background: rgba(12,20,50,0.04); border-top: 3px solid var(--gold-500); min-width: 0; }
.wis-sched-cell.wis-igbo { border-top-color: #2f9e44; }
.wis-sched-cell.wis-yoruba { border-top-color: #d9480f; }
.wis-sched-cell.is-now { background: var(--navy-900); color: #fff; }
.wis-sched-wk { font-family: var(--font-mono); font-size: 11px; letter-spacing: .1em; text-transform: uppercase; opacity: .8; }
.wis-sched-lang { font-weight: 700; font-size: 14px; }
.wis-sched-tx { font-size: 13px; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.wis-tabs { display: flex; gap: 6px; margin-bottom: 14px; flex-wrap: nowrap; overflow-x: auto; overflow-y: hidden; scrollbar-width: none; scroll-snap-type: x proximity; }
.wis-tabs > * { flex: 0 0 auto; white-space: nowrap; scroll-snap-align: start; }
.wis-tab { min-height: 40px; padding: 0 16px; border-radius: 999px; border: 1px solid rgba(12,20,50,0.18); background: #fff; font-weight: 600; cursor: pointer; color: var(--navy-900); }
.wis-tab.is-on { background: var(--navy-900); color: #fff; border-color: var(--navy-900); }
.wis-count { font-family: var(--font-mono); font-size: 12px; opacity: .75; margin-left: 4px; }
.wis-note { margin: 0 0 14px; }
.wis-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; container-type: inline-size; }
.wis-item { text-align: left; display: grid; grid-template-columns: minmax(0, 1fr) minmax(240px, 320px); gap: 20px; }
.wis-item.is-hidden { opacity: .7; }
.wis-item-meta { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; margin-bottom: 8px; }
.wis-pos { font-family: var(--font-mono); font-weight: 700; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; background: rgba(12,20,50,0.07); font-size: 12px; }
.wis-live { background: var(--gold-500); color: var(--navy-900); }
.wis-text { font-family: var(--font-display); font-weight: 600; font-size: 18px; line-height: 1.3; margin: 0 0 6px; }
.wis-tr { font-style: italic; color: var(--ink-700); margin: 0 0 6px; }
.wis-ans { margin: 0; font-size: 14px; color: var(--ink-700); }
.wis-order { display: flex; gap: 4px; flex-wrap: wrap; margin-bottom: 10px; }
.wis-voice { display: grid; gap: 8px; padding: 12px; border-radius: 12px; background: rgba(12,20,50,0.035); }
.wis-voice-head { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; }
.wis-voice-src { font-size: 12px; color: var(--ink-700); }
.wis-audio { width: 100%; height: 36px; }
.wis-voice-row { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
.wis-voice-sel { flex: 1 1 110px; min-width: 0; }
.wis-empty { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.wis-form { display: grid; gap: 12px; }
.wis-form-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; }
.wis-form-actions { display: flex; justify-content: flex-end; gap: 8px; }
@container (max-width: 700px) { .wis-item { grid-template-columns: 1fr; } }
.wis-sched-n { font-family: var(--font-mono); font-weight: 400; font-size: 12px; opacity: .8; }
.wis-vs { text-align: left; display: grid; gap: 12px; margin-bottom: 18px; }
.wis-vs-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }
.wis-vs-head .admin-field-label { margin: 0; }
.wis-vs-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; }
.wis-clones { display: grid; gap: 8px; padding-top: 12px; border-top: 1px solid rgba(12,20,50,0.08); }
.wis-clone-row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 8px 12px; border-radius: 10px; background: rgba(12,20,50,0.035); }
.wis-clone-name { font-weight: 700; }
.wis-clone-meta { font-size: 13px; color: var(--ink-700); flex: 1 1 auto; }
.wis-clone-form { display: grid; gap: 10px; padding: 14px; border-radius: 12px; background: rgba(12,20,50,0.035); }
.wis-warn { font-size: 13px; color: #9a3412; }
.wis-voice-en { padding-top: 8px; border-top: 1px solid rgba(12,20,50,0.08); }
.wis-score { font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 999px; justify-self: start; }
.wis-score.is-good { background: rgba(47,158,68,0.12); color: #1d6b2f; }
.wis-score.is-low { background: rgba(224,49,49,0.1); color: #a02020; }
.wis-saved { font-family: var(--font-mono); font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--ink-700); }
/* ── Member dashboard ──────────────────────────────────────────────────────
   The Members section opens on a dashboard rather than page one of a roster,
   because a page of fifty rows answers no question anybody arrived with. */
/* align-items: start, so a short panel keeps its own height instead of
   being stretched to match a tall neighbour and trailing a half-screen of
   empty card. */
.mem-dash-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin-top: 18px; align-items: start; }
.mem-dash-grid > section { min-width: 0; }
/* A second tile row on the Members dashboard, headed so it reads as its own group. */
.mem-dash-sub { margin: 22px 0 10px; }
@media (max-width: 900px) { .mem-dash-grid { grid-template-columns: 1fr; } }

.mem-bar-row { display: grid; grid-template-columns: minmax(96px, 9rem) 1fr auto; align-items: center; gap: 10px; margin-top: 9px; font-size: 13px; }
.mem-bar-label { color: var(--ink-700, #3c434f); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mem-bar-sub { color: var(--ink-400, #5f6874); font-size: 12px; }
.mem-bar-track { background: var(--line-200, #e7e9ee); border-radius: 999px; height: 8px; overflow: hidden; }
.mem-bar-fill { background: var(--navy-900, #111827); height: 100%; border-radius: 999px; min-width: 2px; }
.mem-bar-n { color: var(--ink-700, #3c434f); font-variant-numeric: tabular-nums; }

/* Only problems that exist are listed. A panel of zeroes trains people to
   skip the panel, including on the day it is not zero. */
.mem-issues { list-style: none; margin: 4px 0 0; padding: 0; }
.mem-issue { display: flex; gap: 12px; align-items: baseline; padding: 10px 0; border-top: 1px solid var(--line-200, #e7e9ee); }
.mem-issue:first-child { border-top: 0; }
.mem-issue-n { font-size: 20px; font-weight: 700; color: var(--gold-700, #8a6d1f); min-width: 3ch; text-align: right; font-variant-numeric: tabular-nums; }
.mem-issue-text { font-size: 13.5px; color: var(--ink-800, #272c35); }
.mem-issue-hint { display: block; color: var(--ink-400, #5f6874); font-size: 12.5px; margin-top: 2px; }

.mem-consent { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--line-200, #e7e9ee); font-size: 13px; color: var(--ink-700, #3c434f); }
.mem-scope-note { margin-top: 14px; font-size: 12.5px; color: var(--ink-400, #5f6874); }
.mem-dupes > section { margin-top: 14px; }

/* ── Data quality: the findings, as buttons ──────────────────────────────
 * Each tile is the list, not the statistic. A tile at zero is drawn and
 * disabled rather than hidden: "nobody is missing an email" and "nobody
 * checked" are different facts, and hiding the first makes the panel
 * shorter on exactly the days it should be reassuring. */
.mem-seg-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 10px; margin-top: 14px; }
.mem-seg { display: flex; flex-direction: column; gap: 4px; align-items: flex-start; text-align: left;
           padding: 12px 14px; min-height: 44px; border: 1px solid var(--line-200, #e7e9ee);
           border-radius: 12px; background: transparent; cursor: pointer; font: inherit; color: inherit; }
.mem-seg:hover:not(:disabled) { border-color: var(--gold-700, #8a6d1f); background: rgba(138, 109, 31, 0.06); }
.mem-seg-n { font-size: 22px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--gold-700, #8a6d1f); }
.mem-seg-l { font-size: 12.5px; color: var(--ink-700, #3c434f); }
.mem-seg.is-clear { opacity: .5; cursor: default; }
.mem-seg.is-clear .mem-seg-n { color: var(--ink-400, #5f6874); }

.mem-seg-on { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 12px 0 0;
              padding: 10px 12px; border-radius: 10px; background: rgba(138, 109, 31, 0.08);
              font-size: 13px; color: var(--ink-800, #272c35); }

/* ── Bulk ────────────────────────────────────────────────────────────────
 * Sticky, because the selection is made by scrolling and the thing that
 * acts on it must not be above the fold somebody has left. */
.mem-bulk { position: sticky; top: 0; z-index: 4; margin: 12px 0; padding: 10px 12px;
            border: 1px solid var(--gold-700, #8a6d1f); border-radius: 12px;
            background: var(--paper, #fff); }
.mem-bulk-row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
/* The controls are narrow on purpose. Left to grow, a two-word select
   stretched the width of the bar and the row read as a form rather than a
   toolbar. */
.mem-bulk-row .admin-select, .mem-bulk-row .admin-input { flex: 0 1 15rem; min-width: 9rem; }
.mem-bulk-out { margin-top: 10px; font-size: 13px; color: var(--ink-700, #3c434f); }
.mem-bulk-out.has-skips { color: var(--ink-800, #272c35); }
.mem-bulk-skips { list-style: none; margin: 6px 0 0; padding: 0; font-size: 12.5px; }
.mem-bulk-skips li { padding: 3px 0; color: var(--ink-400, #5f6874); }

.mem-pick-col { width: 36px; text-align: center; }
.mem-pick-col input { width: 18px; height: 18px; }
tr.is-picked { background: rgba(138, 109, 31, 0.07); }

/* ── Merge ───────────────────────────────────────────────────────────── */
.mem-dupe-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.mem-merge-pick { display: flex; gap: 10px; flex-wrap: wrap; margin: 12px 0; }
.mem-merge-opt { display: flex; gap: 8px; align-items: center; padding: 10px 12px; min-height: 44px;
                 border: 1px solid var(--line-200, #e7e9ee); border-radius: 10px; cursor: pointer; font-size: 13px; }
.mem-merge-opt.is-on { border-color: var(--gold-700, #8a6d1f); background: rgba(138, 109, 31, 0.07); }
.mem-merge-role { color: var(--ink-400, #5f6874); font-size: 12px; }
.mem-merge-list { list-style: none; margin: 6px 0 0; padding: 0; font-size: 13px; }
.mem-merge-list li { padding: 4px 0; border-top: 1px solid var(--line-200, #e7e9ee); }
.mem-merge-list li:first-child { border-top: 0; }
.mem-merge-list em { color: var(--ink-400, #5f6874); font-style: normal; }
.mem-issue-bad { display: block; padding: 10px 12px; border-radius: 10px;
                 border: 1px solid #b03535; color: #8c2626; font-size: 13px; }
.mem-issue-bad p { margin: 6px 0 0; }

/* ── Timeline ────────────────────────────────────────────────────────── */
.mem-tl { list-style: none; margin: 0; padding: 0; max-height: 320px; overflow-y: auto; }
.mem-tl li { display: grid; grid-template-columns: 11rem 1fr auto; gap: 10px; align-items: baseline;
             padding: 7px 0; border-top: 1px solid var(--line-200, #e7e9ee); font-size: 13px; }
.mem-tl li:first-child { border-top: 0; }
.mem-tl-when { color: var(--ink-400, #5f6874); font-size: 12px; }
.mem-tl-what { color: var(--ink-800, #272c35); }
.mem-tl-who { color: var(--ink-400, #5f6874); font-size: 12px; white-space: nowrap; }
@media (max-width: 640px) {
  .mem-tl li { grid-template-columns: 1fr; gap: 2px; }
  .mem-tl-who { white-space: normal; }
}

@media (prefers-color-scheme: dark) {
  .mem-bar-track { background: rgba(255, 255, 255, 0.12); }
  .mem-bar-fill { background: rgba(255, 255, 255, 0.78); }
  .mem-issue { border-top-color: rgba(255, 255, 255, 0.12); }
  .mem-consent { border-top-color: rgba(255, 255, 255, 0.12); }
  .mem-seg { border-color: rgba(255, 255, 255, 0.12); }
  .mem-merge-opt, .mem-merge-list li, .mem-tl li { border-color: rgba(255, 255, 255, 0.12); border-top-color: rgba(255, 255, 255, 0.12); }
  .mem-bulk { background: rgba(255, 255, 255, 0.04); }
  .mem-issue-bad { color: #ff9f9a; border-color: #ff9f9a; }
}

/* Import drawer: ID shapes the sheet uses that no format declares */
.imp-shape { display: flex; gap: 10px; align-items: center; justify-content: space-between; flex-wrap: wrap; padding: 6px 0; font-size: 13px; }
.imp-shape > span:first-child { flex: 1 1 220px; min-width: 0; }
.imp-sug { display: block; margin-top: 3px; font-size: 12px; color: var(--ink-600, #4a5160); }
.imp-year { display: inline-flex; flex-direction: column; gap: 2px; font-size: 11px; color: var(--ink-400, #6b7280); }
.imp-year input { width: 8.5em; padding: 4px 6px; font: inherit; font-size: 13px; }
.imp-writeback { display: flex; gap: 10px; align-items: center; justify-content: space-between; flex-wrap: wrap; margin-bottom: 8px; }
.imp-cap { font-family: var(--font-mono, monospace); font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--ink-400, #6b7280); margin-bottom: 6px; }
.imp-applicants-n { font-size: 13px; }
.imp-last { margin-bottom: 0; }
.mem-dupes-sub { margin: 18px 0 8px; }
.mem-dupes-sub:first-child { margin-top: 0; }

/* ── Approvals (AdminApprovals) ─────────────────────────────────────────── */
.appr-filters { display: flex; flex-wrap: wrap; gap: 6px; margin: 12px 0 16px; }
.appr-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.appr-item { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 12px 16px;
  padding: 14px 16px; background: var(--cream-50); border: 1px solid var(--line-cool-soft); border-radius: var(--r-md); }
.appr-item.is-pending { border-left: 3px solid var(--ink-900); }
.appr-item.is-failed { border-left: 3px solid var(--coral); }
.appr-main { min-width: min(100%, 260px); flex: 1 1 260px; }
.appr-summary { font-weight: 600; line-height: 1.4; margin: 0; color: var(--ink-900); }
.appr-meta { font-size: 12px; color: var(--ink-500); margin-top: 4px; overflow-wrap: anywhere; }
.appr-reason { font-size: 13px; margin-top: 8px; color: var(--ink-700); }
.appr-reason.is-error { color: var(--ink-900); font-weight: 600; }
.appr-side { flex: none; }


/* ============================================================
   7y-2. VOLUNTEER REGISTRATION — the form (VolunteerRegisterPage)
   A progress rail beside numbered cards; one gold accent on the
   live choice and the submit. Layout lives here, not inline.
   ============================================================ */
.volf-hero { padding-top: 72px; }
.volf-wrap { max-width: 1040px; container-type: inline-size; }
.volf-eyebrow { color: var(--gold-500); }
.volf-title { font-size: clamp(40px, 6vw, 80px); margin: 10px 0 14px; line-height: 0.95; }
.volf-lede { font-size: 17px; color: var(--ink-500); line-height: 1.6; max-width: 600px; margin: 0; }
.volf-facts { list-style: none; display: flex; flex-wrap: wrap; gap: 10px; padding: 0; margin: 22px 0 0; }
.volf-facts li { display: flex; align-items: baseline; gap: 8px; padding: 9px 14px; border-radius: 999px;
  background: var(--cream-50); border: 1px solid var(--line-cool-soft); font-size: 13px; color: var(--ink-700); }
.volf-facts b { font-family: var(--font-display); color: var(--ink-900); }
.volf-layout { display: grid; grid-template-columns: 180px minmax(0, 1fr); gap: 32px; margin-top: 40px; align-items: start; }
.volf-rail { list-style: none; margin: 0; padding: 0; position: sticky; top: 96px; display: grid; gap: 4px; }
.volf-rail-step { display: flex; align-items: center; gap: 12px; padding: 8px 0; color: var(--ink-500); font-size: 14px; }
.volf-rail-dot { width: 30px; height: 30px; flex: none; border-radius: 50%; display: grid; place-items: center;
  font-family: var(--font-mono); font-size: 11px; border: 1.5px solid var(--line-cool); background: white; color: var(--ink-700); }
.volf-rail-step.is-done { color: var(--ink-900); font-weight: 600; }
.volf-rail-step.is-done .volf-rail-dot { background: var(--navy-900); border-color: var(--navy-900); color: var(--gold-400); }
.volf-form { display: grid; gap: 18px; min-width: 0; }
.volf-card { background: white; border: 1px solid rgba(12, 20, 50, 0.08); border-radius: var(--r-lg);
  padding: 26px 26px 28px; box-shadow: var(--shadow-sm); }
.volf-paused { margin-top: 40px; }
.volf-step-head { display: flex; align-items: flex-start; gap: 14px; margin-bottom: 18px; }
.volf-step-n { font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.14em; color: var(--ink-700);
  background: var(--cream-100); border-radius: 8px; padding: 6px 8px; flex: none; }
.volf-step-title { font-family: var(--font-display); font-weight: 800; font-size: clamp(20px, 2.4vw, 26px); line-height: 1.15; margin: 0; color: var(--ink-900); }
.volf-step-hint { font-size: 14px; color: var(--ink-500); line-height: 1.5; margin: 4px 0 0; }
.volf-options { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
.volf-option { display: flex; flex-direction: column; gap: 8px; text-align: left; font-family: inherit; cursor: pointer;
  padding: 18px; background: white; border: 1px solid rgba(12, 20, 50, 0.12); border-radius: 16px;
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease; }
.volf-option:hover { transform: translateY(-2px); border-color: rgba(12, 20, 50, 0.24); }
.volf-option:focus-visible, .vol-lane:focus-visible, .vol-chip:focus-visible { outline: 3px solid var(--navy-500); outline-offset: 2px; }
.volf-option.is-active { border-color: var(--gold-500); box-shadow: 0 0 0 3px rgba(245, 176, 38, 0.25); }
.volf-option-top { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.volf-option-name { font-family: var(--font-display); font-weight: 800; font-size: 18px; color: var(--ink-900); }
.volf-option.is-active .volf-option-name::after { content: " ✓"; color: var(--ink-900); }
.volf-option-tag { font-family: var(--font-mono); font-size: 10.5px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--ink-700); background: var(--cream-100); padding: 3px 8px; border-radius: 999px; }
.volf-option-line { font-size: 13px; color: var(--ink-500); line-height: 1.45; }
.volf-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
.volf-span { grid-column: 1 / -1; }
.volf-hint { font-size: 12px; color: var(--ink-500); }
.volf-courses { margin-top: 20px; }
.volf-sub { font-size: 13px; font-weight: 600; color: var(--ink-700); margin: 0 0 10px; }
.volf-chips { display: flex; flex-wrap: wrap; gap: 10px; }
.volf-inline-error { font-size: 13.5px; color: var(--ink-700); display: flex; align-items: center; gap: 10px; padding: 10px 0; }
.volf-consent { display: flex; gap: 12px; align-items: flex-start; cursor: pointer; padding: 14px 16px; border-radius: 12px;
  background: var(--cream-50); border: 1px solid rgba(12, 20, 50, 0.10); font-size: 13.5px; line-height: 1.5; color: var(--ink-700); }
.volf-consent.is-on { border-color: var(--navy-700); background: var(--cream-100); }
.volf-consent input { width: 19px; height: 19px; margin-top: 1px; flex: none; accent-color: var(--navy-700); }
.volf-error { color: #a3271a; font-size: 14px; font-weight: 600; margin: 0; }
.volf-submit { position: sticky; bottom: 12px; z-index: 2; display: flex; align-items: center; justify-content: space-between;
  gap: 16px; flex-wrap: wrap; padding: 14px 16px 14px 20px; border-radius: var(--r-lg); background: var(--navy-900); color: white;
  box-shadow: 0 18px 40px -20px rgba(12, 20, 50, 0.6); }
