.cur-sched > summary { cursor: pointer; font-weight: 700; }
.cur-sched-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; margin: 8px 0 10px; }
.cur-behind { margin: 0 0 18px; }

.admin-tab-count { display: inline-block; min-width: 18px; margin-left: 6px; padding: 0 6px; border-radius: 999px; background: var(--coral-700, #9a3412); color: #fff; font-size: 11px; font-weight: 700; line-height: 18px; text-align: center; }
.cur-subs { display: grid; gap: 10px; }
