.cur-staff-upload { justify-self: start; }
.cur-staff-subs { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.cur-staff-sub { display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: center; justify-content: space-between; }
.cur-staff-sub-note { flex-basis: 100%; margin: 0; opacity: .9; }

/* ── The companion (member dashboard) ── */
.comp { display: grid; gap: 14px; }
.comp-chip { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 13px; font-weight: 700; }
.comp-chip.is-on_track { background: #e3f4e8; color: #14532d; }
.comp-chip.is-watch { background: #fdf3d8; color: #6b4d00; }
.comp-chip.is-at_risk { background: #fde8e4; color: #8a2a12; }
