.comp-hist { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.comp-hist li { display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: baseline; }
.comp-hist-w { font-family: var(--font-mono); font-size: 12px; color: var(--ink-500); }
.comp-hist-s { flex-basis: 100%; font-size: 14px; }
.cur-answer.is-code { font-family: var(--font-mono); font-size: 13px; }
.cur-ed-markhint { grid-column: 1 / -1; margin: 0; }
.cur-mark-flag { margin: 0 0 6px; padding: 8px 10px; border-radius: 8px; background: #fde8e4; color: #8a2a12; font-weight: 600; }

/* ── Lesson text and in-lesson viewers ── */
.cur-text-h4 { font-size: 15px; margin: 12px 0 4px; }
.cur-text ol { padding-left: 22px; }
.cur-callout { margin: 10px 0; padding: 10px 14px; border-left: 4px solid var(--gold, #e0b23a); background: var(--surface-2, #faf6ec); border-radius: 0 8px 8px 0; }
.cur-rule { border: 0; border-top: 1px solid rgba(0,0,0,.12); margin: 14px 0; }
