.cur-embed, .cur-viewer.is-frame { position: relative; width: 100%; aspect-ratio: 16 / 9; margin: 10px 0; border-radius: 10px; overflow: hidden; background: #000; }
.cur-viewer.is-frame { aspect-ratio: 4 / 5; background: #fff; border: 1px solid rgba(0,0,0,.12); }
.cur-embed iframe, .cur-viewer iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.cur-viewer video, .cur-viewer img { width: 100%; max-height: 70vh; border-radius: 10px; display: block; margin: 8px 0; background: #000; object-fit: contain; }
.cur-viewer audio { width: 100%; margin: 8px 0; }
.cur-mat-row { display: flex; gap: 8px; align-items: stretch; }
.cur-mat-row .cur-mat { flex: 1; text-align: left; font: inherit; cursor: pointer; }
.cur-mat-open { align-self: center; font-size: 13px; white-space: nowrap; }
.cur-rte { display: grid; gap: 6px; }
.cur-rte-bar { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; padding: 4px; border: 1px solid var(--line-cool-soft, #d9dde5); border-radius: 8px; background: var(--cream-50, #fbf8f1); }
.cur-rte-btn { min-width: 36px; height: 36px; padding: 0 8px; border: 1px solid transparent; border-radius: 6px; background: transparent; font: 600 14px/1 inherit; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; color: var(--ink-900, #1a2233); }
.cur-rte-btn:hover:not(:disabled) { border-color: var(--line-cool, #c3c9d4); background: #fff; }
