.fee-train-sum { padding: 14px 18px; border-bottom: 1px solid var(--line); font-size: 13px; color: var(--ink-700); line-height: 1.55; }
.fee-train-bar { width: 120px; height: 6px; border-radius: 999px; background: rgba(12,20,50,.08); overflow: hidden; margin-top: 4px; }
.fee-train-bar span { display: block; height: 100%; background: #2f7a3f; }

/* Bundled courses on the curriculum import screen */
