/* Access & roles */
.access-warn { margin: 0 0 12px; padding: 10px 14px; border-radius: 10px; background: #fff4e5; color: #7a3d00; font-size: 13.5px; }
.access-you { margin-left: 8px; font-size: 10px; }
.access-role { min-width: 210px; }
