.mbr-figs { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 10px 16px; margin: 0 0 10px; padding: 12px 0 0; border-top: 1px solid var(--pt-row); }
.mbr-figs dt { font-size: 12.5px; color: var(--pt-muted); }
.mbr-figs dd { margin: 0; font-weight: 700; font-variant-numeric: tabular-nums; }
.mbr-figs dd small { display: block; font-weight: 400; font-size: 12px; color: var(--pt-muted); }
.mbr-figs dd.is-bad { color: var(--pt-danger); }
.mbr-done { display: flex; align-items: center; gap: 8px; margin: 0; color: var(--pt-ok); font-weight: 500; }
.mbr-week { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }
.mbr-sat, .mbr-mentor { display: grid; gap: 4px; align-content: start; min-height: 140px; padding: 18px 20px; border-radius: var(--pt-r-card); text-align: left; font-family: var(--pt-font); cursor: pointer; }
