.mbr-sat span { color: rgba(255,255,255,.78); font-size: 14px; }
.mbr-sat .mbr-sat-go { margin-top: auto; color: #fff; font-weight: 600; display: inline-flex; gap: 6px; align-items: center; }
.mbr-mentor { background: var(--pt-card); border: 1px solid var(--pt-line); color: var(--pt-ink); }
.mbr-mentor small { color: var(--pt-muted); font-weight: 600; font-size: 12.5px; letter-spacing: .06em; text-transform: uppercase; }
.mbr-mentor b { font-size: 19px; }
.mbr-mentor span { color: var(--pt-ink-2); font-size: 14px; }
.mbr-prom { list-style: none; margin: 0; padding: 0; }
.mbr-prom li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 12px; padding: 10px 0; border-top: 1px solid var(--pt-row); }
.mbr-prom li:first-child { border-top: 0; }
.mbr-prom li > span:not(.rs-dots) { grid-column: 1; font-size: 13px; color: var(--pt-muted); }
.mbr-prom .rs-dots { grid-column: 2; grid-row: 1 / span 2; align-self: center; }
.mbr-notes, .rs-notes { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.mbr-notes p, .rs-notes p { margin: 2px 0; }
.mbr-notes small, .rs-notes small { color: var(--pt-muted); font-size: 12.5px; }
.mbr-woop { display: grid; gap: 8px; margin: 0 0 12px; }
.mbr-woop dt, .mbr-dl dt { font-size: 12.5px; color: var(--pt-muted); font-weight: 600; }
.mbr-woop dd, .mbr-dl dd { margin: 0; }
.mbr-dl { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px 20px; margin: 0 0 14px; }
.mbr-seg { display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; }
.mbr-seg span { height: 8px; border-radius: 4px; background: var(--pt-row); }
.mbr-seg span.is-on { background: var(--pt-ok); }
.mbr-likert { border: 0; margin: 0 0 14px; padding: 0; }
.mbr-likert legend { font-weight: 600; margin-bottom: 6px; }
.mbr-likert { display: flex; flex-wrap: wrap; gap: 6px; }
.mbr-likert label { position: relative; }
.mbr-likert input { position: absolute; opacity: 0; inset: 0; }
.mbr-likert span { display: inline-flex; align-items: center; min-height: var(--pt-hit); padding: 0 12px; border: 1px solid var(--pt-line); border-radius: var(--pt-r-ctl); font-size: 14px; cursor: pointer; }
.mbr-likert input:checked + span { background: var(--pt-ink); color: #fff; border-color: var(--pt-ink); }
.mbr-likert input:focus-visible + span { outline: 2px solid var(--pt-accent); outline-offset: 2px; }
.mbr-index { list-style: none; margin: 0; padding: 0; }
.mbr-index li { display: grid; grid-template-columns: 150px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 8px 0; border-top: 1px solid var(--pt-row); }
