.mbr-bar.is-self > span { background: var(--pt-accent); }
.mbr-bar b { position: absolute; right: 8px; top: 0; font: 700 12px/18px var(--pt-font); color: var(--pt-ink); }
.mbr-line { margin: 4px 0; }
.mbr-trend { list-style: none; margin: 0; padding: 0; display: flex; gap: 18px; align-items: flex-end; height: 140px; }
.mbr-trend li { display: grid; justify-items: center; gap: 4px; height: 100%; align-content: end; width: 64px; }
.mbr-trend li span { width: 36px; border-radius: 8px 8px 0 0; background: var(--pt-ink); }
.mbr-trend small { color: var(--pt-muted); font-size: 12px; }
.mbr-slider { display: grid; grid-template-columns: minmax(0, 1fr) 160px 28px; align-items: center; gap: 12px; padding: 8px 0; border-top: 1px solid var(--pt-row); }
