}

/* ── Grow › School results ─────────────────────────────────────────────── */
.rs { display: grid; gap: 16px; }
.rs-due { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; border-radius: var(--pt-r-card); background: var(--pt-warn-bg); color: var(--pt-warn); font-size: 14px; }
.rs-due.is-late { background: var(--pt-danger-bg); color: var(--pt-danger); }
.rs-due b { color: var(--pt-ink); }
.rs-steps { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.rs-steps li { display: grid; gap: 6px; font: 600 13px var(--pt-font); color: var(--pt-muted); }
.rs-steps-bar { height: 6px; border-radius: 3px; background: #dcd9d0; }
.rs-steps li.is-done .rs-steps-bar { background: var(--pt-ok); }
.rs-steps li.is-done { color: var(--pt-ok); }
.rs-steps li.is-on .rs-steps-bar { background: var(--pt-ink); }
.rs-steps li.is-on { color: var(--pt-ink); }
.rs-pick { display: flex; flex-wrap: wrap; gap: 8px; margin: 4px 0 8px; }
.rs-progress { height: 8px; border-radius: 4px; background: var(--pt-row); overflow: hidden; margin-top: 10px; }
.rs-progress span { display: block; height: 100%; background: var(--pt-ink); transition: width .2s; }
.rs-table { display: grid; margin-bottom: 10px; }
.rs-tr { display: grid; grid-template-columns: minmax(0, 2.4fr) 92px 72px 72px 44px; gap: 8px; align-items: center; padding: 6px 0; border-top: 1px solid var(--pt-row); }
.rs-th { border-top: 0; font: 600 12.5px var(--pt-font); color: var(--pt-muted); }
.rs-tr.is-low input { background: #fff6dd; border-color: #ecd393; }
.rs-tr.is-bad input { border-color: var(--pt-danger); background: var(--pt-danger-bg); }
.rs-num { font-variant-numeric: tabular-nums; font-weight: 600; text-align: right; }
.rs-num.is-up { color: var(--pt-ok); }
.rs-num.is-down { color: var(--pt-danger); }
.rs-swatch { display: inline-block; width: 12px; height: 12px; border-radius: 3px; background: #fff6dd; border: 1px solid #ecd393; }
.rs-ai { padding: 14px 16px; border-radius: var(--pt-r-card); background: var(--pt-ai); border: 1px solid var(--pt-ai-line); }
.rs-ai-tag { display: inline-flex; align-items: center; gap: 6px; font: 600 12.5px var(--pt-font); color: var(--pt-warn); }
.rs-ai p { margin: 6px 0 0; }
.rs-ai ul { margin: 6px 0 0; padding-left: 18px; font-size: 14px; color: var(--pt-ink-2); }
.rs-returned { display: flex; gap: 12px; padding: 14px 16px; border-radius: var(--pt-r-card); background: var(--pt-info-bg); color: var(--pt-info); }
.rs-returned b { color: var(--pt-ink); }
.rs-returned p { margin: 4px 0; color: var(--pt-ink); }
.rs-target { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.rs-target > span { font: 600 13.5px var(--pt-font); margin-right: 4px; }
.rs-target > b { min-width: 34px; text-align: center; font: 700 20px var(--pt-font); font-variant-numeric: tabular-nums; }
.rs-target > small { flex-basis: 100%; color: var(--pt-muted); font-size: 12.5px; }
.rs-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 0 16px; }
.rs-row .rs-target { margin-bottom: 0; }
.rs-add { max-width: 360px; }
.rs-recips { list-style: none; margin: 0 0 12px; padding: 0; display: grid; gap: 10px; }
.rs-recips li { display: flex; gap: 10px; align-items: flex-start; }
.rs-recips li > i { font-size: 20px; color: var(--pt-ok); margin-top: 2px; }
.rs-recips small { display: block; color: var(--pt-muted); font-size: 13px; }
.rs-switch, .rs-commit { display: flex; gap: 10px; align-items: flex-start; cursor: pointer; }
.rs-switch input, .rs-commit input { width: 20px; height: 20px; margin-top: 2px; accent-color: var(--pt-ink); flex: none; }
.rs-commit { padding: 12px 14px; border-radius: var(--pt-r-ctl); background: var(--pt-row); font-weight: 600; }
.rs-where { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }
.rs-where li { position: relative; padding-left: 26px; }
.rs-where li::before { content: ""; position: absolute; left: 4px; top: 5px; width: 12px; height: 12px; border-radius: 50%; border: 2px solid #cfcabd; background: var(--pt-card); }
.rs-where li.is-done::before { background: var(--pt-ok); border-color: var(--pt-ok); }
.rs-where li.is-on::before { border-color: var(--pt-ink); }
.rs-where li.is-off { color: var(--pt-muted); }
.rs-where small { display: block; color: var(--pt-muted); font-size: 13px; }
.rs-ticks { list-style: none; margin: 0; padding: 0; }
.rs-ticks li { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 12px; align-items: center; padding: 10px 0; border-top: 1px solid var(--pt-row); }
.rs-ticks li:first-child { border-top: 0; }
.rs-ticks-t small { display: block; color: var(--pt-muted); font-size: 13px; }
.rs-ticks-a { display: flex; gap: 4px; align-items: center; }
.rs-dots { display: inline-flex; gap: 4px; }
.rs-dots span { width: 12px; height: 12px; border-radius: 50%; background: #dcd9d0; }
.rs-dots span.is-on { background: var(--pt-ok); }
.rs-rem { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; font-size: 14px; }
.rs-rem li { display: flex; gap: 8px; align-items: baseline; }
.rs-hist summary { display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: baseline; min-height: var(--pt-hit); cursor: pointer; }
.rs-hist summary small { color: var(--pt-muted); font-size: 13px; }
.rs-hist ol { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 6px; font-size: 14px; }
.rs-hist li { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 10px; }
.rs-hist time { color: var(--pt-muted); font-size: 12.5px; }
.rs-past { list-style: none; margin: 0; padding: 0; }
.rs-past li + li { border-top: 1px solid var(--pt-row); }
@media (max-width: 759px) {
  .rs-tr { grid-template-columns: minmax(0, 1fr) 76px 44px; }
  .rs-tr > span:nth-child(3), .rs-tr > span:nth-child(4) { display: none; }
  .rs-ticks li { grid-template-columns: minmax(0, 1fr) auto; }
  .rs-ticks .rs-ticks-a { grid-column: 1 / -1; justify-content: flex-end; }
}
.mbr-today, .mbr-mentor-page { display: grid; gap: 16px; }
/* The dashboard's own cards, hosted inside a portal screen, take the portal's card shape. */
.pt-app .pt-body .dash-card { margin: 0; border-radius: var(--pt-r-card); border: 1px solid var(--pt-line); box-shadow: none; background: var(--pt-card); }
@media (min-width: 760px) { .pt-app { background: linear-gradient(to right, var(--pt-card) 248px, var(--pt-page) 248px); } }

/* Member portal: mood, mentor, chat */
.mbr-moods { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.mbr-mood { display: grid; justify-items: center; gap: 6px; min-height: 84px; padding: 12px 8px; border: 1px solid var(--pt-line); border-radius: var(--pt-r-ctl); background: var(--pt-card); color: var(--pt-ink); font: 600 14px var(--pt-font); cursor: pointer; }
