.mbr-mhead { display: flex; align-items: center; gap: 12px; }
.mbr-mhead b { display: block; font-size: 17px; }
.mbr-mhead small { display: block; color: var(--pt-muted); font-size: 13px; }
.pt-seg .pt-badge { margin-left: 6px; }
.mbr-chat { padding: 0; overflow: hidden; }
.mbr-thread { list-style: none; margin: 0; padding: 18px 20px; display: flex; flex-direction: column; gap: 10px; max-height: 56vh; min-height: 200px; overflow-y: auto; }
