.mbr-thread li.is-mine small { color: rgba(255,255,255,.72); }
.mbr-thread .mbr-about { margin: 0 0 4px; font-weight: 600; }
.mbr-thread-empty { color: var(--pt-muted); text-align: center; }
.mbr-thread-empty:not(#_):not(#_) { max-width: none; align-self: stretch; background: none; padding: 30px 10px; }
.mbr-thread-end:not(#_):not(#_) { padding: 0; background: none; }
.mbr-compose { display: flex; gap: 8px; align-items: flex-end; padding: 12px 16px; border-top: 1px solid var(--pt-line); }
.mbr-compose textarea { flex: 1; min-height: var(--pt-hit); max-height: 160px; padding: 10px 12px; border: 1px solid var(--pt-line); border-radius: var(--pt-r-ctl); font: 400 16px var(--pt-font); color: var(--pt-ink); resize: vertical; }
.mbr-compose textarea:focus-visible { outline: 0; border-color: var(--pt-ink); box-shadow: 0 0 0 3px rgba(245,176,38,.45); }
.mbr-chat .pt-hint { padding: 0 16px 12px; }
.mbr-crisis { display: flex; gap: 8px; margin: 0; padding: 12px 16px; background: var(--pt-danger-bg); color: var(--pt-danger); font-weight: 600; }
@media (max-width: 759px) { .mbr-compose .pt-btn span { display: none; } .mbr-thread li { max-width: 88%; } }

/* The dashboard's own panels (curriculum, money, records, requests…) hosted in
   a portal screen: the portal's card, button and field, one look. Their own
   section headings repeat the page title, so they go. */
.ngg-anchor-narrow { max-width: 860px; }
