.pt-app .pt-body .dash-card-h-sm { font: 600 16px/1.3 var(--pt-font); margin: 0; letter-spacing: 0; }
.pt-app .pt-body .btn { min-height: var(--pt-hit); padding: 0 16px; border-radius: var(--pt-r-ctl); font: 600 14.5px var(--pt-font); box-shadow: none; text-transform: none; letter-spacing: 0; }
