.pt-app .pt-body .btn-ghost { background: var(--pt-card); border: 1px solid var(--pt-line); color: var(--pt-ink); }
.pt-app .pt-body .admin-input { min-height: var(--pt-hit); border: 1px solid var(--pt-line); border-radius: var(--pt-r-ctl); font: 400 16px var(--pt-font); padding: 10px 12px; }
.pt-app .pt-body .eyebrow, .pt-app .pt-body .mono { font-family: var(--pt-mono); }
.pt-app .pt-body .dash-spinner { margin: 30px auto; }

