.mtr-items { margin: 0; padding-left: 20px; display: flex; flex-direction: column; gap: 10px; }
.mtr-items p { margin: 2px 0 0; }
.mtr-decide { margin-top: 14px; display: flex; flex-direction: column; gap: 8px; }
.mtr-decide label { font-weight: 700; font-size: 14px; }
.mtr-decide textarea { min-height: 72px; padding: 10px 12px; border-radius: 11px; border: 1px solid rgba(255,255,255,.18); background: rgba(255,255,255,.07); color: #eef2fb; font: inherit; font-size: 15px; resize: vertical; }
.mtr-decide-acts { display: flex; gap: 8px; flex-wrap: wrap; }
.mtr-btn { min-height: 44px; padding: 0 16px; border-radius: 11px; border: 1px solid rgba(255,255,255,.22); background: transparent; color: #eef2fb; font: inherit; font-weight: 700; cursor: pointer; }
.mtr-btn--gold { background: #ffce54; border-color: #ffce54; color: #2b2100; }
.mtr-btn:disabled { opacity: .6; cursor: default; }
.mtr-msg { margin: 10px 0 0; color: #b9f0c6; font-weight: 600; }
.mtr-notes ul { margin: 0; padding-left: 18px; font-size: 14px; }
@media (max-width: 520px) { .mtr-kpis { grid-template-columns: 1fr 1fr; } }

/* The member's managed details in Edit profile: shown, not editable. */
.dash-managed { margin: 4px 0 14px; padding: 12px 14px; border-radius: 12px; background: #f6f1e6; }
.dash-managed p { margin: 0 0 6px; display: flex; gap: 10px; font-size: 14px; }
.dash-managed p span { min-width: 64px; color: #5b6478; }
.dash-managed-note { color: #5b6478; }
.dash-managed-note:not(#_):not(#_) { font-size: 13px; margin: 4px 0 0; }
.dash-link { border: 0; background: none; padding: 0; font: inherit; color: #7d5a00; font-weight: 650; text-decoration: underline; cursor: pointer; }

/* Mentor Portal › Report a concern (MentorConcernSheet). */
.mtr-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.mtr-concern-btn { border-color: rgba(255,180,168,.55); color: #ffd3cb; }
.mtr-sheet-wrap { position: fixed; inset: 0; z-index: 80; background: rgba(5,10,25,.6); display: flex; align-items: flex-end; justify-content: center; padding: 16px; }
@media (min-width: 640px) { .mtr-sheet-wrap { align-items: center; } }
.mtr-sheet { width: 100%; max-width: 560px; max-height: calc(100vh - 32px); overflow: auto; background: #1d2a4a; color: #eef2fb; border: 1px solid rgba(255,255,255,.16); border-radius: 16px; padding: 18px 20px; }
.mtr-sheet-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.mtr-sheet-head h2 { margin: 0; font-size: 20px; font-weight: 800; }
.mtr-x { width: 44px; height: 44px; border: 0; border-radius: 10px; background: transparent; color: #cdd6ea; font-size: 18px; cursor: pointer; }
.mtr-danger { margin: 8px 0 14px; padding: 10px 12px; border-radius: 10px; background: rgba(255,120,100,.14); color: #ffd3cb; font-size: 14px; }
.mtr-cn-form { display: flex; flex-direction: column; gap: 8px; }
.mtr-cn-form label, .mtr-cn-form legend { font-weight: 700; font-size: 14px; padding: 0; }
.mtr-cn-form fieldset { border: 0; margin: 6px 0; padding: 0; }
.mtr-cn-form select, .mtr-cn-form textarea { min-height: 44px; padding: 10px 12px; border-radius: 11px; border: 1px solid rgba(255,255,255,.18); background: #24335a; color: #eef2fb; font: inherit; font-size: 15px; }
.mtr-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.mtr-chip { min-height: 40px; padding: 0 12px; border-radius: 999px; border: 1px solid rgba(255,255,255,.22); background: transparent; color: #eef2fb; font: inherit; font-size: 13.5px; cursor: pointer; }
.mtr-chip.is-on { background: rgba(255,206,84,.18); border-color: #ffce54; color: #ffce54; font-weight: 700; }
.mtr-err { margin: 4px 0; color: #ffb4a8; font-size: 14px; }
.mtr-sent p { margin: 0 0 8px; }

/* ── Mentor Portal · cover: opening a record that is not my mentee's ────── */
.mtr-cover { display: grid; gap: 10px; padding: 16px; margin: 0 0 16px; border-radius: 14px; background: rgba(255,255,255,.06); border: 1px solid rgba(255,206,84,.45); }
.mtr-cover-h { margin: 0; font-size: 16px; font-weight: 800; color: #fff; }
.mtr-cover-p { margin: 0; font-size: 14px; line-height: 1.55; color: rgba(230,238,255,.82); }
.mtr-cover-l { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: rgba(230,238,255,.72); }
.mtr-cover-in { width: 100%; box-sizing: border-box; padding: 11px 13px; border-radius: 11px; font: inherit; font-size: 16px; min-height: 44px; resize: vertical;
  background: rgba(255,255,255,.07); border: 1px solid rgba(255,255,255,.2); color: #eef2fb; }
.mtr-cover-go { justify-self: start; min-height: 44px; padding: 0 20px; border-radius: 11px; border: 0; background: #ffce54; color: #2b2100; font-weight: 800; cursor: pointer; }
.mtr-cover-go:disabled { opacity: .55; cursor: not-allowed; }
.mtr-cover-go:focus-visible, .mtr-cover-in:focus-visible, .mtr-cover-who:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
.mtr-cover-note { margin: 0 0 14px; padding: 10px 14px; border-radius: 12px; font-size: 13.5px; background: rgba(255,206,84,.12); border: 1px solid rgba(255,206,84,.4); color: #ffe6a8; }
.mtr-cover-withheld { margin: 0 0 6px; font-size: 13.5px; line-height: 1.5; color: #ffd2b0; font-style: italic; }
.mtr-att-h { font-size: 13px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: rgba(230,238,255,.72); margin: 0 0 10px; }
.mtr-cover-list { list-style: none; margin: 0 0 24px; padding: 0; display: grid; gap: 8px; }
.mtr-cover-row { display: grid; gap: 4px; padding: 12px 14px; border-radius: 14px; background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.12); }
.mtr-cover-who { justify-self: start; background: none; border: 0; padding: 0; font: inherit; font-weight: 800; font-size: 15px; color: #fff; cursor: pointer; text-decoration: underline; text-underline-offset: 3px; }
.mtr-cover-meta { font-size: 12px; color: rgba(230,238,255,.72); font-variant-numeric: tabular-nums; }
.mtr-cover-why { font-size: 14px; color: #eef2fb; }
/* ── Member accounts ─────────────────────────────────────────────────────────
   Five signals about signing in. Each opens to the members it counts, because
   "14 locked out" with no names is an accusation rather than a working list. */
.acct-totals { font-size: 11.5px; color: var(--ink-500); margin-right: 4px; }
.acct-signals { display: flex; flex-direction: column; gap: 10px; }
.acct-signal { padding: 0; overflow: hidden; }
.acct-signal-head {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 14px;
  align-items: center;
  width: 100%;
  min-height: 44px;
  padding: 14px 16px;
  background: none;
  border: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.acct-signal-head:hover { background: rgba(12, 20, 50, 0.03); }
.acct-signal-head:focus-visible { outline: 2px solid var(--gold-500, #f5b026); outline-offset: -2px; }
.acct-signal-n {
  font-size: 22px;
  font-variant-numeric: tabular-nums;
  min-width: 2.2ch;
  text-align: right;
}
.acct-signal-text { display: flex; flex-direction: column; gap: 2px; text-align: left; }
.acct-signal-why { font-size: 12.5px; color: var(--ink-500); line-height: 1.4; }
.acct-signal-caret { font-size: 18px; color: var(--ink-500); line-height: 1; }

.acct-list { border-top: 1px solid var(--line, #e8ebf2); }
.acct-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 9px 16px;
  font-size: 13.5px;
  border-bottom: 1px solid var(--line, #e8ebf2);
}
.acct-row:last-child { border-bottom: none; }
/* .admin-panel centres its text; a list of people must not inherit that. */
.acct-row-name { display: flex; flex-direction: column; gap: 1px; justify-self: start; text-align: left; }
.acct-row-meta { font-size: 11px; color: var(--ink-500); }
.acct-more { padding: 10px 16px; font-size: 12.5px; color: var(--ink-500); text-align: left; }

/* The panel sits in a column beside the sidebar, so its own width is the
   question — not the window's (CLAUDE.md §11). */
.acct-signal { container: acctsig / inline-size; }
@container acctsig (max-width: 420px) {
  .acct-signal-why { display: none; }
  .acct-row { grid-template-columns: 1fr; }
  .acct-row > :last-child { justify-self: start; }
}

