.asd-check { display: flex; gap: 8px; align-items: center; font-size: 13.5px; color: var(--asd-ink-2); }
.asd-foot { display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; padding-top: 4px; }
.asd-sum { margin: 0; font-size: 14px; color: var(--asd-ink-2); }
.asd-brief { border: 1px solid var(--asd-line); border-radius: var(--asd-r); padding: 10px 14px; font-size: 13.5px; }
.asd-brief summary { cursor: pointer; font-weight: 600; }
.asd-brief p { white-space: pre-wrap; margin: 10px 0 0; color: var(--asd-ink-2); }
.asd-subs { list-style: none; margin: 0; padding: 0; border: 1px solid var(--asd-line); border-radius: var(--asd-r); overflow: hidden; }
.asd-sub { border-top: 1px solid var(--asd-line); }
.asd-sub:first-child { border-top: 0; }
.asd-subhead { width: 100%; display: flex; align-items: center; gap: 8px; padding: 12px 14px; background: var(--asd-bg); border: 0; font: inherit; color: var(--asd-ink); text-align: left; cursor: pointer; }
.asd-subhead:hover, .asd-sub.is-open .asd-subhead { background: var(--asd-s1); }
.asd-markbox { padding: 4px 14px 16px; display: flex; flex-direction: column; gap: 12px; background: var(--asd-s1); }
.asd-work { white-space: pre-wrap; background: var(--asd-bg); border: 1px solid var(--asd-line); border-radius: var(--asd-r-sm); padding: 12px; font-size: 14px; line-height: 1.55; max-height: 320px; overflow: auto; }
.asd-missing h3 { margin: 6px 0 8px; font-size: 14px; display: flex; gap: 8px; align-items: center; }
.asd-missing ul { margin: 0; padding: 0; list-style: none; display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 6px 14px; font-size: 13.5px; }

/* ── The member's hand-in panel (AsdHandIn) — the member portal's own light ink ── */
.ahi-veil { position: fixed; inset: 0; background: rgba(11, 11, 12, .45); display: flex; align-items: flex-end; justify-content: center; z-index: 900; padding: 0; }
.ahi { --ahi-ink: #0b0b0c; --ahi-ink-2: #45454c; --ahi-ink-3: #5f5f66; --ahi-line: #e6e4de; --ahi-s1: #f7f6f2; --ahi-ok: #1d6b30; --ahi-ok-bg: #e7f3ea; --ahi-warn: #7a5600; --ahi-warn-bg: #fbf1d9; --ahi-bad: #a8231b; --ahi-bad-bg: #fbe9e7;
  background: #fff; color: var(--ahi-ink); width: min(640px, 100%); max-height: 92vh; display: flex; flex-direction: column; border-radius: 18px 18px 0 0; box-shadow: 0 -8px 40px rgba(0, 0, 0, .18); outline: none; container-type: inline-size; text-align: left; }
@media (min-width: 760px) { .ahi-veil { align-items: center; padding: 24px; } .ahi { border-radius: 18px; } }
.ahi-head { position: relative; padding: 18px 56px 12px 20px; border-bottom: 1px solid var(--ahi-line); display: flex; flex-direction: column; gap: 6px; }
.ahi-kicker { font-size: 12px; font-weight: 650; color: var(--ahi-ink-3); letter-spacing: .02em; }
.ahi-head h2 { margin: 0; font-size: 19px; line-height: 1.25; letter-spacing: -.01em; }
.ahi-state { align-self: flex-start; font-size: 12px; font-weight: 650; padding: 3px 10px; border-radius: 999px; background: var(--ahi-s1); color: var(--ahi-ink-2); }
.ahi-state.is-todo { background: var(--ahi-warn-bg); color: var(--ahi-warn); }
.ahi-state.is-late, .ahi-state.is-returned { background: var(--ahi-bad-bg); color: var(--ahi-bad); }
.ahi-state.is-submitted, .ahi-state.is-marked { background: var(--ahi-ok-bg); color: var(--ahi-ok); }
.ahi-x { position: absolute; top: 12px; right: 12px; width: 40px; height: 40px; border-radius: 50%; border: 0; background: var(--ahi-s1); color: var(--ahi-ink); font-size: 18px; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; }
.ahi-body { padding: 16px 20px; overflow: auto; display: flex; flex-direction: column; gap: 16px; }
.ahi-sec h3 { margin: 0 0 4px; font-size: 14.5px; }
.ahi-brief { margin: 0; white-space: pre-wrap; font-size: 14.5px; line-height: 1.55; color: var(--ahi-ink-2); }
.ahi-hint { margin: 0; font-size: 13px; color: var(--ahi-ink-3); }
.ahi-note { margin: 0; padding: 12px 14px; border-radius: 12px; background: var(--ahi-s1); font-size: 14px; }
.ahi-fb { padding: 12px 14px; border-radius: 12px; background: var(--ahi-ok-bg); }
.ahi-fb.is-ret { background: var(--ahi-warn-bg); }
.ahi-fb b { font-size: 14px; } .ahi-fb p { margin: 4px 0 0; font-size: 14px; white-space: pre-wrap; }
.ahi-link { display: inline-flex; gap: 6px; align-items: center; margin-top: 8px; font-size: 14px; font-weight: 600; color: var(--ahi-ink); }
.ahi-steps { border: 1px solid var(--ahi-line); border-radius: 14px; padding: 10px 12px 8px; margin: 0; display: flex; flex-direction: column; gap: 4px; }
.ahi-steps legend { font-size: 13.5px; font-weight: 650; padding: 0 4px; }
.ahi-step { display: flex; gap: 10px; align-items: flex-start; padding: 8px 6px; border-radius: 10px; font-size: 14.5px; cursor: pointer; min-height: 44px; box-sizing: border-box; }
.ahi-step input { width: 20px; height: 20px; margin-top: 1px; flex: none; accent-color: var(--ahi-ok); }
.ahi-step.is-on span { color: var(--ahi-ink-3); text-decoration: line-through; }
.ahi-count { margin: 2px 6px 4px; font-size: 12.5px; color: var(--ahi-ink-3); }
.ahi-field { display: flex; flex-direction: column; gap: 6px; font-size: 13.5px; font-weight: 650; }
.ahi-field em { font-style: normal; font-weight: 450; color: var(--ahi-ink-3); }
.ahi-input { min-height: 46px; padding: 0 14px; border: 1px solid #d4d2cb; border-radius: 12px; font: inherit; font-size: 15px; font-weight: 450; color: var(--ahi-ink); background: #fff; width: 100%; box-sizing: border-box; }
.ahi-input.is-area { padding: 12px 14px; line-height: 1.5; resize: vertical; }
.ahi-input:focus-visible, .ahi-btn:focus-visible, .ahi-x:focus-visible, .ahi-step:focus-within { outline: 2px solid var(--ahi-ink); outline-offset: 2px; }
.ahi-lk { font-size: 13px; font-weight: 550; color: var(--ahi-ink-3); display: inline-flex; gap: 6px; align-items: center; }
.ahi-lk.is-ok { color: var(--ahi-ok); }
.ahi-files { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.ahi-files li { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; background: var(--ahi-s1); font-weight: 500; font-size: 14px; }
.ahi-files a { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--ahi-ink); }
.ahi-rm { width: 36px; height: 36px; border: 0; background: none; color: var(--ahi-bad); border-radius: 8px; cursor: pointer; font-size: 16px; }
.ahi-pick, .ahi-inline { display: flex; flex-wrap: wrap; gap: 8px; }
.ahi-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 44px; padding: 0 16px; border-radius: 999px; border: 1px solid #d4d2cb; background: #fff; color: var(--ahi-ink); font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; }
.ahi-btn.is-dark { background: var(--ahi-ink); border-color: var(--ahi-ink); color: #fff; }
.ahi-btn:disabled { opacity: .5; cursor: not-allowed; }
.ahi-up { display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 500; color: var(--ahi-ink-2); }
.ahi-bar { height: 6px; border-radius: 3px; background: var(--ahi-line); overflow: hidden; }
.ahi-bar span { display: block; height: 100%; background: var(--ahi-ok); transition: width .2s; }
.ahi-rec { display: flex; flex-direction: column; gap: 10px; padding: 12px; border-radius: 12px; background: var(--ahi-s1); }
.ahi-rec b { font-size: 14px; }
.ahi-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--ahi-bad); display: inline-block; animation: ahi-pulse 1.2s ease-in-out infinite; }
@keyframes ahi-pulse { 50% { opacity: .3; } }
@media (prefers-reduced-motion: reduce) { .ahi-dot { animation: none; } .ahi-bar span { transition: none; } }
.ahi-media { width: 100%; max-height: 260px; border-radius: 10px; }
.ahi-err { margin: 0; padding: 10px 12px; border-radius: 10px; background: var(--ahi-bad-bg); color: var(--ahi-bad); font-size: 14px; font-weight: 550; }
.ahi-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 20px calc(12px + env(safe-area-inset-bottom)); border-top: 1px solid var(--ahi-line); }
.ahi-need { font-size: 13.5px; color: var(--ahi-ink-3); font-weight: 550; }
.ahi-btn.is-go { min-width: 140px; }
.asd-kinds { display: flex; flex-wrap: wrap; gap: 6px; }
.asd-kind { display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 0 12px; border-radius: 999px; border: 1px solid var(--asd-line-2); background: var(--asd-bg); color: var(--asd-ink-2); font: inherit; font-size: 13px; font-weight: 550; cursor: pointer; }
.asd-kind.is-on { border-color: var(--asd-ink); color: var(--asd-ink); background: var(--asd-s1); }
.asd-kind:focus-visible { outline: 2px solid var(--asd-ink); outline-offset: 2px; }
.asd-media { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-start; }
.asd-thumb img { width: 140px; height: 140px; object-fit: cover; border-radius: var(--asd-r-sm); border: 1px solid var(--asd-line); display: block; }
.asd-player { width: min(100%, 420px); max-height: 260px; border-radius: var(--asd-r-sm); }
.asd-ticks { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; font-size: 13.5px; color: var(--asd-ink-3); }
.asd-ticks li.is-on { color: var(--asd-ok); }
.asd-golink { align-self: flex-start; }

/* ── Study helper on Learn (CurStudyHelper) ── */
.sth { --sth-ink: #0b0b0c; --sth-ink-3: #5f5f66; --sth-line: #e6e4de; --sth-s1: #f7f6f2;
  margin: 16px 0 8px; padding: 16px 18px; border: 1px solid var(--sth-line); border-radius: 16px; background: #fff; color: var(--sth-ink); display: flex; flex-direction: column; gap: 12px; text-align: left; }
.sth-head { display: flex; gap: 12px; align-items: flex-start; }
.sth-head > .ph { font-size: 22px; margin-top: 2px; }
.sth-head h3 { margin: 0; font-size: 16px; }
.sth-head p { margin: 2px 0 0; font-size: 13.5px; color: var(--sth-ink-3); }
.sth-form { display: flex; flex-direction: column; gap: 10px; }
.sth-field { display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 650; }
.sth-input { min-height: 44px; padding: 0 12px; border: 1px solid #d4d2cb; border-radius: 12px; font: inherit; font-size: 14.5px; font-weight: 450; background-color: #fff; color: var(--sth-ink); width: 100%; box-sizing: border-box; }
.sth-input.is-area { padding: 10px 12px; line-height: 1.5; resize: vertical; }
.sth-input:focus-visible, .sth-btn:focus-visible { outline: 2px solid var(--sth-ink); outline-offset: 2px; }
.sth-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.sth-left { font-size: 12.5px; color: var(--sth-ink-3); }
.sth-btn { min-height: 44px; min-width: 110px; padding: 0 18px; border-radius: 999px; border: 0; background: var(--sth-ink); color: #fff; font: inherit; font-size: 14px; font-weight: 650; cursor: pointer; }
.sth-btn:disabled { opacity: .5; cursor: not-allowed; }
.sth-ans { white-space: pre-wrap; padding: 12px 14px; border-radius: 12px; background: var(--sth-s1); font-size: 14.5px; line-height: 1.55; }
/* The thread. The helper used to be a form that replaced its own answer, so
   there was nothing to lay out; a conversation needs turns you can tell
   apart at a glance and a question box that stays put under them. */
.sth-thread { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; max-height: 52vh; overflow-y: auto; }
.sth-turn { display: grid; gap: 3px; }
.sth-who { font-size: 11.5px; font-weight: 600; letter-spacing: .02em; text-transform: uppercase; color: var(--sth-ink-3); }
.sth-bubble { margin: 0; white-space: pre-wrap; padding: 11px 13px; border-radius: 12px; font-size: 14.5px; line-height: 1.6; }
.sth-turn.is-me .sth-bubble { background: #eef1f8; color: var(--sth-ink); }
.sth-turn.is-ai .sth-bubble { background: var(--sth-s1); color: var(--sth-ink); border: 1px solid var(--sth-line); }
.sth-turn.is-care .sth-bubble { background: #fdf6e3; border-color: #e8c97a; }
.sth-bubble.is-wait { color: var(--sth-ink-3); font-style: italic; }
/* "Ask a question" is hard when you do not know what you do not understand. */
.sth-openers { display: grid; gap: 8px; }
.sth-opener { min-height: 44px; padding: 10px 14px; text-align: left; cursor: pointer; font: inherit; font-size: 14px;
  border: 1px dashed var(--sth-line); border-radius: 12px; background: transparent; color: var(--sth-ink); }
.sth-opener:hover { border-style: solid; background: var(--sth-s1); }
.sth-restart { min-height: 36px; padding: 0 12px; cursor: pointer; font: inherit; font-size: 13px;
  border: 0; background: none; color: var(--sth-ink-3); text-decoration: underline; }
.sth-ans.is-err { background: #fbe9e7; color: #a8231b; }
.sth-ans.is-care { background: #fbf1d9; color: #4a3500; }

/* ── The desk's face check (face-check.jsx) ── */
.gate-face-btn { margin-top: 10px; display: inline-flex; align-items: center; gap: 6px; }
.fc-veil { position: fixed; inset: 0; z-index: 950; background: rgba(8, 10, 14, .62); display: flex; align-items: center; justify-content: center; padding: 16px; }
.fc { --fc-ink: #0b0b0c; --fc-ink-3: #5f5f66; --fc-line: #e6e4de; --fc-s1: #f7f6f2;
  width: min(680px, 100%); max-height: 94vh; overflow: auto; background: #fff; color: var(--fc-ink); border-radius: 18px; box-shadow: 0 20px 60px rgba(0, 0, 0, .3); outline: none; text-align: left; display: flex; flex-direction: column; container-type: inline-size; }
.fc-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 18px; border-bottom: 1px solid var(--fc-line); }
.fc-head h2 { margin: 0; font-size: 17px; }
.fc-x { width: 40px; height: 40px; border-radius: 50%; border: 0; background: var(--fc-s1); color: var(--fc-ink); font-size: 18px; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; }
.fc-body { padding: 16px 18px; display: flex; flex-direction: column; gap: 12px; }
.fc-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
@container (max-width: 420px) { .fc-pair { grid-template-columns: 1fr; } }
.fc-fig { margin: 0; display: flex; flex-direction: column; gap: 6px; }
.fc-fig img, .fc-fig video, .fc-none { width: 100%; aspect-ratio: 3 / 4; object-fit: cover; border-radius: 12px; background: #1b1d22; display: block; }
.fc-fig video { transform: scaleX(-1); }
.fc-fig video.is-live { box-shadow: 0 0 0 3px #1d6b30; }
.fc-none { display: flex; align-items: center; justify-content: center; color: #e8e8ea; font-size: 14px; }
.fc-fig figcaption { font-size: 12.5px; color: var(--fc-ink-3); font-weight: 600; }
.fc-stage { margin: 0; display: flex; gap: 10px; align-items: center; font-size: 15px; font-weight: 600; }
.fc-spin { width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--fc-line); border-top-color: var(--fc-ink); animation: fc-spin .8s linear infinite; flex: none; }
@keyframes fc-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .fc-spin { animation: none; } }
.fc-out { padding: 12px 14px; border-radius: 12px; background: var(--fc-s1); display: flex; flex-direction: column; gap: 6px; }
.fc-out b { font-size: 16px; }
.fc-out p { margin: 0; font-size: 14px; }
.fc-out.is-match { background: #e7f3ea; color: #12471f; }
.fc-out.is-unsure, .fc-out.is-no_face, .fc-out.is-no_photo { background: #fbf1d9; color: #4a3500; }
.fc-out.is-no_match, .fc-out.is-not_live, .fc-out.is-bad { background: #fbe9e7; color: #7d1a13; }
.fc-scores { font-size: 12.5px; opacity: .9; }
.fc-note { margin: 0; font-size: 12.5px; color: var(--fc-ink-3); }
.fc-foot { display: flex; gap: 8px; justify-content: flex-end; flex-wrap: wrap; padding: 12px 18px; border-top: 1px solid var(--fc-line); }
.fc-btn { min-height: 44px; padding: 0 16px; border-radius: 999px; border: 1px solid #d4d2cb; background: #fff; color: var(--fc-ink); font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; }
.fc-btn.is-go { background: var(--fc-ink); border-color: var(--fc-ink); color: #fff; }
.fc-btn:focus-visible, .fc-x:focus-visible { outline: 2px solid var(--fc-ink); outline-offset: 2px; }

/* Member portal: the simple view (mp9-more.jsx simpleTiles / viewSwitch). */
.m9x-kid { padding: 20px; border-radius: 18px; background: #fff; border: 1px solid #e6e5e0; container-type: inline-size; }
.m9x-kid-h { margin: 0 0 14px; font-size: 20px; font-weight: 700; color: #0b0b0c; }
.m9x-kid-grid { margin: 0; padding: 0; list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
@container (min-width: 620px) { .m9x-kid-grid { grid-template-columns: repeat(4, 1fr); } }
.m9x-kid-tile { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; width: 100%; min-height: 104px; padding: 14px 10px; border: 1px solid #e8e5dd; border-radius: 16px; background: #fafaf8; color: #0b0b0c; font: 600 16px 'Geist', system-ui, sans-serif; text-align: center; cursor: pointer; }
.m9x-kid-tile:hover { background: #f4f4f2; }
.m9x-kid-tile:focus-visible { outline: 3px solid #0b0b0c; outline-offset: 2px; }
.m9x-kid-help { margin: 14px 0 0; }
.m9x-kid-link, .m9x-view-opt { font: inherit; cursor: pointer; }
.m9x-kid-link { min-height: 44px; padding: 0; border: 0; background: none; font-weight: 600; font-size: 15px; color: #0b0b0c; text-decoration: underline; }
.m9x-view { margin-top: 16px; padding: 20px; border-radius: 18px; background: #fff; border: 1px solid #e6e5e0; container-type: inline-size; }
.m9x-view-h { margin: 0 0 6px; font-size: 17px; font-weight: 700; color: #0b0b0c; }
.m9x-view-p { margin: 0 0 12px; font-size: 14px; line-height: 1.5; color: #4a4a50; }
.m9x-view-opts { display: grid; grid-template-columns: 1fr; gap: 8px; }
@container (min-width: 440px) { .m9x-view-opts { grid-template-columns: 1fr 1fr; } }
.m9x-view-opt { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; min-height: 64px; padding: 12px 14px; border: 1px solid #e8e5dd; border-radius: 14px; background: #fafaf8; color: #0b0b0c; text-align: left; }
.m9x-view-opt span { font-size: 13px; color: #4a4a50; }
