.scm-bar-top { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.scm-seg { display: inline-flex; flex-wrap: wrap; gap: 4px; padding: 4px; border-radius: 14px; background: #efeee9; }
.scm-seg > button { min-height: 40px; padding: 0 14px; border: 0; border-radius: 10px; background: none; color: #45454d; font: inherit; font-size: 14px; font-weight: 600; cursor: pointer; }
.scm-seg > button.is-on { background: #fff; color: #0b0b0c; box-shadow: 0 1px 2px rgba(0, 0, 0, .08); }
.scm-find { flex: 1 1 200px; display: flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 12px; border: 1px solid #d6d4cc; border-radius: 12px; background: #fff; }
.scm-find > i { color: #6b6b72; }
.scm-find > input { flex: 1; min-width: 0; border: 0; background: none; font: inherit; font-size: 15px; color: #0b0b0c; outline-offset: 4px; }
.scm-status { margin: 0; font-size: 13px; color: #5b5b62; }
.scm-now { padding: 12px 14px; border-radius: 16px; background: #fff8e6; border: 1px solid #f0d9a0; display: flex; flex-direction: column; gap: 6px; }
.scm-now > h3, .scm-term-h { margin: 0; font-size: 15px; font-weight: 600; color: #0b0b0c; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; }
.scm-term-h > small { font-size: 12.5px; font-weight: 400; color: #5b5b62; }
.scm-term { display: flex; flex-direction: column; gap: 6px; padding: 14px; border-radius: 16px; background: #fff; border: 1px solid #e8e5dd; }
.scm-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.scm-row { border-top: 1px solid #f0efea; }
.scm-row:first-child { border-top: 0; }
.scm-row-btn { width: 100%; display: grid; grid-template-columns: 44px minmax(0, 1fr) 96px auto 20px; align-items: center; gap: 10px; min-height: 56px; padding: 6px 0; border: 0; background: none; text-align: left; font: inherit; color: #0b0b0c; cursor: pointer; }
.scm-wk { height: 28px; display: grid; place-items: center; border-radius: 8px; background: #f4f4f2; font-family: "Geist Mono", ui-monospace, monospace; font-size: 12.5px; color: #45454d; }
.scm-row.is-now .scm-wk { background: #0b0b0c; color: #fff; }
.scm-t { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.scm-t > b { font-size: 15px; font-weight: 600; }
.scm-t > small { font-size: 12.5px; color: #5b5b62; }
.scm-bar { height: 6px; border-radius: 999px; background: #efeee9; overflow: hidden; }
.scm-bar > span { display: block; height: 100%; border-radius: 999px; background: #1d6b30; }
.scm-chip { height: 24px; padding: 0 9px; display: inline-flex; align-items: center; border-radius: 999px; font-size: 12px; font-weight: 600; white-space: nowrap; background: #f4f4f2; color: #45454d; }
.scm-chip.is-now { background: #0b0b0c; color: #fff; }
.scm-chip.is-behind { background: #fbeae5; color: #8a2a14; }
.scm-chip.is-done { background: #e9f6ec; color: #1d6b30; }
.scm-chip.is-open { background: #fff4d6; color: #6b4b00; }
.scm-lesson { display: flex; flex-direction: column; gap: 8px; padding: 4px 0 14px 54px; font-size: 14px; line-height: 1.5; color: #2b2b30; }
.scm-lesson ul { margin: 0; padding-left: 18px; }
.scm-lesson p { margin: 0; }
.scm-h4 { margin: 0; font-size: 13px; font-weight: 600; color: #45454d; }
.scm-path { font-size: 12.5px; color: #5b5b62; }
.scm-behind { padding: 8px 10px; border-radius: 10px; background: #fbeae5; color: #8a2a14; font-size: 13px; }
.scm-empty { margin: 0; font-size: 14px; color: #5b5b62; }
@container (max-width: 560px) {
  .scm-row-btn { grid-template-columns: 40px minmax(0, 1fr) auto 18px; }
  .scm-bar { display: none; }
  .scm-lesson { padding-left: 0; }
}

/* ── Growth report (GrowthReport): mentor profile and family portal ── */
.grw { container-type: inline-size; display: flex; flex-direction: column; gap: 12px; }
.grw-card { background: #fff; border: 1px solid #e8e5dd; border-radius: 18px; padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.grw-card > h3 { margin: 0; font-size: 15px; font-weight: 600; color: #0b0b0c; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; }
.grw-card > h3 > small { font-size: 12.5px; font-weight: 400; color: #5b5b62; }
.grw-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
@container (max-width: 640px) { .grw-grid { grid-template-columns: minmax(0, 1fr); } }
.grw-ins ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.grw-ins li { display: flex; gap: 10px; align-items: flex-start; font-size: 14px; line-height: 1.45; color: #2b2b30; }
.grw-ins li > i { flex: none; width: 28px; height: 28px; display: grid; place-items: center; border-radius: 8px; background: #f4f4f2; color: #45454d; font-size: 16px; }
.grw-ins li.is-up > i { background: #e9f6ec; color: #1d6b30; }
.grw-ins li.is-down > i { background: #fbeae5; color: #8a2a14; }
.grw-ins em { display: block; font-style: normal; font-size: 13px; color: #5b5b62; }
.grw-dots { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.grw-dots > li { width: 18px; height: 18px; border-radius: 50%; background: #efeee9; }
.grw-dots > li.is-here { background: #1d6b30; }
.grw-dots > li.is-away { background: #fff; box-shadow: inset 0 0 0 2px #b0361c; }
.grw-dots > li.is-pre { background: repeating-linear-gradient(45deg, #efeee9 0 3px, #fff 3px 6px); }
.grw-bars { list-style: none; margin: 0; padding: 0; display: flex; align-items: flex-end; gap: 8px; min-height: 96px; }
.grw-bars > li { display: flex; flex-direction: column; align-items: center; gap: 2px; flex: 1 1 0; min-width: 0; }
.grw-bars b { font-size: 12.5px; font-variant-numeric: tabular-nums; color: #0b0b0c; }
.grw-bars small { font-size: 11.5px; color: #5b5b62; white-space: nowrap; }
.grw-bar { width: 100%; max-width: 28px; border-radius: 6px 6px 2px 2px; background: #0b0b0c; }
.grw-bar.is-ev { background: #7a5600; }
.grw-chips { margin: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.grw-chip { height: 24px; padding: 0 9px; display: inline-flex; align-items: center; border-radius: 999px; font-size: 12px; font-weight: 600; }
.grw-chip.is-up, .grw-list > li.is-up { background: #e9f6ec; color: #1d6b30; }
.grw-chip.is-down, .grw-list > li.is-down { background: #fbeae5; color: #8a2a14; }
.grw-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.grw-list > li { padding: 4px 8px; border-radius: 8px; font-size: 13px; }
.grw-note { margin: 0; font-size: 13px; color: #45454d; line-height: 1.45; }
.grw-facts { margin: 0; display: flex; flex-direction: column; gap: 8px; }
.grw-facts > div { display: grid; grid-template-columns: 90px minmax(0, 1fr); gap: 8px; font-size: 14px; }
.grw-facts dt { color: #5b5b62; }
.grw-facts dd { margin: 0; color: #0b0b0c; }
.grw-msg { display: flex; gap: 10px; align-items: center; padding: 14px 16px; border-radius: 14px; background: #f4f4f2; font-size: 14px; color: #2b2b30; }
.grw-btn { min-height: 44px; padding: 0 16px; border-radius: 12px; border: 1px solid #d6d4cc; background: #fff; font: inherit; font-weight: 600; cursor: pointer; }
/* Mentor portal → Projects (Mp15Projects, domain/projects.php). The grw-card
   housing, with the countdown in the same three tones the member sees. */
.mpj { container-type: inline-size; display: flex; flex-direction: column; gap: 12px; }
.mpj-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.mpj-go { min-height: 44px; padding: 0 16px; border-radius: 12px; border: 0; background: #0b0b0c; color: #fff; font: inherit; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
.mpj-go:disabled { background: #8d8d93; cursor: not-allowed; }
/* Supervision write-up (Mp15SupNotes): the agreed points are a real fieldset, one input each. */
.mpj fieldset.mpj-f { border: 0; margin: 0; padding: 0; min-width: 0; gap: 6px; }
.mpj fieldset.mpj-f legend { padding: 0; margin-bottom: 4px; }
.mpj fieldset.mpj-f .grw-btn { align-self: flex-start; }
.mpj-danger { color: #b0361c; border-color: #e6b8ab; }
.mpj-card { border-top: 1px solid #efeee9; padding-top: 12px; display: flex; flex-direction: column; gap: 8px; }
.grw-card > .mpj-card:first-of-type { border-top: 0; padding-top: 0; }
.mpj-head h4 { margin: 0; font-size: 16px; font-weight: 700; color: #0b0b0c; }
.mpj-when { margin: 4px 0 6px; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; font-size: 13px; color: #5b5b62; }
.mpj-cd { font-size: 15px; font-weight: 700; color: #45454d; }
.mpj-cd.is-ok { color: #1d6b30; } .mpj-cd.is-soon { color: #7a5600; } .mpj-cd.is-over { color: #b0361c; }
.mpj-bar { display: block; height: 6px; border-radius: 999px; background: #efeee9; overflow: hidden; }
.mpj-bar > span { display: block; height: 100%; border-radius: 999px; background: #0b0b0c; }
.mpj-detail, .mpj-meta { margin: 0; font-size: 13.5px; line-height: 1.45; color: #45454d; }
.mpj-people { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.mpj-people > li { display: inline-flex; align-items: center; gap: 6px; min-height: 32px; padding: 0 10px; border-radius: 999px; background: #f4f4f2; font-size: 13px; color: #2b2b30; }
.mpj-people > li.is-done > i { color: #1d6b30; }
.mpj-mark { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 8px; }
.mpj-mark .mpj-f { flex: 1 1 220px; }
.mpj-done { margin: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 12px; background: #e9f6ec; color: #1d6b30; font-size: 13.5px; }
.mpj-group h5, .mpj-who h5 { margin: 6px 0 4px; font-size: 13px; font-weight: 600; color: #0b0b0c; }
.mpj-group h5 small, .mpj-f small, .mpj fieldset legend small { font-weight: 400; color: #5b5b62; }
.mpj-parts { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.mpj-parts > li { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 4px 0; border-bottom: 1px solid #f4f4f2; }
.mpj-who-n { display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 8px; font-size: 14px; color: #0b0b0c; min-width: 0; }
.mpj-who-n em { font-style: normal; font-size: 12px; color: #5b5b62; }
.mpj-who-n small { flex-basis: 100%; font-size: 12.5px; color: #5b5b62; }
.mpj select, .mpj input:not([type="checkbox"]), .mpj textarea { min-height: 44px; padding: 0 10px; border: 1px solid #d6d4cc; border-radius: 10px; background: #fff; font: inherit; font-size: 15px; color: #0b0b0c; }
.mpj textarea { padding: 10px; line-height: 1.45; resize: vertical; }
.mpj-acts { display: flex; flex-wrap: wrap; gap: 8px; }
.mpj-form { display: flex; flex-direction: column; gap: 12px; }
.mpj-f { display: flex; flex-direction: column; gap: 4px; font-size: 13px; font-weight: 600; color: #2b2b30; }
.mpj-dates { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.mpj fieldset { margin: 0; padding: 0; border: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.mpj fieldset legend { padding: 0; margin-bottom: 6px; font-size: 13px; font-weight: 600; color: #2b2b30; }
.mpj fieldset.mpj-who { flex-direction: column; align-items: stretch; }
.mpj-chip { display: inline-flex; align-items: center; gap: 2px; min-height: 32px; padding: 0 4px 0 12px; border-radius: 999px; background: #f4f4f2; font-size: 13px; }
.mpj-chip button { width: 44px; height: 44px; border: 0; background: none; border-radius: 50%; cursor: pointer; color: #45454d; }
.mpj-addg { display: inline-flex; gap: 6px; flex-wrap: wrap; }
.mpj-search { display: flex; align-items: center; gap: 8px; }
.mpj-search input { flex: 1; }
.mpj-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; max-height: 340px; overflow: auto; }
.mpj-pick { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 2px 6px; border-radius: 10px; }
.mpj-pick.is-on { background: #f4f4f2; }
.mpj-pick label { display: flex; align-items: center; gap: 10px; min-height: 44px; flex: 1; cursor: pointer; font-size: 14px; }
.mpj-pick label input { width: 20px; height: 20px; }
.mpj-pick label em { font-style: normal; font-size: 12px; color: #5b5b62; }
@container (max-width: 420px) { .mpj-dates { grid-template-columns: 1fr; } }
.grw-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.mpg-wrap { overflow-x: auto; }
.mpg-t { width: 100%; border-collapse: collapse; font-size: 14px; }
.mpg-t th, .mpg-t td { padding: 8px 10px; text-align: left; border-top: 1px solid #f0efea; white-space: nowrap; font-variant-numeric: tabular-nums; }
.mpg-t thead th { border-top: 0; font-size: 12.5px; font-weight: 600; color: #5b5b62; }
.mpg-name { min-height: 44px; padding: 0; border: 0; background: none; font: inherit; font-weight: 600; color: #0b0b0c; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }
.mpg-t .is-up { color: #1d6b30; }
.mpg-t .is-down { color: #8a2a14; }
.mpg-d { font-size: 12.5px; }

/* Getting started (Today): a short first-week list, read from the record. */
.m9x-start { display: flex; flex-direction: column; gap: 12px; padding: 18px; border-radius: 20px; background: #fff; border: 1px solid #e6e5e0; container-type: inline-size; }
.m9x-start-top { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.m9x-start-h { margin: 0; flex: 1; font-size: 17px; font-weight: 700; color: #0b0b0c; }
.m9x-start-n { font-size: 14px; color: #4a4a50; }
.m9x-start-bar { height: 8px; border-radius: 999px; background: #ecebe6; overflow: hidden; }
.m9x-start-bar > span { display: block; height: 100%; background: #1d6b30; border-radius: inherit; }
.m9x-start-list { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; }
.m9x-start-i { display: flex; align-items: center; gap: 12px; min-height: 56px; padding: 8px 0; border-top: 1px solid #f0efea; }
.m9x-start-i > i { font-size: 22px; color: #4a4a50; flex-shrink: 0; }
.m9x-start-i.is-done > i { color: #1d6b30; }
.m9x-start-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; font-size: 14px; color: #4a4a50; }
.m9x-start-tx b { font-size: 15px; color: #0b0b0c; }
.m9x-start-i.is-done .m9x-start-tx b { color: #3f3f46; }
.m9x-start-go { flex-shrink: 0; display: inline-flex; align-items: center; min-height: 44px; padding: 0 14px; border-radius: 12px; border: 1px solid #0b0b0c; background: #fff; color: #0b0b0c;
  font: 600 14px 'Geist', system-ui, sans-serif; text-decoration: none; cursor: pointer; }
.m9x-start-go:focus-visible, .m9x-start-hide:focus-visible { outline: 3px solid #0b0b0c; outline-offset: 2px; }
.m9x-start-hide { align-self: flex-start; min-height: 44px; padding: 0 4px; border: 0; background: none; color: #3f3f46; font: 500 14px 'Geist', system-ui, sans-serif; text-decoration: underline; cursor: pointer; }
/* On a phone the step's words take the row and its button goes under them:
   flex-wrap alone never wrapped, because a min-width: 0 text column shrinks
   to let the button sit beside it, three words a line. */
@container (max-width: 420px) { .m9x-start-i { flex-wrap: wrap; } .m9x-start-tx { flex: 1 1 calc(100% - 34px); } .m9x-start-go { margin-left: 34px; } }

/* Member portal · My mentor. The next-session banner stacks rather than
   truncates: label, the date (which may wrap), the countdown in the reading
   face, and the Prepare action, which drops below when the row is narrow. */
.m9x-sess { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 12px; padding: 12px 14px; border-radius: 14px; background: #f4f4f2; }
.m9x-sess > i { flex-shrink: 0; align-self: flex-start; margin-top: 2px; font-size: 22px; color: var(--m9-accent, #0b0b0c); }
.m9x-sess-txt { flex: 1 1 180px; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.m9x-sess-k { font-size: 12.5px; color: #5f5f66; }
.m9x-sess-d { font-size: 15px; font-weight: 600; line-height: 1.3; overflow-wrap: anywhere; }
.m9x-sess-cd { font-size: 13.5px; color: #3a3a40; font-variant-numeric: tabular-nums; }
.m9x-sess-go { flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 44px; padding: 0 16px; border: 0; border-radius: 10px; background: #0b0b0c; color: #fff; font-size: 14px; font-weight: 600; cursor: pointer; white-space: nowrap; }
.m9x-sess-go:focus-visible { outline: 3px solid #f5b026; outline-offset: 2px; }
@container (max-width: 420px) { .m9x-sess-go { flex: 1 1 100%; } }

/* ══ Member portal · Messages (the Mentor screen's chat) ═════════════════════
   A messaging screen, not a card on a page: the conversation fills the height
   it is given (--m9c-h, measured by Mp9Portal.chatFit), scrolls on its own and
   keeps the composer pinned; a side panel holds the mentor, the next session
   and the other mentor tabs. Below 820px of its own width the side panel goes
   away and the conversation is the whole screen. */
.m9c { --m9c-ink: #0b0b0c; --m9c-ink2: #3f3f46; --m9c-ink3: #5f5f66; --m9c-line: #e6e5e0; --m9c-soft: #f4f4f2; --m9c-accent: #6d28d9;
  display: flex; gap: 20px; align-items: flex-start; container-type: inline-size; container-name: m9c; }
/* A flex row, not a grid: a container query styles the container's children, never the container,
   so the side panel is what collapses — the conversation simply takes the room. */
.m9c-convo { flex: 1; min-width: 0; display: flex; flex-direction: column; height: var(--m9c-h, 680px); min-height: 440px; background: #fff; border: 1px solid var(--m9c-line); border-radius: 20px; overflow: hidden; }
.m9c-head { display: flex; align-items: center; gap: 14px; padding: 16px 20px; border-bottom: 1px solid var(--m9c-line); }
.m9c-head-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.m9c-name { margin: 0; font-size: 19px; font-weight: 700; color: var(--m9c-ink); }
.m9c-sub { display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--m9c-ink3); }
.m9c-dot { width: 9px; height: 9px; border-radius: 50%; flex-shrink: 0; }
.m9c-dot.is-open { background: #1d8a3f; } .m9c-dot.is-closed { background: #a1a1a8; }
.m9c-safe { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--m9c-ink3); white-space: nowrap; }
/* The next session is one quiet row that opens Sessions — not a second black button competing with Send. */
.m9c-next { display: none; align-items: center; gap: 10px; width: 100%; min-height: 52px; padding: 8px 16px; border: 0; border-bottom: 1px solid var(--m9c-line); background: #fbfbf9;
  color: var(--m9c-ink); font: 400 14px 'Geist', system-ui, sans-serif; text-align: left; cursor: pointer; }
.m9c-next:hover { background: var(--m9c-soft); }
.m9c-next:focus-visible { outline: 3px solid var(--m9c-accent); outline-offset: -3px; }
.m9c-next > i { font-size: 20px; color: var(--m9c-ink2); }
.m9c-next-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; } .m9c-next-tx > span { font-size: 12.5px; color: var(--m9c-ink3); font-variant-numeric: tabular-nums; }
.m9c-next-tx b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.m9c-next-go { flex-shrink: 0; display: inline-flex; align-items: center; gap: 2px; font-weight: 600; color: var(--m9c-accent); }
.m9c-av { width: 36px; height: 36px; border-radius: 50%; flex-shrink: 0; display: grid; place-items: center; background: var(--m9c-ink); color: #f5b026; font-size: 13px; font-weight: 700; }
.m9c-av-lg { width: 48px; height: 48px; font-size: 16px; }
.m9c-av-xl { width: 72px; height: 72px; font-size: 22px; }
.m9c-log { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 20px 24px 12px; display: flex; flex-direction: column; background: #faf9f6; scroll-behavior: smooth; }
.m9c-log:focus-visible { outline: 3px solid var(--m9c-accent); outline-offset: -3px; }
