.m9c-icon:focus-visible, .m9c-chip:focus-visible, .m9c-btn:focus-visible, .m9c-side-link:focus-visible, .m9c-link:focus-visible, .m9c-read:focus-visible { outline: 3px solid var(--m9c-accent); outline-offset: 2px; }
.m9c-btn { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; padding: 0 16px; border-radius: 12px; border: 0; background: var(--m9c-ink); color: #fff; font: 600 14px 'Geist', system-ui, sans-serif; cursor: pointer; white-space: nowrap; }
