.lq-f { display: grid; gap: 5px; min-width: 0; }
.lq-f > span, .lq-label { font-size: 12.5px; font-weight: 600; color: var(--ink-600, #4a5168); }
.lq-f textarea, .lq-f input {
  width: 100%; min-width: 0; padding: 9px 11px; font-size: 16px; line-height: 1.5;
  border: 1px solid var(--line-cool, #c3c9d4); border-radius: 8px; background: #fff;
  color: var(--ink-900, #1a2233); font-family: inherit; resize: vertical;
