.lq-note, .lq-bad { font-size: 12px; font-style: normal; line-height: 1.45; }
.lq-note { color: var(--ink-500, #5a6488); }
.lq-bad { color: #a3221f; }
.lq-hint { margin: 0; font-size: 12px; color: var(--ink-500, #5a6488); line-height: 1.5; }

.lq-mark { display: grid; gap: 10px; }
