/* ============================================================================
   Portals on a touch screen: one floor, one field size (2026-10-29).

   tests/portals-phone.test.js signs in to every portal on live data and walks
   every destination its navigation offers at 360px and 390px. Its first run
   found 700-odd controls under the 44px touch floor — segmented tabs, filter
   chips, "Add" buttons, the Saturday value chips a mentor taps forty times a
   morning — and fields set at 12.5–15px, which iOS answers by zooming the page
   into the field and not zooming back out. The portals are drawn from compiled
   designs (each class generated from a design's inline style), so the floor
   cannot be fixed design by design without forking them; it is set here, once,
   for touch pointers only. A mouse keeps the designs' denser sizes.

   Not a blanket on everything: inline links inside text stay text, a control
   hidden from assistive tech is not a target, and a checkbox is hit through
   its label. Specificity comes from the :is() list and the :not()s, never from an
   importance flag.
   ========================================================================== */
@media (pointer: coarse) {
  :is(.m9-app, .m15-app, .i6-app, .fp3-app, .cp3-app, .ss3-app, .sd3-app, .cm3-app, .lrn-app)
    :is(button, [role="tab"], select):not([aria-hidden="true"]):not([tabindex="-1"]) { min-height: 44px; }
  :is(.m9-app, .m15-app, .i6-app, .fp3-app, .cp3-app, .ss3-app, .sd3-app, .cm3-app, .lrn-app)
    :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="file"]):not([type="hidden"]), select, textarea) { font-size: 16px; }
  :is(.m9-app, .m15-app, .i6-app, .fp3-app, .cp3-app, .ss3-app, .sd3-app, .cm3-app, .lrn-app)
    :is(input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="file"]):not([type="hidden"]), select) { min-height: 44px; }
  /* A link that stands alone is a control; one inside a sentence is text. */
  :is(.m9-app, .m15-app, .i6-app, .fp3-app, .cp3-app, .ss3-app, .sd3-app, .cm3-app, .lrn-app) a[href]:not(p a):not(li a):not(span a) { min-height: 44px; }
}

/* Mentor portal, Mentees on a phone: a child's name is the row. The design's
   narrow grid (check · name · flags) gave the flag chip the width it wanted
   and the name what was left, so "Oluwatolu…" sat beside "One-to-one
   overdue". The flags go under the name, the name wraps rather than
   truncating, and the search and the sort each get the full width. */
@container (max-width: 600px) {
  .m15-app .m15-9b17b89 { grid-template-columns: 40px minmax(0, 1fr); row-gap: 2px; padding: 8px 14px 10px 6px; }
  .m15-app .m15-9b17b89 > .m15-0b2b64b { grid-column: 2; justify-content: flex-start; padding-left: 46px; }
  .m15-app .m15-9b17b89 .m15-5949b3a { white-space: normal; overflow-wrap: anywhere; }
  .m15-app .m15-768764a > .m15-f782820 { flex: 1 1 calc(100% - 56px); max-width: none; min-width: 0; }
  .m15-app .m15-768764a > .m15-97445a8 { display: none; }
  .m15-app .m15-768764a > .m15-eca4a53 { flex: 1 1 100%; }
}

/* Club portal on a phone. Its <main> is a scrolling flex column, and a box
   that clips (the "Needs you" and "Status by group" lists are rounded cards
   with overflow hidden) has a minimum height of zero there — so the column
   squeezed them to fit the screen and the last rows were cut off inside
   their own card instead of the page scrolling. Nothing in that column may
   shrink; the column scrolls. */
.cp3-app .cp3-4fe69f6 > * { flex-shrink: 0; }

/* Member portal, My course on a phone: a lesson's title is the row. Week,
   icon, title and state on one line left the title three words wide; the
   state ("To catch up", "Done 80%") goes under the title instead. */
@container (max-width: 600px) {
  .m9-app .m9-efc4855 { display: grid; grid-template-columns: 40px 22px minmax(0, 1fr); column-gap: 10px; row-gap: 2px; align-items: start; padding: 10px 14px; }
  .m9-app .m9-efc4855 > .m9-18477a2 { width: auto; padding-top: 2px; }
  .m9-app .m9-efc4855 > .m9-71241bc { grid-column: 3; text-align: left; }
}
/* The skip link sits outside every portal's root, so the touch floor above
   does not reach it; it is a real target the moment it is focused. */
@media (pointer: coarse) { .skip-link { min-height: 44px; display: inline-flex; align-items: center; } }

/* Community, the quote carousel's position dots on a touch screen: each dot
   is a button, so it takes the 44px floor — and its fill took all of it, a
   black pill the height of a thumb in the middle of the card. The button
   keeps the tall hit area; the dot is drawn inside it, 8px, as designed. */
@media (pointer: coarse) {
  .cm3-app .cm3-e3d8434 { position: relative; background: transparent; }
  .cm3-app .cm3-e3d8434::before { content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 8px; margin-top: -4px; border-radius: 999px; background: var(--dc-background, #0b0b0c); }
}

/* ── Push notifications (NggPushCard / NggPushNudge, components.jsx) ──────────
   One component in three portals (member, family, Control Room), all light
   surfaces with near-black ink, so it carries its own quiet palette rather
   than borrowing any one portal's tokens. Container-sized, not window-sized:
   the card sits in a 400px panel in one portal and a wide page in another. */
.ngp { --ngp-ink: #0b0b0c; --ngp-ink2: #55555c; --ngp-line: #e8e5dd; --ngp-soft: #f6f5f1;
  container-type: inline-size; background: #fff; color: var(--ngp-ink); border: 1px solid var(--ngp-line);
  border-radius: 16px; padding: 16px; display: grid; gap: 12px; font-size: 14px; line-height: 1.45; }
.ngp.is-compact { border-radius: 12px; padding: 12px 14px; }
.ngp button, .ngp input { font: inherit; }
.ngp button:focus-visible, .ngp input:focus-visible, .ngp-nudge button:focus-visible { outline: 2px solid var(--ngp-ink, #0b0b0c); outline-offset: 2px; }
.ngp-head { display: flex; align-items: center; gap: 12px; }
.ngp-head-t { flex: 1; min-width: 0; }
.ngp-ic { width: 36px; height: 36px; border-radius: 10px; background: var(--ngp-soft, #f6f5f1); display: grid; place-items: center; font-size: 18px; flex: none; }
.ngp-h { margin: 0; font-size: 15px; font-weight: 650; }
.ngp-sub { margin: 2px 0 0; font-size: 13px; color: var(--ngp-ink2); }
.ngp-p { margin: 0; color: var(--ngp-ink2); }
.ngp-why { background: var(--ngp-soft); border-radius: 10px; padding: 10px 12px; color: var(--ngp-ink); }
.ngp-off { display: grid; gap: 10px; justify-items: start; }
.ngp-row { display: flex; flex-wrap: wrap; gap: 8px; }
.ngp-btn { min-height: 40px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--ngp-line, #e8e5dd); background: #fff; color: var(--ngp-ink, #0b0b0c); font-weight: 600; cursor: pointer; }
.ngp-btn.is-primary { background: var(--ngp-ink, #0b0b0c); border-color: var(--ngp-ink, #0b0b0c); color: #fff; }
.ngp-btn:disabled { opacity: .55; cursor: default; }
.ngp-link { background: none; border: 0; padding: 4px 2px; color: var(--ngp-ink); font-weight: 600; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }
.ngp-prefs { display: grid; gap: 10px; border-top: 1px solid var(--ngp-line); padding-top: 12px; }
.ngp-pref { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 36px; }
.ngp-pref > div { display: grid; gap: 2px; }
.ngp-pref small { color: var(--ngp-ink2); font-size: 13px; }
.ngp-sw { position: relative; width: 44px; height: 26px; flex: none; border-radius: 999px; border: 0; background: #85827a; cursor: pointer; padding: 0; }
.ngp-sw span { position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; transition: transform .15s ease; }
.ngp-sw.is-on { background: var(--ngp-ink, #0b0b0c); }
.ngp-sw.is-on span { transform: translateX(18px); }
@media (prefers-reduced-motion: reduce) { .ngp-sw span { transition: none; } }
.ngp-times { display: flex; flex-wrap: wrap; gap: 12px; }
.ngp-times label { display: grid; gap: 4px; font-size: 13px; color: var(--ngp-ink2); }
.ngp-times input { min-height: 40px; padding: 0 10px; border: 1px solid var(--ngp-line); border-radius: 10px; background: #fff; color: var(--ngp-ink); }
.ngp-topics { border: 0; margin: 0; padding: 0; display: grid; gap: 4px; }
.ngp-topics legend { padding: 0; margin-bottom: 4px; font-weight: 650; }
.ngp-devs { display: grid; gap: 4px; justify-items: start; }
.ngp-note { margin: 0; font-size: 13px; color: var(--ngp-ink2); min-height: 0; }
.ngp-note:empty { display: none; }
.ngp-state { display: grid; gap: 8px; justify-items: start; }
.ngp-skel { display: grid; gap: 8px; }
.ngp-skel span { height: 12px; border-radius: 6px; background: var(--ngp-soft); }
.ngp-skel span:last-child { width: 60%; }
@container (max-width: 340px) { .ngp-pref { align-items: flex-start; } .ngp-row .ngp-btn { flex: 1 1 100%; } }

.ngp-nudge { --ngp-ink: #0b0b0c; --ngp-ink2: #55555c; --ngp-line: #e8e5dd; --ngp-soft: #fdf3dc;
  container-type: inline-size; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 14px; padding: 14px 16px;
  border-radius: 16px; background: #fffaf0; border: 1px solid #f1dfb4; color: var(--ngp-ink); font-size: 14px; line-height: 1.45; }
.ngp-nudge button { font: inherit; }
.ngp-nudge-t { flex: 1 1 240px; display: grid; gap: 2px; min-width: 0; }
.ngp-nudge-t small { color: var(--ngp-ink2); font-size: 13px; }
@container (max-width: 420px) { .ngp-nudge .ngp-row { width: 100%; } .ngp-nudge .ngp-btn { flex: 1; } }
.m9n-push { padding: 10px 16px 14px; border-top: 1px solid #ececea; }
.fp3x-push { margin-top: 16px; }
.cr-push-wrap { padding: 4px 0; }
.cr-ib-push { padding: 8px 12px 0; }

/* ── The notice editor (cr-tab-comms.jsx NoticeEditor) ──────────────────────
   A document editor, not a form: the page is the notice (.nt-paper.nt-doc, the
   same drawing members read), set on a quiet desk, with a slim toolbar above
   it and the sending choices in a rail beside it — a sheet when the editor is
   narrower than page + rail. Widths are the editor's own (a container), not
   the window's. */
.nte { position: fixed; inset: 0; z-index: 42;   /* above the shell and its menus (≤40), below the Control Room's forms (46), confirms (65) and toasts (70) */ display: flex; flex-direction: column; background: var(--cr-s2); font-family: var(--cr-font); color: var(--cr-ink); container-type: inline-size; container-name: nte; }
.nte-bar { display: flex; align-items: center; gap: 8px; padding: 10px 16px; background: var(--cr-bg); border-bottom: 1px solid var(--cr-line); flex: none; }
.nte-grow { flex: 1; }
.nte-state { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--cr-muted-3); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nte-state.is-saved { color: var(--cr-ok-fg); }
.nte-state.is-error { color: var(--cr-danger); }
.nte-state.is-saving .ph { animation: nte-spin 1s linear infinite; }
@keyframes nte-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .nte-state.is-saving .ph { animation: none; } }
.nte-count { font-size: 12.5px; color: var(--cr-muted-3); font-variant-numeric: tabular-nums; white-space: nowrap; }
.nte-banner { display: flex; gap: 8px; align-items: flex-start; padding: 10px 16px; background: var(--cr-banner-bg); border-bottom: 1px solid var(--cr-banner-line); color: var(--cr-banner-fg); font-size: 13.5px; line-height: 1.45; flex: none; }
.nte-banner .ph { margin-top: 2px; }
.nte-banner.is-bad { background: var(--cr-bad-bg); border-bottom-color: var(--cr-bad-bg); color: var(--cr-bad-fg); align-items: center; flex-wrap: wrap; }
.nte-sched { display: inline-flex; align-items: center; gap: 4px; font-size: 12.5px; color: var(--cr-warn-fg); background: var(--cr-warn-bg); border-radius: var(--cr-r-pill); padding: 2px 10px; white-space: nowrap; }
.nte-count.is-warn { color: var(--cr-warn-fg); font-weight: 600; }
.nte-side-warn { margin: 8px 18px 0; }
.nte-when { display: flex; flex-direction: column; gap: 8px; }
.nte-when-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.nte-when-row .nte-lbl { display: flex; flex-direction: column; gap: 4px; }
.nte-hint { font-size: 12.5px; color: var(--cr-muted-3); }
.nte-work { flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 320px; }
.nte-desk { overflow-y: auto; padding: 24px 24px 72px; display: flex; flex-direction: column; align-items: center; gap: 12px; }
.nte-desk > * { width: 100%; max-width: 780px; }
/* The formatting band sits between the bar and the desk, never over the words. */
.nte-format { flex: none; display: flex; padding: 6px 16px; background: var(--cr-bg); border-bottom: 1px solid var(--cr-line); overflow-x: auto; }
.nte-tools { display: flex; align-items: center; gap: 2px; flex: none; margin: 0 auto; }   /* auto margins centre it and, unlike justify-content, never clip its start when it overflows */
.nte-tool { width: 36px; height: 36px; display: inline-grid; place-items: center; border: 0; border-radius: var(--cr-r-sm); background: transparent; color: var(--cr-muted); font-size: 18px; }
.nte-tool:hover { background: var(--cr-s2); color: var(--cr-ink); }
.nte-tool[aria-pressed="true"] { background: var(--cr-nav-on); color: var(--cr-ink); }
.nte-tool.is-label { width: auto; display: inline-flex; gap: 6px; padding: 0 10px; font-size: 13px; font-weight: 500; }
.nte-tool.is-label .ph { font-size: 16px; }
.nte-tool:focus-visible, .nte-add:focus-visible, .nte-x:focus-visible { outline: 2px solid var(--cr-ink); outline-offset: 1px; }
.nte-sep { width: 1px; height: 20px; background: var(--cr-line-3); margin: 0 4px; }
.nte-paper { min-height: 60vh; position: relative; box-shadow: var(--cr-sh-switch); }
.nte-in { display: block; width: 100%; border: 0; background: transparent; padding: 2px 0; margin: 0; color: inherit; text-align: inherit; border-radius: 4px; }
.nte-in::placeholder { color: var(--cr-faint); }
.nte-in:focus { outline: none; background: var(--cr-s4); }
.nte-head { position: relative; }
/* The × sits inside the letterhead's own box (it used to hang 6px out, past the page on a phone); the two lines keep clear of it on both sides so they stay centred. */
.nte-head .nte-in.nt-org, .nte-head .nte-in.nt-kind { padding-left: 36px; padding-right: 36px; }
.nte-head .nte-in.nt-org { margin-bottom: 4px; }
.nte-head .nte-in.nt-kind { margin-bottom: 14px; }
.nte-subj { display: flex; align-items: baseline; gap: 8px; }
.nte-subj.is-official { justify-content: center; text-align: center; padding-bottom: 16px; border-bottom: 2px solid var(--cr-ink); margin-bottom: 18px; }
.nte-subj-k { font: 600 clamp(18px, 2.6vw, 22px)/1.3 var(--c-font-display, sans-serif); flex: none; }
.nte-subj .nte-in.nt-subject { resize: none; overflow: hidden; font-size: 26px; line-height: 1.25; }
.nte-subj.is-official .nte-in.nt-subject { font-size: clamp(18px, 2.6vw, 22px); text-align: left; width: auto; flex: 1; max-width: 560px; }
.nte-subj:not(.is-official) { margin: 4px 0 14px; }
.nte-body { min-height: 180px; outline: none; border-radius: 4px; caret-color: var(--cr-ink); }
/* The page is the field: its caret is the focus, as in a document — the Control Room's 2px ring (.cr-app :focus-visible) would box the notice in. */
.nte .nte-paper .nte-body:focus-visible { outline: none; }
.nte .nte-paper .nte-in:focus-visible { outline: none; }
.nte-body.is-empty::before { content: attr(data-ph); color: var(--cr-faint); pointer-events: none; display: block; }
.nte-body.is-empty:focus::before { color: var(--cr-faint-2); }
.nte-add { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 10px; margin: 0 0 14px; border: 1px dashed var(--cr-line-strong); border-radius: var(--cr-r-sm); background: transparent; color: var(--cr-muted); font-size: 13px; width: auto; }
.nte-add em { font-style: normal; color: var(--cr-muted-3); }
.nte-add:hover { border-color: var(--cr-ink); color: var(--cr-ink); }
.nte-add.is-sign { margin: 24px 0 0; }
.nte-x { position: absolute; top: 0; right: 0; width: 32px; height: 32px; display: inline-grid; place-items: center; border: 0; border-radius: var(--cr-r-sm); background: transparent; color: var(--cr-muted-3); }
.nte-x:hover { background: var(--cr-s2); color: var(--cr-ink); }
.nte-signrow { position: relative; margin-top: 24px; }
.nte-signrow .nte-in.nt-sign { margin: 0; padding-right: 36px; }
.nte-signrow .nte-x { top: -2px; right: 0; }
.nte-err { color: var(--cr-danger); font-size: 13px; margin: 6px 0 0; }
.nte-wait { color: var(--cr-muted-3); font-size: 13px; margin: 0; text-align: center; }
.nte-side { background: var(--cr-bg); border-left: 1px solid var(--cr-line); overflow-y: auto; display: flex; flex-direction: column; }
.nte-side-head { display: none; }
.nte-side-in { display: flex; flex-direction: column; }
.nte-sec { padding: 16px 18px; border-bottom: 1px solid var(--cr-line-4); display: flex; flex-direction: column; gap: 8px; }
.nte .nte-side .nte-sec-h { font-size: 12.5px; line-height: 1.3; font-weight: 600; color: var(--cr-muted-3); margin: 0 0 2px; }
.nte-lbl { font-size: 13px; font-weight: 500; color: var(--cr-text); }
.nte-lbl i { font-style: normal; color: var(--cr-muted-3); font-weight: 400; }
.nte-select, .nte-input { width: 100%; max-width: none; }
.nte-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.nte-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 4px 0; }
.nte-row b { display: block; font-size: 13.5px; font-weight: 500; }
.nte-row em { display: block; font-style: normal; font-size: 12.5px; color: var(--cr-muted-3); line-height: 1.4; margin-top: 2px; }
.nte-fixed { margin: 0; font-size: 13.5px; }
.nte-fixed span { display: block; font-size: 12.5px; color: var(--cr-muted-3); margin-top: 4px; }
.nte-help ul { margin: 0; padding-left: 18px; font-size: 12.5px; line-height: 1.5; color: var(--cr-muted); display: flex; flex-direction: column; gap: 6px; }
.nte-help kbd { font-family: var(--cr-mono); font-size: 11.5px; padding: 0 4px; border: 1px solid var(--cr-line-3); border-radius: 4px; background: var(--cr-s4); }
/* What will happen, in a sentence, before any of the choices that decide it. */
.nte-sum { display: flex; gap: 10px; align-items: flex-start; margin: 14px 14px 2px; padding: 12px 14px; background: var(--cr-s4); border-radius: var(--cr-r); font-size: 13px; line-height: 1.45; }
.nte-sum > .ph { font-size: 18px; margin-top: 1px; color: var(--cr-muted); }
.nte-sum b { display: block; font-weight: 600; font-size: 13.5px; }
.nte-sum em { display: block; font-style: normal; color: var(--cr-muted); }
.nte-help summary { cursor: pointer; font-size: 13px; font-weight: 500; color: var(--cr-muted); list-style-position: inside; }
.nte-help summary:hover { color: var(--cr-ink); }
.nte-help[open] summary { margin-bottom: 8px; }
.nte-sheet-l { max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nte-sheet-btn { display: none; }
@container nte (max-width: 900px) {
  .nte-work { grid-template-columns: minmax(0, 1fr); }
  .nte-sheet-btn { display: inline-flex; }
  .nte-side { position: absolute; left: 0; right: 0; bottom: 0; max-height: 80%; border-left: 0; border-top: 1px solid var(--cr-line); border-radius: var(--cr-r-xl) var(--cr-r-xl) 0 0; box-shadow: var(--cr-sh-sheet); transform: translateY(105%); transition: transform .2s var(--cr-ease); z-index: 3; visibility: hidden; }
  .nte-side.is-open { transform: none; visibility: visible; }
  .nte-side-head { display: flex; align-items: center; justify-content: space-between; padding: 12px 18px 4px; position: relative; }
  .nte-side-head .nte-x { position: static; }
}
@container nte (max-width: 560px) {
  .nte-bar { flex-wrap: wrap; padding: 8px 12px; row-gap: 6px; }
  .nte-bar .nte-sheet-btn { margin-left: auto; }
  .nte-count { display: none; }
  .nte-format { padding: 4px 8px; }
  .nte-tool.is-label { width: 36px; padding: 0; }
  .nte-tool.is-label span { display: none; }
  .nte-desk { padding: 12px 10px 72px; }
  .nte-subj .nte-in.nt-subject { font-size: 22px; }
}

/* Diagnostics → a lost photo's Cloudinary picks (CrSyPhotoRecover). */
.cr-sy-cloud { list-style: none; margin: 10px 0 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.cr-sy-cloud-row { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }
.cr-sy-cloud-who { flex: 1 1 200px; min-width: 0; }
.cr-sy-cloud-picks { display: flex; flex-wrap: wrap; gap: 6px; }
.cr-sy-cloud-pick { padding: 0; border: 1px solid var(--cr-line-strong); border-radius: var(--cr-r); overflow: hidden; background: none; cursor: pointer; width: 48px; height: 48px; }
.cr-sy-cloud-pick:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
.cr-sy-cloud-pick img { display: block; width: 48px; height: 48px; object-fit: cover; }

/* ── A member's account, as a statement (cr-tab-money.jsx, CrMoAccountSummary) ──
   What is payable on the left; on the right the sum that makes it — charged by
   kind, less received by kind — so the figure can be checked on the page.
   Side by side when the block is wide enough, stacked when it is not: the
   block's own width decides, not the window's. */
.cr-block:has(> .cr-stmt), .cr-pblock:has(> .cr-stmt) { container-type: inline-size; }
.cr-stmt { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; border: 1px solid var(--cr-line); border-radius: var(--cr-r-lg); background: var(--cr-bg); padding: 20px; }
@container (min-width: 720px) { .cr-stmt { grid-template-columns: minmax(0, 1fr) minmax(300px, 380px); gap: 32px; } }
.cr-stmt-due { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.cr-stmt-k { font-size: 13px; color: var(--cr-muted-3); }
.cr-stmt-big { font-size: 34px; font-weight: 650; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; color: var(--cr-ink); line-height: 1.15; }
.cr-stmt-sub { font-size: 13.5px; color: var(--cr-muted-3); }
.cr-stmt-facts { margin: 14px 0 0; display: flex; flex-direction: column; gap: 8px; border-top: 1px solid var(--cr-line-4); padding-top: 12px; }
.cr-stmt-facts div { display: grid; grid-template-columns: 96px minmax(0, 1fr); gap: 12px; align-items: center; font-size: 13.5px; }
.cr-stmt-facts dt { color: var(--cr-muted-3); }
.cr-stmt-facts dd { margin: 0; color: var(--cr-ink); display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.cr-recon { width: 100%; border-collapse: collapse; font-size: 13.5px; align-self: start; }
.cr-recon th { text-align: left; font-weight: 400; color: var(--cr-ink); padding: 5px 0; }
.cr-recon td { text-align: right; font-variant-numeric: tabular-nums; padding: 5px 0; white-space: nowrap; }
.cr-recon tr.is-head th { font-size: 12.5px; font-weight: 600; color: var(--cr-muted-3); padding-top: 12px; }
.cr-recon tr.is-head:first-child th { padding-top: 0; }
.cr-recon tr:not(.is-head):not(.is-total):not(.is-grand) th { padding-left: 12px; color: var(--cr-muted-2); }
.cr-recon tr.is-total th, .cr-recon tr.is-total td { font-weight: 600; border-top: 1px solid var(--cr-line-4); }
.cr-recon tr.is-grand th, .cr-recon tr.is-grand td { font-weight: 650; font-size: 15px; border-top: 2px solid var(--cr-ink); padding-top: 9px; }

/* ── The debt book: how long the money has been owed (crMoOwesBlocks) ──
   A single bar split by age, and a legend that is also the sum: the bands
   add up to the total on the line below them. */
.cr-age { display: grid; grid-template-columns: minmax(0, 1fr); gap: 14px; border: 1px solid var(--cr-line); border-radius: var(--cr-r-lg); background: var(--cr-bg); padding: 20px; }
@container (min-width: 720px) { .cr-age { grid-template-columns: minmax(0, 1fr) minmax(300px, 380px); column-gap: 32px; } .cr-age-legend { grid-row: 1 / span 2; grid-column: 2; } }
.cr-block:has(> .cr-age), .cr-pblock:has(> .cr-age) { container-type: inline-size; }
.cr-age-top { display: flex; flex-direction: column; gap: 4px; }
.cr-age-bar { display: flex; height: 14px; border-radius: var(--cr-r-pill); overflow: hidden; background: var(--cr-s2); gap: 2px; }
.cr-age-seg { display: block; min-width: 4px; }
.cr-age-seg.is-current, .cr-age-dot.is-current { background: var(--cr-ok-dot); }
.cr-age-seg.is-d31, .cr-age-dot.is-d31 { background: var(--cr-warn-dot); }
.cr-age-seg.is-d61, .cr-age-dot.is-d61 { background: var(--cr-warn-fg); }
.cr-age-seg.is-d90, .cr-age-dot.is-d90 { background: var(--cr-bad-dot); }
.cr-age-dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 8px; vertical-align: 1px; }
.cr-age-legend tr:not(.is-grand) th { padding-left: 0; color: var(--cr-ink); }
.cr-age-pct { width: 52px; color: var(--cr-muted-3); }

/* ── Transactions: the filter bar (crMoJournalBlocks) ── */
.cr-jfilter { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 10px 12px; border: 1px solid var(--cr-line); border-radius: var(--cr-r-lg); background: var(--cr-bg); padding: 14px 16px; }
.cr-jfilter label { display: flex; flex-direction: column; gap: 4px; font-size: 12.5px; color: var(--cr-muted-3); min-width: 140px; }
.cr-jfilter label.is-grow { flex: 1 1 220px; }
.cr-jfilter .cr-select { max-width: none; }
.cr-jfilter .cr-input { height: 36px; padding: 0 10px; border: 1px solid var(--cr-line-3); border-radius: var(--cr-r); font-size: 14px; background: var(--cr-bg); color: var(--cr-ink); }

/* ── Money that could not be applied: one line each, with its decision (Membership payments) ── */
.cr-mp-unapplied p { margin: 2px 0 8px; font-size: 13px; }
.cr-mp-unapplied ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.cr-mp-unapplied li { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 6px 12px; padding-top: 8px; border-top: 1px solid var(--cr-line-4); }
.cr-mp-unapplied-acts { display: flex; flex-wrap: wrap; gap: 6px; }
/* ── The registration checklist in the portals (mp15-registration.jsx) ──────
   The supervisor's "My registrations" in the Mentor Portal, and the member's
   and guardian's progress card. The portals' own light palette, declared once
   here as tokens; every rule below reads them. The bar is a native <progress>. */
.rcl-desk, .rcl-card {
  --rcl-ink: #0b0b0c; --rcl-ink-2: #5a5a60; --rcl-line: #e8e5dd; --rcl-surface: #fff; --rcl-sink: #f4f4f2;
  --rcl-ok: #1d6b30; --rcl-ok-bg: #edf7ef; --rcl-bad: #8a2a16; --rcl-bad-bg: #fdeeea;
  --rcl-font: 'Geist', system-ui, sans-serif; --rcl-r: 18px; --rcl-r-ctl: 12px;
}
.rcl-desk { container-type: inline-size; display: flex; flex-direction: column; gap: 16px; font-family: var(--rcl-font); color: var(--rcl-ink); }
.rcl-lead { margin: 0; font-size: 14px; color: var(--rcl-ink-2); }
.rcl-card { container-type: inline-size; margin: 0 0 16px; padding: 16px; border: 1px solid var(--rcl-line); border-radius: var(--rcl-r); background: var(--rcl-surface); color: var(--rcl-ink); font-family: var(--rcl-font); }
.rcl-desk .rcl-card { margin: 0; }
.rcl-card h2 { margin: 0; font-size: 16px; font-weight: 600; line-height: 1.3; }
.rcl-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.rcl-head span, .rcl-meta { font-size: 13.5px; color: var(--rcl-ink-2); }
.rcl-meta { margin: 6px 0; line-height: 1.45; }
.rcl-state { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.rcl-state p { flex: 1; min-width: 200px; margin: 0; font-size: 14px; line-height: 1.45; }
.rcl-bar { appearance: none; display: block; width: 100%; height: 8px; margin: 8px 0; border: 0; border-radius: 999px; background: var(--rcl-sink); overflow: hidden; }
.rcl-bar::-webkit-progress-bar { background: var(--rcl-sink); border-radius: 999px; }
.rcl-bar::-webkit-progress-value { background: var(--rcl-ok); border-radius: 999px; }
.rcl-bar::-moz-progress-bar { background: var(--rcl-ok); border-radius: 999px; }
.rcl-left { margin: 0 0 6px; padding-left: 20px; font-size: 14px; line-height: 1.5; }
.rcl-items { list-style: none; margin: 8px 0 0; padding: 0; }
.rcl-item { display: grid; grid-template-columns: 24px 1fr auto; align-items: start; gap: 10px; padding: 12px 0; border-top: 1px solid var(--rcl-line); }
.rcl-item > i { font-size: 20px; line-height: 1.2; color: var(--rcl-ink-2); }
.rcl-item.is-done > i { color: var(--rcl-ok); }
.rcl-item-body { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.rcl-item-body b { font-size: 14.5px; font-weight: 600; }
.rcl-item-body > span { font-size: 13.5px; line-height: 1.45; color: var(--rcl-ink-2); }
.rcl-item.is-done .rcl-item-body b { font-weight: 500; }
.rcl-why { font-style: italic; }
.rcl-res { margin: 4px 0 0; padding: 8px 10px; border-radius: var(--rcl-r-ctl); font-size: 13.5px; line-height: 1.45; }
.rcl-item-body > .rcl-res.is-ok, .rcl-res.is-ok { background: var(--rcl-ok-bg); color: var(--rcl-ok); }
.rcl-item-body > .rcl-res.is-bad, .rcl-res.is-bad { background: var(--rcl-bad-bg); color: var(--rcl-bad); }
.rcl-btn { min-height: 44px; padding: 0 16px; border: 1px solid var(--rcl-line); border-radius: var(--rcl-r-ctl); background: var(--rcl-surface); color: var(--rcl-ink); font: 600 14px var(--rcl-font); cursor: pointer; }
.rcl-btn.is-main { border-color: var(--rcl-ink); background: var(--rcl-ink); color: var(--rcl-surface); }
.rcl-btn:disabled { opacity: .6; cursor: default; }
.rcl-btn:focus-visible, .rcl-field input:focus-visible, .rcl-field textarea:focus-visible { outline: 2px solid var(--rcl-ink); outline-offset: 2px; }
.rcl-form { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; padding: 12px; border-radius: var(--rcl-r-ctl); background: var(--rcl-sink); }
.rcl-field { display: flex; flex-direction: column; gap: 4px; font-size: 13.5px; font-weight: 600; }
.rcl-field input, .rcl-field textarea { min-height: 44px; padding: 8px 10px; border: 1px solid var(--rcl-line); border-radius: var(--rcl-r-ctl); background: var(--rcl-surface); color: var(--rcl-ink); font: 400 14px var(--rcl-font); }
.rcl-acts { display: flex; gap: 8px; flex-wrap: wrap; }
@container (max-width: 480px) { .rcl-item { grid-template-columns: 24px 1fr; } .rcl-item > .rcl-btn { grid-column: 2; justify-self: start; } }
